-- ============================================================================
-- Language catalog → Supabase
--
-- GENERATED FILE — edit lib/languages.ts (or a lib/*-plus.ts bank) and run
-- `npm run catalog:sql`. Hand edits here are lost on the next build.
--
-- Run once in the Supabase dashboard → SQL editor, after schema.sql:
-- https://supabase.com/dashboard/project/rlulmewvmhxgctonizas/sql
--
-- Safe to re-run: the DDL is idempotent and the seed uses ON CONFLICT DO NOTHING,
-- so a lesson edited in the dashboard is never overwritten by a later run.
--
-- After this runs, the app reads lesson title/theory/questions from these tables
-- through lib/languageCatalog.ts. The bundled catalog stays as the offline and
-- first-run fallback. Editing a row changes the lesson on the next launch (the
-- loader caches for five minutes); no app release is needed.
--
-- 104 lessons · 6 courses.
-- ============================================================================

create table if not exists public.language_courses (
  id text primary key,
  title text not null,
  icon text not null default '',
  blurb text not null default '',
  position integer not null default 0,
  published boolean not null default true,
  updated_at timestamptz not null default now()
);

create table if not exists public.language_lessons (
  id text primary key,
  course_id text not null references public.language_courses (id) on delete cascade,
  title text not null,
  theory jsonb not null default '[]'::jsonb,
  questions jsonb not null default '[]'::jsonb,
  position integer not null default 0,
  published boolean not null default true,
  updated_at timestamptz not null default now(),
  constraint language_lessons_theory_is_array check (jsonb_typeof(theory) = 'array'),
  constraint language_lessons_questions_is_array check (jsonb_typeof(questions) = 'array')
);

create index if not exists language_lessons_course_position
  on public.language_lessons (course_id, position);

create or replace function public.touch_language_catalog()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists language_courses_touch on public.language_courses;
create trigger language_courses_touch
  before update on public.language_courses
  for each row execute function public.touch_language_catalog();

drop trigger if exists language_lessons_touch on public.language_lessons;
create trigger language_lessons_touch
  before update on public.language_lessons
  for each row execute function public.touch_language_catalog();

alter table public.language_courses enable row level security;
alter table public.language_lessons enable row level security;

-- Public read, dashboard/service-role write. Unpublishing a row hides it from
-- the app immediately; the bundled lesson remains as the offline fallback.
drop policy if exists "Anyone can read published language courses" on public.language_courses;
create policy "Anyone can read published language courses"
  on public.language_courses for select using (published);

drop policy if exists "Anyone can read published language lessons" on public.language_lessons;
create policy "Anyone can read published language lessons"
  on public.language_lessons for select using (published);

grant select on public.language_courses, public.language_lessons to anon, authenticated;
grant select on public.language_courses, public.language_lessons to service_role;
grant insert, update, delete on public.language_courses, public.language_lessons to service_role;

comment on table public.language_courses is
  'Language course metadata. Managed in Supabase; read by the app via lib/languageCatalog.ts.';
comment on table public.language_lessons is
  'Lesson content: theory (jsonb string[]) and questions (jsonb CourseQuestion[]). Edits apply without an app release.';

-- Seed: DO UPDATE. The database is what the app reads first, so a row that was
-- seeded before the repo gained richer content (question kinds, listen/speak/
-- match items, new theory) would otherwise shadow the bundle forever: a stale
-- row silently downgraded every language lesson to plain tap-to-choose items.
-- Regenerating and re-running this file is the publish step — it intentionally
-- replaces dashboard edits with the reviewed content in the repo. To keep a
-- dashboard-only change, copy it into lib/languages.ts before publishing.
insert into public.language_courses (id, title, icon, blurb, position, published)
select x.id, x.title, x.icon, x.blurb, x.position, true
from jsonb_to_recordset($catalog_courses$[
  {"id":"spanish","title":"Spanish","icon":"🇪🇸","blurb":"Hold your first conversations","position":1},
  {"id":"french","title":"French","icon":"🇫🇷","blurb":"Charm your way through Paris","position":2},
  {"id":"german","title":"German","icon":"🇩🇪","blurb":"Order, introduce, and apologise","position":3},
  {"id":"swahili","title":"Swahili","icon":"🇰🇪","blurb":"Karibu — speak with East Africa","position":4},
  {"id":"chess","title":"Chess","icon":"♟️","blurb":"From moves to mating nets","position":5},
  {"id":"english","title":"English","icon":"🇬🇧","blurb":"Master English grammar and conversation","position":6}
]$catalog_courses$::jsonb)
  as x(id text, title text, icon text, blurb text, position integer)
on conflict (id) do update set
  title = excluded.title,
  icon = excluded.icon,
  blurb = excluded.blurb,
  position = excluded.position;

insert into public.language_lessons (id, course_id, title, theory, questions, position, published)
select x.id, x.course_id, x.title, x.theory, x.questions, x.position, true
from jsonb_to_recordset($catalog_lessons$[
  {"id":"spanish-basics","course_id":"spanish","title":"Spanish Basics","theory":["Spanish is spoken by 500M+ people. Start the Duolingo way: greetings first — Hola (hello), Adiós (goodbye), Gracias (thank you), Por favor (please).","Every Spanish noun has gender: el for masculine, la for feminine. Niña (girl) is feminine → la niña."],"questions":[{"prompt":"How do you say \"Hello\" in Spanish?","correctChain":["Hola"],"scrambledTokens":["Hola","Adiós","Gracias","Por favor"],"explain":"Hola opens every conversation — nail it first."},{"prompt":"\"Gracias\" means…","correctChain":["Thank you"],"scrambledTokens":["Thank you","Please","Goodbye","Welcome"],"explain":"Gratitude unlocks kindness in every language."},{"prompt":"Say \"I eat apples\":","correctChain":["Yo","como","manzanas"],"scrambledTokens":["manzanas","Yo","el","como"],"explain":"Yo = I, como = (I) eat from comer, manzanas = apples."},{"prompt":"Which article goes with \"niña\" (girl)?","correctChain":["la"],"scrambledTokens":["la","el","los","un"],"explain":"Feminine nouns take la; masculine nouns take el."},{"prompt":"Say goodbye to a friend:","correctChain":["Adiós","amigo"],"scrambledTokens":["amigo","Hola","Adiós","gracias"],"explain":"Adiós = goodbye, amigo = friend."},{"kind":"match","prompt":"Pair each Spanish word with its meaning.","correctChain":["5 pairs"],"scrambledTokens":["Hola → Hello","Adiós → Goodbye","Gracias → Thank you","Por favor → Please","Niña → Girl"],"explain":"Four politeness words plus the gender cue: la niña is feminine, so el article never fits.","match":{"pairs":[{"left":"Hola","right":"Hello"},{"left":"Adiós","right":"Goodbye"},{"left":"Gracias","right":"Thank you"},{"left":"Por favor","right":"Please"},{"left":"Niña","right":"Girl"}]}},{"kind":"listen","prompt":"Listen and type the sentence about apples.","correctChain":["Yo como manzanas"],"scrambledTokens":[],"explain":"Yo = I, como = (I) eat, manzanas = apples — the -o ending is what marks the speaker as \"I\".","listen":{"phrase":"Yo como manzanas","answers":["Yo como manzanas"]}},{"kind":"speak","prompt":"Say goodbye to a friend, out loud.","correctChain":["Adiós amigo"],"scrambledTokens":[],"explain":"The stress sits on the middle syllable — ad-YOS ah-MEE-go — and the accent on adiós lengthens that o.","speak":{"phrase":"Adiós amigo","passScore":75}}],"position":1},
  {"id":"spanish-phrases","course_id":"spanish","title":"Spanish Phrases","theory":["Move past single words: ask how people are (¿Cómo estás?), introduce yourself (Me llamo…), and soften every request with Por favor.","Gratitude scales up: Gracias → Muchas gracias (thank you very much). Goodbyes scale too: Adiós → Hasta luego (see you later)."],"questions":[{"prompt":"\"¿Cómo estás?\" means…","correctChain":["How are you?"],"scrambledTokens":["How are you?","What is your name?","Where are you from?","How old are you?"],"explain":"The go-to greeting right after Hola."},{"prompt":"Say \"My name is Ana\":","correctChain":["Me","llamo","Ana"],"scrambledTokens":["Ana","Yo","Me","llamo"],"explain":"Me llamo = I call myself — the Spanish introduction."},{"prompt":"\"Por favor\" means…","correctChain":["Please"],"scrambledTokens":["Please","Thank you","Sorry","Welcome"],"explain":"Por favor softens every request."},{"prompt":"Say \"Thank you very much\":","correctChain":["Muchas","gracias"],"scrambledTokens":["gracias","Hola","Muchas","por"],"explain":"Muchas = many; gracias = thanks. Stack them for emphasis."},{"prompt":"\"Hasta luego\" means…","correctChain":["See you later"],"scrambledTokens":["See you later","Good night","Good luck","Welcome back"],"explain":"Hasta = until; luego = later. Warmer than Adiós."},{"kind":"match","prompt":"Pair each phrase with what it does in a conversation.","correctChain":["5 pairs"],"scrambledTokens":["¿Cómo estás? → Ask a friend how they are","Me llamo → Introduce yourself","Por favor → Soften a request","Muchas gracias → Thank someone warmly","Hasta luego → Leave for now"],"explain":"Each one is a move in a conversation, not just a translation — greet, name, ask, thank, part.","match":{"pairs":[{"left":"¿Cómo estás?","right":"Ask a friend how they are"},{"left":"Me llamo","right":"Introduce yourself"},{"left":"Por favor","right":"Soften a request"},{"left":"Muchas gracias","right":"Thank someone warmly"},{"left":"Hasta luego","right":"Leave for now"}]}},{"kind":"listen","prompt":"Listen and type how someone says their name.","correctChain":["Me llamo Ana"],"scrambledTokens":[],"explain":"Me llamo = I call myself. No verb changes, no accent — the stress sits on the final a of Ana.","listen":{"phrase":"Me llamo Ana","answers":["Me llamo Ana"]}},{"kind":"speak","prompt":"Thank someone generously, out loud.","correctChain":["Muchas gracias"],"scrambledTokens":[],"explain":"Both words stress the second-to-last syllable: MUCH-ahs GRASH-yahs (Latin America) or GRAH-see-ahs (Spain).","speak":{"phrase":"Muchas gracias","passScore":75}}],"position":2},
  {"id":"spanish-tenses","course_id":"spanish","title":"Spanish Tenses Lab","theory":["Present tense runs on endings: -o = I (hablo), -as = you (hablas), -a = he/she (habla), -amos = we (hablamos), -an = they (hablan).","Ser vs estar: ser for identity, events and time (la fiesta es hoy); estar for location and mood (estoy cansado)."],"questions":[{"prompt":"\"___ hablo español.\" (I speak Spanish.)","correctChain":["Yo"],"scrambledTokens":["Yo","Tú","Él","Ellos"],"explain":"The verb ends in -o → the speaker is “I”: Yo hablo."},{"prompt":"Say \"We speak English\":","correctChain":["Nosotros","hablamos","inglés"],"scrambledTokens":["inglés","Nosotros","hablamos","hablas"],"explain":"-amos = we: hablamos. Spanish often drops the pronoun!"},{"prompt":"\"La fiesta ___ hoy.\" (The party is today.)","correctChain":["es"],"scrambledTokens":["es","está","son","están"],"explain":"Ser for events and time: la fiesta es hoy."},{"prompt":"Ask \"Where is the bathroom?\":","correctChain":["Dónde","está","el","baño"],"scrambledTokens":["baño","Dónde","el","está","es"],"explain":"Location of things uses estar: ¿dónde está…?"},{"prompt":"\"Ellos ___ tacos.\" (They eat tacos.)","correctChain":["comen"],"scrambledTokens":["como","comes","come","comen"],"explain":"-er verbs: ellos take -en → comen."},{"kind":"match","prompt":"Pair each subject with its present-tense ending.","correctChain":["5 pairs"],"scrambledTokens":["Yo → -o","Tú → -as","Él o Ella → -a","Nosotros → -amos","Ellos → -an"],"explain":"One ending tells you who is speaking — that is why Spanish drops the pronoun so often.","match":{"pairs":[{"left":"Yo","right":"-o"},{"left":"Tú","right":"-as"},{"left":"Él o Ella","right":"-a"},{"left":"Nosotros","right":"-amos"},{"left":"Ellos","right":"-an"}]}},{"kind":"listen","prompt":"Listen and type the sentence about languages.","correctChain":["Nosotros hablamos inglés"],"scrambledTokens":[],"explain":"-amos marks the we-form, and inglés keeps its accent on the final syllable.","listen":{"phrase":"Nosotros hablamos inglés","answers":["Nosotros hablamos inglés"]}},{"kind":"speak","prompt":"Ask where the bathroom is, out loud.","correctChain":["Dónde está el baño"],"scrambledTokens":[],"explain":"Two accents, two stresses: DON-deh, es-TAH — and the ñ cuts the nose, not the n.","speak":{"phrase":"Dónde está el baño","passScore":75}}],"position":3},
  {"id":"spanish-quiz","course_id":"spanish","title":"Spanish Checkpoint","theory":["Checkpoint: greetings, phrases, gender, and tenses from the full Spanish course."],"questions":[{"prompt":"How do you say \"Hello\" in Spanish?","correctChain":["Hola"],"scrambledTokens":["Hola","Adiós","Gracias","Por favor"],"explain":"Hola opens every conversation."},{"prompt":"Say \"I eat apples\":","correctChain":["Yo","como","manzanas"],"scrambledTokens":["manzanas","Yo","el","como"],"explain":"Yo = I, como = (I) eat, manzanas = apples."},{"prompt":"Which article goes with \"libro\" (book)?","correctChain":["el"],"scrambledTokens":["el","la","los","las"],"explain":"Libro is masculine → el. La niña, el libro."},{"prompt":"Say \"My name is Ana\":","correctChain":["Me","llamo","Ana"],"scrambledTokens":["Ana","Me","llamo","Tú"],"explain":"Me llamo Ana — introduce yourself anywhere."},{"prompt":"\"¿Cómo estás?\" means…","correctChain":["How are you?"],"scrambledTokens":["How are you?","What is your name?","Where are you?","How old are you?"],"explain":"Ask it after Hola to start a real conversation."},{"prompt":"\"Ellos ___ tacos.\" (They eat tacos.)","correctChain":["comen"],"scrambledTokens":["como","comes","come","comen"],"explain":"Tenses check: ellos take -en → comen."},{"kind":"text","prompt":"You are at a café in Madrid. Type the Spanish for “A coffee, please. The bill, please.”","correctChain":["Un café, por favor. La cuenta, por favor."],"scrambledTokens":[],"explain":"Por favor softens both requests, and la cuenta is the bill. In Spain you can also say “Cobrar, por favor” when you are ready to pay.","text":{"answers":["Un café, por favor. La cuenta, por favor.","Un café por favor, la cuenta por favor."],"misconceptions":{"Un café. La cuenta.":"Both requests need por favor to sound polite in a café."}}},{"kind":"match","prompt":"Pair each subject with the verb form that agrees with it.","correctChain":["4 pairs"],"scrambledTokens":["Yo → hablo","Tú → hablas","Nosotros → hablamos","Ellos → comen"],"explain":"Three -o/-as/-amos forms from hablar, plus one -er verb: ellos comen, never comemos.","match":{"pairs":[{"left":"Yo","right":"hablo"},{"left":"Tú","right":"hablas"},{"left":"Nosotros","right":"hablamos"},{"left":"Ellos","right":"comen"}]}},{"kind":"listen","prompt":"Listen and type the question a stranger asks you.","correctChain":["Dónde está el baño"],"scrambledTokens":[],"explain":"Location uses estar, and the accent on dónde is what makes it a question rather than a statement.","listen":{"phrase":"Dónde está el baño","answers":["Dónde está el baño","Donde esta el bano"]}},{"kind":"speak","prompt":"Order a coffee politely, out loud.","correctChain":["Un café por favor"],"scrambledTokens":[],"explain":"Rise slightly on favor to signal a request; the é in café is a full vowel, not a stray mark.","speak":{"phrase":"Un café por favor","passScore":75}}],"position":4},
  {"id":"spanish-greetings","course_id":"spanish","title":"Spanish Greetings & Politeness","theory":["Hola opens everything; Buenos días (morning), Buenas tardes (afternoon), Buenas noches (night)Ride the clock. ¿Cómo estás? asks a friend, ¿Cómo está usted? respects an elder — tú for friends, usted for respect.","Always land with por favor, gracias, and perdón. De nada answers gracias; ¡Bienvenidos! welcomes everyone."],"questions":[{"prompt":"“Buenas noches” is said…","correctChain":["At night"],"scrambledTokens":["At night","In the morning","At noon","At farewell only"],"explain":"Noches = night. Tardes = afternoon, días = morning."},{"prompt":"Ask a friend “How are you?”:","correctChain":["Cómo","estás"],"scrambledTokens":["estás","Cómo","está","estoy"],"explain":"¿Cómo estás? — tú form, friends and family."},{"prompt":"“¿Cómo está usted?” differs from “¿Cómo estás?” in…","correctChain":["Formality"],"scrambledTokens":["Formality","Tense","Number","Meaning"],"explain":"Usted = respect (elders, officials). Tú = friends."},{"prompt":"Answer “thanks” with “you are welcome”:","correctChain":["De","nada"],"scrambledTokens":["nada","De","Gracias","Favor"],"explain":"Gracias → De nada. A tiny perfect pair."},{"prompt":"“¡Bienvenidos!” means…","correctChain":["Welcome! (to everyone)"],"scrambledTokens":["Welcome! (to everyone)","Goodbye!","Congratulations!","Good luck!"],"explain":"Bienvenido (one man), bienvenida (one woman), bienvenidos (all)."},{"kind":"match","prompt":"Pair each phrase with the moment it belongs to.","correctChain":["5 pairs"],"scrambledTokens":["Buenos días → Morning","Buenas tardes → Afternoon","Buenas noches → Night","De nada → Answering gracias","¡Bienvenidos! → Welcoming a group"],"explain":"The clock picks the greeting, and de nada is the only correct reply to gracias.","match":{"pairs":[{"left":"Buenos días","right":"Morning"},{"left":"Buenas tardes","right":"Afternoon"},{"left":"Buenas noches","right":"Night"},{"left":"De nada","right":"Answering gracias"},{"left":"¡Bienvenidos!","right":"Welcoming a group"}]}},{"kind":"listen","prompt":"Listen and type the question you ask a friend.","correctChain":["Cómo estás"],"scrambledTokens":[],"explain":"estás with the accent is the tú form; está without it is usted.","listen":{"phrase":"Cómo estás","answers":["Cómo estás","Como estas"]}},{"kind":"speak","prompt":"Answer someone who thanked you, out loud.","correctChain":["De nada"],"scrambledTokens":[],"explain":"Two flat syllables, no stress drama: deh-NAH-dah — it means “of nothing”.","speak":{"phrase":"De nada","passScore":75}}],"position":5},
  {"id":"spanish-numbers-time","course_id":"spanish","title":"Spanish Numbers & Time","theory":["Count: uno, dos, tres, cuatro, cinco, seis, siete, ocho, nueve, diez — then veinte, treinta… cien. Son las tres = it is 3 o’clock; Es la una = it is 1 o’clock (only one is singular!).","Days run lunes to domingo; months enero to diciembre. Hoy = today, mañana = tomorrow, ayer = yesterday."],"questions":[{"prompt":"“Siete” means…","correctChain":["Seven"],"scrambledTokens":["Seven","Six","Eight","Ten"],"explain":"Seis 6, siete 7, ocho 8 — chant the run."},{"prompt":"Say “It is 3 o’clock”:","correctChain":["Son","las","tres"],"scrambledTokens":["tres","Son","Es","las"],"explain":"Plural hours take Son las; only 1 o’clock takes Es la una."},{"prompt":"“Mañana” means…","correctChain":["Tomorrow"],"scrambledTokens":["Tomorrow","Morning","Yesterday","Today"],"explain":"Mañana does double duty: tomorrow AND morning. Context decides."},{"prompt":"Say “ten” (10):","correctChain":["Diez"],"scrambledTokens":["Nueve","Diez","Once","Doce"],"explain":"Nueve 9, diez 10, once 11, doce 12."},{"prompt":"“Es la una” is used because…","correctChain":["One o’clock is singular"],"scrambledTokens":["One o’clock is singular","Nights are singular","Una is formal","It is a question"],"explain":"La una = the one (hour). Every other hour is las."},{"kind":"match","prompt":"Pair each number with its value.","correctChain":["5 pairs"],"scrambledTokens":["Seis → 6","Siete → 7","Ocho → 8","Diez → 10","Doce → 12"],"explain":"Seis, siete, ocho then a jump: diez, once, doce — the teens break the pattern on purpose.","match":{"pairs":[{"left":"Seis","right":"6"},{"left":"Siete","right":"7"},{"left":"Ocho","right":"8"},{"left":"Diez","right":"10"},{"left":"Doce","right":"12"}]}},{"kind":"listen","prompt":"Listen and type what the clock says.","correctChain":["Son las tres"],"scrambledTokens":[],"explain":"Son las + hour for every hour except one, which is singular: es la una.","listen":{"phrase":"Son las tres","answers":["Son las tres"]}},{"kind":"speak","prompt":"Say the only singular hour out loud.","correctChain":["Es la una"],"scrambledTokens":[],"explain":"es-lah-OO-nah — the s of es links straight into la, so it sounds like one word.","speak":{"phrase":"Es la una","passScore":75}}],"position":6},
  {"id":"spanish-food","course_id":"spanish","title":"Spanish Food & Drink","theory":["Order like a local: Quiero… (I want…), La cuenta, por favor (the bill, please). El agua, el pan, el café, la leche, el arroz, el pollo, la fruta — hunger solved.","Tengo hambre = I am hungry (I HAVE hunger), tengo sed = I am thirsty. Me gusta = I like it; me encanta = I love it."],"questions":[{"prompt":"“El pollo” means…","correctChain":["The chicken"],"scrambledTokens":["The chicken","The fish","The bread","The rice"],"explain":"Pollo = chicken, pescado = fish, pan = bread."},{"prompt":"Say “I want coffee”:","correctChain":["Quiero","café"],"scrambledTokens":["café","Quiero","Tengo","Agua"],"explain":"Quiero + anything: quiero agua, quiero la cuenta."},{"prompt":"“Tengo hambre” literally means…","correctChain":["I have hunger"],"scrambledTokens":["I have hunger","I eat hunger","I am hunger","My hunger eats"],"explain":"Spanish HAS hunger and thirst: tengo hambre, tengo sed."},{"prompt":"Ask for the bill politely:","correctChain":["La","cuenta"],"scrambledTokens":["cuenta","La","Quiero","Menú"],"explain":"La cuenta, por favor — the magic exit words."},{"prompt":"“Me encanta” means…","correctChain":["I love it"],"scrambledTokens":["I love it","I hate it","I want it","I need it"],"explain":"Gusta = like, encanta = love. Me encanta el café!"},{"kind":"match","prompt":"Pair each Spanish food-word with its meaning.","correctChain":["5 pairs"],"scrambledTokens":["El pollo → The chicken","El pescado → The fish","El pan → The bread","La cuenta → The bill","Tengo sed → I am thirsty"],"explain":"Tener hambre/sed literally means to have hunger/thirst — Spanish owns its appetites.","match":{"pairs":[{"left":"El pollo","right":"The chicken"},{"left":"El pescado","right":"The fish"},{"left":"El pan","right":"The bread"},{"left":"La cuenta","right":"The bill"},{"left":"Tengo sed","right":"I am thirsty"}]}},{"kind":"listen","prompt":"Listen and type what you would order.","correctChain":["Quiero café"],"scrambledTokens":[],"explain":"Quiero takes any noun: quiero agua, quiero la cuenta, quiero el pollo.","listen":{"phrase":"Quiero café","answers":["Quiero café"]}},{"kind":"speak","prompt":"Ask for the bill, out loud.","correctChain":["La cuenta por favor"],"scrambledTokens":[],"explain":"Four even syllables and a rising favor — the rise is what makes it a request.","speak":{"phrase":"La cuenta por favor","passScore":75}}],"position":7},
  {"id":"spanish-travel","course_id":"spanish","title":"Spanish Travel & Directions","theory":["Move with confidence: ¿Dónde está…? (where is…?), a la izquierda (left), a la derecha (right), todo recto (straight). La estación, el aeropuerto, el hotel, el baño — the big four.","Ride anything: el autobús, el tren, el taxi. ¿Cuánto cuesta? (how much?), ¿A qué hora sale? (what time does it leave?)."],"questions":[{"prompt":"“¿Dónde está el baño?” asks for…","correctChain":["The bathroom’s location"],"scrambledTokens":["The bathroom’s location","The bath’s price","Bath time","A bad room"],"explain":"Dónde = where. Dónde está…? unlocks every city."},{"prompt":"Say “to the left”:","correctChain":["A","la","izquierda"],"scrambledTokens":["izquierda","A","derecha","la"],"explain":"Izquierda = left, derecha = right. Todo recto = straight on."},{"prompt":"“¿A qué hora sale?” asks for…","correctChain":["The departure time"],"scrambledTokens":["The departure time","The ticket price","The platform","The arrival"],"explain":"Salir = to leave. ¿A qué hora…? pins any schedule."},{"prompt":"Ask “How much does it cost?”:","correctChain":["Cuánto","cuesta"],"scrambledTokens":["cuesta","Cuánto","Cuesta","Cuestan"],"explain":"¿Cuánto cuesta? — singular thing. ¿Cuánto cuestan? — many."},{"prompt":"“El tren” means…","correctChain":["The train"],"scrambledTokens":["The train","The bus","The taxi","The plane"],"explain":"Tren = train, autobús = bus, avión = plane."},{"kind":"match","prompt":"Pair each travel phrase with what you are asking for.","correctChain":["5 pairs"],"scrambledTokens":["¿Dónde está el baño? → A location","¿A qué hora sale? → A departure time","¿Cuánto cuesta? → A price","A la izquierda → A direction","Todo recto → Straight on"],"explain":"Three question words cover travel: dónde (where), a qué hora (when), cuánto (how much).","match":{"pairs":[{"left":"¿Dónde está el baño?","right":"A location"},{"left":"¿A qué hora sale?","right":"A departure time"},{"left":"¿Cuánto cuesta?","right":"A price"},{"left":"A la izquierda","right":"A direction"},{"left":"Todo recto","right":"Straight on"}]}},{"kind":"listen","prompt":"Listen and type the price question.","correctChain":["Cuánto cuesta"],"scrambledTokens":[],"explain":"The accent on cuánto turns a statement into a question — writing marks the rise that speech carries.","listen":{"phrase":"Cuánto cuesta","answers":["Cuánto cuesta","Cuanto cuesta"]}},{"kind":"speak","prompt":"Give someone a turning instruction, out loud.","correctChain":["A la izquierda"],"scrambledTokens":[],"explain":"ah-lah-thee-KWER-dah; in Spain the z sounds run through the tongue, elsewhere they are soft.","speak":{"phrase":"A la izquierda","passScore":75}}],"position":8},
  {"id":"spanish-family","course_id":"spanish","title":"Spanish Family & Descriptions","theory":["Meet la familia: la madre, el padre, el hermano, la hermana, el hijo, la hija, el amigo. Mi/mis = my, tu/tus = your, su/sus = his/her/their.","Describe with ser + adjective, matching gender and number: alto/alta, altos/altas; pequeño, grande, feliz. Soy alto = I am tall."],"questions":[{"prompt":"“La hermana” means…","correctChain":["The sister"],"scrambledTokens":["The sister","The brother","The mother","The daughter"],"explain":"Hermana = sister, hermano = brother. La familia grows."},{"prompt":"Say “my brothers” (more than one):","correctChain":["Mis","hermanos"],"scrambledTokens":["hermanos","Mi","Mis","Tu"],"explain":"Mi → mis before plurals: mis hermanos, mis amigos."},{"prompt":"“Soy alta” is said by…","correctChain":["A tall woman/girl"],"scrambledTokens":["A tall woman/girl","A tall man","Tall children","Anyone tall"],"explain":"Adjectives agree: -o men, -a women, -os/-as plurals."},{"prompt":"Say “your (friend’s) mother”:","correctChain":["Tu","madre"],"scrambledTokens":["madre","Su","Tu","Mi"],"explain":"Tu = your (friend), su = his/her/their. Madre = mother."},{"prompt":"“El hijo” means…","correctChain":["The son"],"scrambledTokens":["The son","The daughter","The father","The child (neutral)"],"explain":"Hijo = son, hija = daughter, hijos = children/sons."},{"kind":"match","prompt":"Pair each family word with its meaning.","correctChain":["5 pairs"],"scrambledTokens":["La hermana → The sister","El hermano → The brother","La hija → The daughter","El hijo → The son","Mis hermanos → My brothers"],"explain":"The -a/-o swap does all the work; only plurals force mi to become mis.","match":{"pairs":[{"left":"La hermana","right":"The sister"},{"left":"El hermano","right":"The brother"},{"left":"La hija","right":"The daughter"},{"left":"El hijo","right":"The son"},{"left":"Mis hermanos","right":"My brothers"}]}},{"kind":"listen","prompt":"Listen and type the phrase about siblings.","correctChain":["Mis hermanos"],"scrambledTokens":[],"explain":"mi becomes mis before a plural noun — the possessive agrees in number, not gender.","listen":{"phrase":"Mis hermanos","answers":["Mis hermanos"]}},{"kind":"speak","prompt":"Talk about a friend’s mother, out loud.","correctChain":["Tu madre"],"scrambledTokens":[],"explain":"TOO MAH-dreh — and Spanish vowels never glide into English diphthongs.","speak":{"phrase":"Tu madre","passScore":75}}],"position":9},
  {"id":"spanish-verbs-present","course_id":"spanish","title":"Spanish Present Verbs","theory":["Three endings rule the present: -ar (hablar), -er (comer), -ir (vivir). Hablo, hablas, habla, hablamos, hablan — the endings sing the person.","Must-knows: soy (I am), tengo (I have), quiero (I want), puedo (I can). Estar describes place and mood: estoy en casa, estoy feliz."],"questions":[{"prompt":"Say “I speak Spanish”:","correctChain":["Hablo","español"],"scrambledTokens":["español","Hablo","Hablas","Habla"],"explain":"-ar verbs: hablo (I), hablas (you), habla (he/she)."},{"prompt":"“Comemos” means…","correctChain":["We eat"],"scrambledTokens":["We eat","You eat","They eat","He eats"],"explain":"-er verbs: como, comes, come, comemos, comen."},{"prompt":"Say “I am happy” (feeling → estar):","correctChain":["Estoy","feliz"],"scrambledTokens":["feliz","Soy","Estoy","Estás"],"explain":"Estar = how/where: estoy feliz. Ser = what: soy alto."},{"prompt":"“Puedo” means…","correctChain":["I can"],"scrambledTokens":["I can","I want","I have","I go"],"explain":"Poder → puedo. Querer → quiero. Tener → tengo."},{"prompt":"Say “They live here” (vivir):","correctChain":["Viven","aquí"],"scrambledTokens":["aquí","Viven","Vivo","Vives"],"explain":"-ir verbs: vivo, vives, vive, viven. Aquí = here."},{"kind":"match","prompt":"Pair each verb form with the person it names.","correctChain":["5 pairs"],"scrambledTokens":["Hablo → I speak","Comemos → We eat","Puedo → I can","Quiero → I want","Viven → They live"],"explain":"Three different infinitives, one rule: the ending names the subject, so the pronoun is optional.","match":{"pairs":[{"left":"Hablo","right":"I speak"},{"left":"Comemos","right":"We eat"},{"left":"Puedo","right":"I can"},{"left":"Quiero","right":"I want"},{"left":"Viven","right":"They live"}]}},{"kind":"listen","prompt":"Listen and type how you say you are happy.","correctChain":["Estoy feliz"],"scrambledTokens":[],"explain":"Estar for a feeling, ser for what you are: estoy feliz but soy alto.","listen":{"phrase":"Estoy feliz","answers":["Estoy feliz"]}},{"kind":"speak","prompt":"Say which language you speak, out loud.","correctChain":["Hablo español"],"scrambledTokens":[],"explain":"AH-bloh es-pah-NYOL — the ny is one sound, pushed through the palate, not n + y.","speak":{"phrase":"Hablo español","passScore":75}}],"position":10},
  {"id":"spanish-past","course_id":"spanish","title":"Spanish Past Stories","theory":["Yesterday speaks in preterite: hablé (I spoke), comí (I ate), viví (I lived). -ar takes -é, -er/-ir take -í — one accent, whole past.","The rebels: fui (I went/was), tuve (I had), hice (I did/made), dije (I said). Ayer = yesterday, la semana pasada = last week."],"questions":[{"prompt":"“Hablé” means…","correctChain":["I spoke"],"scrambledTokens":["I spoke","I speak","I will speak","Speak!"],"explain":"Hablé with the accent = finished past. Hablo = now."},{"prompt":"Say “I ate rice” (comer → comí):","correctChain":["Comí","arroz"],"scrambledTokens":["arroz","Comí","Como","Comer"],"explain":"Comí: -er past takes -í. Arroz = rice."},{"prompt":"“Fui” can mean…","correctChain":["I went / I was"],"scrambledTokens":["I went / I was","I go","I will go","Go!"],"explain":"Ser and ir share fui in the past — context picks."},{"prompt":"Say “last week”:","correctChain":["La","semana","pasada"],"scrambledTokens":["pasada","La","semana","ayer"],"explain":"La semana pasada frames any finished story."},{"prompt":"“Hice” means…","correctChain":["I did / I made"],"scrambledTokens":["I did / I made","I do","I say","I have"],"explain":"Hacer → hice. Dije = I said, tuve = I had."},{"kind":"match","prompt":"Pair each past form with what it means.","correctChain":["5 pairs"],"scrambledTokens":["Hablé → I spoke","Comí → I ate","Viví → I lived","Fui → I went or I was","Hice → I did or made"],"explain":"Regular pasts wear one accent at the end; fui and hice are rebels you simply memorise.","match":{"pairs":[{"left":"Hablé","right":"I spoke"},{"left":"Comí","right":"I ate"},{"left":"Viví","right":"I lived"},{"left":"Fui","right":"I went or I was"},{"left":"Hice","right":"I did or made"}]}},{"kind":"listen","prompt":"Listen and type what you ate.","correctChain":["Comí arroz"],"scrambledTokens":[],"explain":"Comí is finished past — the accent on the last syllable is the whole tense marker.","listen":{"phrase":"Comí arroz","answers":["Comí arroz"]}},{"kind":"speak","prompt":"Set a story in last week, out loud.","correctChain":["La semana pasada"],"scrambledTokens":[],"explain":"lah seh-MAH-nah pah-SAH-dah — the feminine article and adjective both agree with semana.","speak":{"phrase":"La semana pasada","passScore":75}}],"position":11},
  {"id":"spanish-final","course_id":"spanish","title":"Spanish Final Exam","theory":["Final exam: greetings, numbers, food, travel, family, present verbs, and past stories — the whole comprehensive course."],"questions":[{"prompt":"Ask a friend “How are you?”:","correctChain":["Cómo","estás"],"scrambledTokens":["estás","Cómo","está","estoy"],"explain":"Tú form for friends: ¿Cómo estás?"},{"prompt":"“Son las tres” tells…","correctChain":["The time (3 o’clock)"],"scrambledTokens":["The time (3 o’clock)","Three are sons","Three things","Tuesday"],"explain":"Son las + hour. Es la una for 1 o’clock only."},{"prompt":"Say “They live here”:","correctChain":["Viven","aquí"],"scrambledTokens":["aquí","Viven","Vivo","Vivimos"],"explain":"-ir present: viven = they live."},{"prompt":"“Tengo hambre” means…","correctChain":["I am hungry"],"scrambledTokens":["I am hungry","I have ham","I eat bread","I am thirsty"],"explain":"Tengo hambre = I have hunger. Tengo sed = thirsty."},{"prompt":"“Hablé” vs “hablo”: the difference is…","correctChain":["Past vs present"],"scrambledTokens":["Past vs present","Formal vs casual","Loud vs quiet","None"],"explain":"The accent marks the finished past: hablé = I spoke."},{"prompt":"Ask “Where is the station?”:","correctChain":["Dónde","está"],"scrambledTokens":["está","Dónde","Cuánto","Está"],"explain":"¿Dónde está…? + place. La estación = the station."},{"prompt":"You are at a café in Madrid. You want water and the bill. Which pair is most natural?","correctChain":["Un agua, por favor. La cuenta, por favor."],"scrambledTokens":["Un agua, por favor. La cuenta, por favor.","Agua cuenta por favor.","Yo quiero agua y cuenta.","Una agua, la cuenta."],"explain":"Por favor softens both requests, and la cuenta is the bill. Politeness is part of the language, not decoration."},{"kind":"text","prompt":"Type the Spanish for “I don’t understand.”","correctChain":["No entiendo."],"scrambledTokens":[],"explain":"No entiendo and no comprendo both mean “I don’t understand”; entiendo is the most common everyday choice.","text":{"answers":["No entiendo.","No comprendo."],"misconceptions":{"No entiendo nada":"That means “I understand nothing” — stronger than the neutral phrase."}}},{"kind":"match","prompt":"Pair each phrase with the situation it fits.","correctChain":["4 pairs"],"scrambledTokens":["Ayer → Talking about yesterday","La semana pasada → Framing a finished story","Tengo hambre → You need food","Tengo sed → You need a drink"],"explain":"Time words and body words are the two things a beginner actually needs to say out loud.","match":{"pairs":[{"left":"Ayer","right":"Talking about yesterday"},{"left":"La semana pasada","right":"Framing a finished story"},{"left":"Tengo hambre","right":"You need food"},{"left":"Tengo sed","right":"You need a drink"}]}},{"kind":"listen","prompt":"Listen and type what they tell you about the time.","correctChain":["Son las tres"],"scrambledTokens":[],"explain":"Son las, not Es las — plural hours keep the plural verb.","listen":{"phrase":"Son las tres","answers":["Son las tres"]}},{"kind":"speak","prompt":"Say the one phrase that saves any conversation, out loud.","correctChain":["No entiendo"],"scrambledTokens":[],"explain":"no en-ten-YEH-do — admit you do not understand and people switch tactics instead of repeating louder.","speak":{"phrase":"No entiendo","passScore":75}}],"position":12},
  {"id":"spanish-questions","course_id":"spanish","title":"Spanish Questions & Negation","theory":["Spanish questions carry an opening ¿ and usually put the question word first: ¿Dónde está el baño? (Where is the bathroom?), ¿Cuándo llegas? (When do you arrive?), ¿Por qué estudias español? (Why do you study Spanish?).","A yes/no question can simply rise in pitch: ¿Hablas español? The subject can come before or after the verb — ¿Tú hablas español? and ¿Hablas tú español? both work.","Negation is no before the verb: No hablo francés. Double negatives are normal and emphatic: No veo nada (I see nothing), No hay nadie (there is nobody). Use tú with friends and usted in formal situations."],"questions":[{"prompt":"Which word means “where”?","correctChain":["dónde"],"scrambledTokens":["dónde","cuándo","quién","cómo"],"explain":"Dónde = where, cuándo = when, quién = who, cómo = how."},{"prompt":"Ask “Where is the bathroom?”","correctChain":["Dónde","está","el","baño"],"scrambledTokens":["baño","Dónde","está","el","cuándo"],"explain":"¿Dónde está…? + place. El baño = the bathroom; está = is (location)."},{"prompt":"“No hablo francés” means…","correctChain":["I don’t speak French"],"scrambledTokens":["I don’t speak French","I speak French","I don’t study French","I want to learn French"],"explain":"No before the verb negates the whole sentence: no hablo = I don’t speak."},{"prompt":"Say “I don’t have time”:","correctChain":["No","tengo","tiempo"],"scrambledTokens":["tiempo","No","tengo","tiene"],"explain":"No + tengo + tiempo. Tiene is the usted/él form, not yo."},{"prompt":"“No veo nada” means…","correctChain":["I see nothing"],"scrambledTokens":["I see nothing","I don’t see the water","I see everything","I don’t want to see"],"explain":"Spanish keeps both negatives: no + veo + nada. Literally “I don’t see nothing,” meaning I see nothing."},{"kind":"match","prompt":"Pair each question word with what it asks for.","correctChain":["5 pairs"],"scrambledTokens":["Dónde → Place","Cuándo → Time","Quién → Person","Cómo → Manner","Por qué → Reason"],"explain":"Five question words cover almost every survival question. The spoken stress is marked, so the accent is part of the word — quien without an accent is not a question.","match":{"pairs":[{"left":"Dónde","right":"Place"},{"left":"Cuándo","right":"Time"},{"left":"Quién","right":"Person"},{"left":"Cómo","right":"Manner"},{"left":"Por qué","right":"Reason"}]}},{"kind":"listen","prompt":"Listen and type the excuse they give about time.","correctChain":["No tengo tiempo"],"scrambledTokens":[],"explain":"No + tengo + tiempo — the negative sits directly before the verb, and tengo is the yo form.","listen":{"phrase":"No tengo tiempo","answers":["No tengo tiempo"]}},{"kind":"speak","prompt":"Ask out loud whether someone speaks Spanish.","correctChain":["Hablas español"],"scrambledTokens":[],"explain":"say it with the rising pitch that turns a statement into a question — Spanish needs no inversion.","speak":{"phrase":"Hablas español","passScore":75}}],"position":13},
  {"id":"spanish-health","course_id":"spanish","title":"Spanish Health & Emergencies","theory":["Say what hurts with doler: Me duele la cabeza (I have a headache), Me duele el estómago (my stomach hurts). For plural body parts use duelen: Me duelen los pies.","Symptoms: Tengo fiebre (I have a fever), Tengo tos (I have a cough). Ask for help with Necesito un médico (I need a doctor), ¿Dónde está la farmacia? (where is the pharmacy?), or Llame a una ambulancia (call an ambulance — formal).","Allergies: Soy alérgico/a a los cacahuetes. Use ¿Puede ayudarme? for a polite “Can you help me?”."],"questions":[{"prompt":"“Me duele la cabeza” means…","correctChain":["I have a headache"],"scrambledTokens":["I have a headache","I have a stomach ache","My feet hurt","I am dizzy"],"explain":"Me duele + singular body part: la cabeza = the head. Duelen is for plural parts."},{"prompt":"Say “I need a doctor”:","correctChain":["Necesito","un","médico"],"scrambledTokens":["médico","Necesito","un","médica"],"explain":"Necesito = I need; un médico = a doctor. Médica is the feminine form of the profession."},{"prompt":"“Tengo fiebre” means…","correctChain":["I have a fever"],"scrambledTokens":["I have a fever","I have a cough","I am cold","I have a headache"],"explain":"Tener + fiebre = to have a fever. Tos is a cough."},{"prompt":"Ask “Where is the pharmacy?”","correctChain":["Dónde","está","la","farmacia"],"scrambledTokens":["farmacia","Dónde","está","la","el"],"explain":"¿Dónde está la farmacia? — farmacia is feminine, so la farmacia."},{"prompt":"“Soy alérgico a los cacahuetes” means…","correctChain":["Peanuts make me ill"],"scrambledTokens":["Peanuts make me ill","I love peanuts","I am carrying peanuts","Peanuts are expensive"],"explain":"Alérgico/a a… names the trigger. Say it clearly before ordering food."},{"kind":"match","prompt":"Pair each symptom with what you are telling the pharmacist.","correctChain":["5 pairs"],"scrambledTokens":["Me duele la cabeza → My head hurts","Me duele el estómago → My stomach hurts","Tengo fiebre → I have a fever","Tengo tos → I have a cough","Necesito un médico → I need a doctor"],"explain":"Doler names the body part; tener names the symptom you carry. Both open the door at a pharmacy counter.","match":{"pairs":[{"left":"Me duele la cabeza","right":"My head hurts"},{"left":"Me duele el estómago","right":"My stomach hurts"},{"left":"Tengo fiebre","right":"I have a fever"},{"left":"Tengo tos","right":"I have a cough"},{"left":"Necesito un médico","right":"I need a doctor"}]}},{"kind":"listen","prompt":"Listen and type the question this person is asking in the street.","correctChain":["Dónde está la farmacia"],"scrambledTokens":[],"explain":"¿Dónde está + the place? — farmacia is feminine, so la farmacia, never el.","listen":{"phrase":"Dónde está la farmacia","answers":["Dónde está la farmacia"]}},{"kind":"speak","prompt":"Ask a stranger for help, politely, out loud.","correctChain":["Puede ayudarme"],"scrambledTokens":[],"explain":"the usted form puede plus the infinitive ayudarme is the polite way to open any request for assistance.","speak":{"phrase":"Puede ayudarme","passScore":75}}],"position":14},
  {"id":"spanish-adjectives","course_id":"spanish","title":"Spanish Adjectives & Agreement","theory":["Adjectives in Spanish match the noun they describe in gender and number. Masculine: el chico alto (the tall boy), feminine: la chica alta (the tall girl). Plural adds -s or -es: los chicos altos, las chicas altas.","Compare things with más... que (more... than) or menos... que (less... than): Este libro es más interesante que ese. For equality, use tan... como: Ella es tan alta como su hermano."],"questions":[{"prompt":"Which adjective form goes with \"las casas\" (the houses)?","correctChain":["blancas"],"scrambledTokens":["blancas","blanco","blanca","blancos"],"explain":"Casas is feminine plural, so the adjective must be blancas."},{"prompt":"Say “The boy is tall”:","correctChain":["El","chico","es","alto"],"scrambledTokens":["alto","El","chico","es","alta"],"explain":"Chico is masculine singular, so it takes alto, not alta."},{"prompt":"“Más rápido que el tren” means…","correctChain":["Faster than the train"],"scrambledTokens":["Faster than the train","Slower than the train","As fast as the train","Next to the train"],"explain":"Más... que is the comparative of superiority: faster than."},{"prompt":"Say “He is as tall as Juan”:","correctChain":["Él","es","tan","alto","como","Juan"],"scrambledTokens":["como","Él","es","tan","alto","Juan","que"],"explain":"Tan... como expresses equality: as tall as."},{"prompt":"What is the irregular comparative of \"bueno\" (good)?","correctChain":["Mejor"],"scrambledTokens":["Mejor","Más bueno","Mayor","Peor"],"explain":"Bueno becomes mejor (better); malo becomes peor (worse)."},{"kind":"match","prompt":"Pair each adjective with its opposite.","correctChain":["5 pairs"],"scrambledTokens":["Grande → Pequeño","Alto → Bajo","Bueno → Malo","Rápido → Lento","Fácil → Difícil"],"explain":"Spanish adjectives pair up naturally: grande/pequeño, alto/bajo, rápido/lento.","match":{"pairs":[{"left":"Grande","right":"Pequeño"},{"left":"Alto","right":"Bajo"},{"left":"Bueno","right":"Malo"},{"left":"Rápido","right":"Lento"},{"left":"Fácil","right":"Difícil"}]}},{"kind":"listen","prompt":"Listen and type the comparison.","correctChain":["Más rápido que el tren"],"scrambledTokens":[],"explain":"Más with an accent means more, and que introduces the second term of comparison.","listen":{"phrase":"Más rápido que el tren","answers":["Más rápido que el tren"]}},{"kind":"speak","prompt":"Say “The boy is tall” out loud.","correctChain":["El chico es alto"],"scrambledTokens":[],"explain":"El CHEE-co es AHL-to: keep the o vowel crisp and round.","speak":{"phrase":"El chico es alto","passScore":75}}],"position":15},
  {"id":"spanish-politeness","course_id":"spanish","title":"Spanish Politeness & Courtesy","theory":["Politeness opens doors everywhere in the Spanish-speaking world. Use Disculpe to get attention or apologize politely to an adult, and Perdón when you bump into someone.","Con permiso is used when squeezing past someone or asking to leave the table. Close with Muchas gracias, and answer with De nada (you are welcome) or No hay problema (no problem)."],"questions":[{"prompt":"You need to squeeze past someone in a crowded bus. What do you say?","correctChain":["Con permiso"],"scrambledTokens":["Con permiso","Hola","Adiós","De nada"],"explain":"Con permiso is the universal polite phrase for asking to pass."},{"prompt":"Say “Excuse me, sir” politely:","correctChain":["Disculpe","señor"],"scrambledTokens":["señor","Disculpe","Gracias","Hola"],"explain":"Disculpe is the formal usted imperative of disculpar."},{"prompt":"“Lo siento mucho” means…","correctChain":["I am very sorry"],"scrambledTokens":["I am very sorry","Thank you very much","You are welcome","Please wait"],"explain":"Sentir = to feel. Lo siento mucho literally means “I feel it very much”."},{"prompt":"Say “Thank you very much”:","correctChain":["Muchas","gracias"],"scrambledTokens":["gracias","Muchas","Mucho","De"],"explain":"Gracias is feminine plural, so it pairs with muchas, not mucho."},{"prompt":"Someone says “Gracias”. Which is a friendly reply?","correctChain":["No hay problema"],"scrambledTokens":["No hay problema","Por favor","Lo siento","Disculpe"],"explain":"No hay problema (no problem) or De nada (you are welcome) replies to thanks."},{"kind":"match","prompt":"Pair each courtesy phrase with its English meaning.","correctChain":["5 pairs"],"scrambledTokens":["Disculpe → Excuse me","Lo siento → I am sorry","Con permiso → Pardon me (passing)","Muchas gracias → Thank you very much","De nada → You are welcome"],"explain":"Disculpe gets attention; lo siento expresses apology; con permiso clears a path.","match":{"pairs":[{"left":"Disculpe","right":"Excuse me"},{"left":"Lo siento","right":"I am sorry"},{"left":"Con permiso","right":"Pardon me (passing)"},{"left":"Muchas gracias","right":"Thank you very much"},{"left":"De nada","right":"You are welcome"}]}},{"kind":"listen","prompt":"Listen and type the sincere apology.","correctChain":["Lo siento mucho"],"scrambledTokens":[],"explain":"Lo siento mucho is the empathetic way to express sympathy or apology.","listen":{"phrase":"Lo siento mucho","answers":["Lo siento mucho"]}},{"kind":"speak","prompt":"Ask politely to pass by someone, out loud.","correctChain":["Con permiso"],"scrambledTokens":[],"explain":"Con per-MEE-so: a clear, soft rhythm that lets everyone know you are passing through.","speak":{"phrase":"Con permiso","passScore":75}}],"position":16},
  {"id":"spanish-introductions","course_id":"spanish","title":"Spanish Introductions & Origins","theory":["Introduce yourself with Me llamo... (My name is...) or Mi nombre es... (My name is...). Ask someone with ¿Cómo te llamas? (casual) or ¿Cómo se llama usted? (formal).","Talk about origins with ser + de: ¿De dónde eres? -> Soy de España / Soy de México. Talk about where you live with vivir: Vivo en Madrid. Close an introduction warmly with ¡Mucho gusto! (Pleasure to meet you!)."],"questions":[{"prompt":"“¿Cómo te llamas?” asks for…","correctChain":["Your name"],"scrambledTokens":["Your name","Your age","Your country","Your job"],"explain":"¿Cómo te llamas? literally means “How do you call yourself?”."},{"prompt":"Say “My name is Carlos”:","correctChain":["Me","llamo","Carlos"],"scrambledTokens":["Carlos","Me","llamo","Te","llama"],"explain":"Me llamo + name is the most natural way to state your name."},{"prompt":"“¿De dónde eres?” means…","correctChain":["Where are you from?"],"scrambledTokens":["Where are you from?","Where do you live?","Where are you going?","Where is the hotel?"],"explain":"De dónde = from where; eres = you are (ser)."},{"prompt":"Say “I am from Spain”:","correctChain":["Soy","de","España"],"scrambledTokens":["España","Soy","de","Estoy","en"],"explain":"Origins take ser: Soy de España. Location takes estar."},{"prompt":"A new acquaintance says “Mucho gusto”. What does that mean?","correctChain":["Nice to meet you"],"scrambledTokens":["Nice to meet you","Good luck","Have a nice trip","Goodbye"],"explain":"Mucho gusto = great pleasure / nice to meet you."},{"kind":"match","prompt":"Pair each introduction phrase with its function.","correctChain":["5 pairs"],"scrambledTokens":["Me llamo → Stating your name","Soy de → Stating your origin","Vivo en → Stating your residence","Mucho gusto → Pleased to meet you","Encantado → Delighted (greeting)"],"explain":"Me llamo names you, soy de tells your origin, and vivo en tells where you live today.","match":{"pairs":[{"left":"Me llamo","right":"Stating your name"},{"left":"Soy de","right":"Stating your origin"},{"left":"Vivo en","right":"Stating your residence"},{"left":"Mucho gusto","right":"Pleased to meet you"},{"left":"Encantado","right":"Delighted (greeting)"}]}},{"kind":"listen","prompt":"Listen and type the polite introduction response.","correctChain":["Mucho gusto"],"scrambledTokens":[],"explain":"Mucho gusto is the standard, warm response to meeting someone new.","listen":{"phrase":"Mucho gusto","answers":["Mucho gusto"]}},{"kind":"speak","prompt":"Say where you are from, out loud.","correctChain":["Soy de España"],"scrambledTokens":[],"explain":"Soy deh es-PAH-nyah: the ñ sounds like the \"ny\" in canyon.","speak":{"phrase":"Soy de España","passScore":75}}],"position":17},
  {"id":"spanish-language","course_id":"spanish","title":"Spanish Languages & Understanding","theory":["Ask about language ability with hablar: ¿Hablas inglés? (Do you speak English?) or formal ¿Habla usted español?. Reply with Hablo un poco de español (I speak a little Spanish).","When you are lost in a fast conversation, save yourself with: No entiendo (I don’t understand), ¿Puede hablar más despacio, por favor? (Can you speak slower, please?), and ¿Puede repetir? (Can you repeat?)."],"questions":[{"prompt":"“No entiendo” means…","correctChain":["I do not understand"],"scrambledTokens":["I do not understand","I do not know","I do not speak","I cannot hear"],"explain":"Entender = to understand. No entiendo is the first life-saving phrase in any language."},{"prompt":"Ask “Do you speak English?” casually:","correctChain":["Hablas","inglés"],"scrambledTokens":["inglés","Hablas","Habla","español"],"explain":"¿Hablas inglés? — tú form with friend or peer."},{"prompt":"You need someone to slow down. What do you say?","correctChain":["Más despacio, por favor"],"scrambledTokens":["Más despacio, por favor","Más rápido, por favor","No me gusta","Adiós"],"explain":"Despacio = slowly; más despacio = more slowly."},{"prompt":"Say “I speak a little Spanish”:","correctChain":["Hablo","un","poco","de","español"],"scrambledTokens":["español","Hablo","un","poco","de","mucho"],"explain":"Hablo = I speak; un poco de = a little bit of."},{"prompt":"“¿Puede repetir?” asks…","correctChain":["Can you repeat?"],"scrambledTokens":["Can you repeat?","Can you write it down?","Can you call someone?","Can you translate?"],"explain":"Repetir = to repeat. Puede repetir is the formal polite request."},{"kind":"match","prompt":"Pair each language phrase with what it communicates.","correctChain":["5 pairs"],"scrambledTokens":["No entiendo → I do not understand","Más despacio → Speak slower","Puede repetir → Ask for a repetition","Un poco → A little bit","Hablo inglés → I speak English"],"explain":"No entiendo admits confusion; más despacio and puede repetir ask for help.","match":{"pairs":[{"left":"No entiendo","right":"I do not understand"},{"left":"Más despacio","right":"Speak slower"},{"left":"Puede repetir","right":"Ask for a repetition"},{"left":"Un poco","right":"A little bit"},{"left":"Hablo inglés","right":"I speak English"}]}},{"kind":"listen","prompt":"Listen and type the plea for a slower pace.","correctChain":["Más despacio por favor"],"scrambledTokens":[],"explain":"Más despacio = slower; por favor = please.","listen":{"phrase":"Más despacio por favor","answers":["Más despacio por favor"]}},{"kind":"speak","prompt":"Say you speak a little Spanish, out loud.","correctChain":["Hablo un poco de español"],"scrambledTokens":[],"explain":"AH-blo oon PO-co deh es-pah-NYOL: remember the h in hablo is completely silent.","speak":{"phrase":"Hablo un poco de español","passScore":75}}],"position":18},
  {"id":"spanish-money","course_id":"spanish","title":"Spanish Shopping & Money","theory":["In markets and shops, ask the price with ¿Cuánto cuesta? (singular item) or ¿Cuánto cuestan? (plural items). You can also ask ¿Cuánto es? (How much is it in total?).","Describe prices with caro (expensive) and barato (cheap): Es demasiado caro (It is too expensive). Payment: ¿Puedo pagar con tarjeta? (Can I pay with card?) or en efectivo (in cash). At a café, ask La cuenta, por favor (The check, please)."],"questions":[{"prompt":"“¿Cuánto cuesta?” asks…","correctChain":["How much does it cost?"],"scrambledTokens":["How much does it cost?","Where is it?","Do you have more?","What time is it?"],"explain":"Costar = to cost. ¿Cuánto cuesta? is the primary shopping question."},{"prompt":"Say “It is very expensive”:","correctChain":["Es","muy","caro"],"scrambledTokens":["caro","Es","muy","barato"],"explain":"Es = it is, muy = very, caro = expensive. Barato is cheap."},{"prompt":"How do you say “Can I pay with a card?”","correctChain":["¿Puedo pagar con tarjeta?"],"scrambledTokens":["¿Puedo pagar con tarjeta?","¿Tiene efectivo?","¿Cuánto cuesta?","¿Dónde está el banco?"],"explain":"Tarjeta = card; pagar = to pay."},{"prompt":"Ask for the check at a restaurant:","correctChain":["La","cuenta","por","favor"],"scrambledTokens":["favor","La","cuenta","por","el"],"explain":"La cuenta, por favor = The bill/check, please."},{"prompt":"“En efectivo” means…","correctChain":["In cash"],"scrambledTokens":["In cash","By credit card","With a discount","For free"],"explain":"Efectivo = cash. Con tarjeta = by card."},{"kind":"match","prompt":"Pair each shopping phrase with its meaning.","correctChain":["5 pairs"],"scrambledTokens":["Cuánto cuesta → Asking price","Muy caro → Too expensive","Muy barato → Very cheap","Con tarjeta → By card","La cuenta → The bill"],"explain":"Cuánto cuesta asks the price, caro/barato evaluates it, and la cuenta asks to pay.","match":{"pairs":[{"left":"Cuánto cuesta","right":"Asking price"},{"left":"Muy caro","right":"Too expensive"},{"left":"Muy barato","right":"Very cheap"},{"left":"Con tarjeta","right":"By card"},{"left":"La cuenta","right":"The bill"}]}},{"kind":"listen","prompt":"Listen and type the question asked at the market.","correctChain":["Cuánto cuesta esto"],"scrambledTokens":[],"explain":"¿Cuánto cuesta esto? = How much does this cost? Esto is the neutral \"this\".","listen":{"phrase":"Cuánto cuesta esto","answers":["Cuánto cuesta esto"]}},{"kind":"speak","prompt":"Ask for the restaurant check, out loud.","correctChain":["La cuenta por favor"],"scrambledTokens":[],"explain":"Lah KWEN-tah por fah-VOR: clear, courteous, and recognized in every restaurant.","speak":{"phrase":"La cuenta por favor","passScore":75}}],"position":19},
  {"id":"french-basics","course_id":"french","title":"French Basics","theory":["French starts with music: Bonjour (hello), Merci (thank you), Au revoir (goodbye). Pronounce every syllable softly — the r rolls at the back.","Like Spanish, French nouns have gender: le for masculine, la for feminine. Fille (girl) is feminine → la fille."],"questions":[{"prompt":"\"Bonjour\" means…","correctChain":["Hello"],"scrambledTokens":["Hello","Goodbye","Thank you","Please"],"explain":"Bonjour = good day — the all-purpose French hello."},{"prompt":"\"Merci\" means…","correctChain":["Thank you"],"scrambledTokens":["Thank you","Sorry","Welcome","Good night"],"explain":"Merci carries you through every café in Paris."},{"prompt":"Say \"I eat apples\":","correctChain":["Je","mange","des","pommes"],"scrambledTokens":["pommes","Je","le","mange","des"],"explain":"Je = I, mange = (I) eat, des pommes = (some) apples."},{"prompt":"Which article goes with \"fille\" (girl)?","correctChain":["la"],"scrambledTokens":["la","le","les","un"],"explain":"Feminine nouns take la; masculine nouns take le."},{"prompt":"Say goodbye, friend:","correctChain":["Au","revoir","mon","ami"],"scrambledTokens":["ami","Bonjour","Au","revoir","mon"],"explain":"Au revoir = until we meet again; mon ami = my friend."},{"kind":"match","prompt":"Pair each French word with its meaning.","correctChain":["5 pairs"],"scrambledTokens":["Bonjour → Hello","Merci → Thank you","Au revoir → Goodbye","Fille → Girl","Pommes → Apples"],"explain":"Bonjour opens, au revoir closes, and gender decides the article: la fille, des pommes.","match":{"pairs":[{"left":"Bonjour","right":"Hello"},{"left":"Merci","right":"Thank you"},{"left":"Au revoir","right":"Goodbye"},{"left":"Fille","right":"Girl"},{"left":"Pommes","right":"Apples"}]}},{"kind":"listen","prompt":"Listen and type the sentence about apples.","correctChain":["Je mange des pommes"],"scrambledTokens":[],"explain":"Je = I, mange = (I) eat, des pommes = (some) apples. The -s on pommes is silent; the nasal in \"pommes\" is not.","listen":{"phrase":"Je mange des pommes","answers":["Je mange des pommes"]}},{"kind":"speak","prompt":"Say goodbye to a friend, out loud.","correctChain":["Au revoir mon ami"],"scrambledTokens":[],"explain":"Link the words the way French does — oh-rev-WAR mohn-ah-MEE — and let the r rasp at the back of the throat.","speak":{"phrase":"Au revoir mon ami","passScore":75}}],"position":1},
  {"id":"french-phrases","course_id":"french","title":"French Phrases","theory":["Level up: ask how people are (Comment ça va?), introduce yourself (Je m’appelle…), and request politely (S’il vous plaît).","Merci scales to Merci beaucoup; Au revoir softens to À bientôt (see you soon)."],"questions":[{"prompt":"\"Comment ça va?\" means…","correctChain":["How are you?"],"scrambledTokens":["How are you?","What is your name?","Where is the station?","What time is it?"],"explain":"The classic after Bonjour."},{"prompt":"Say \"My name is Marie\":","correctChain":["Je","m'appelle","Marie"],"scrambledTokens":["Marie","Tu","Je","m'appelle"],"explain":"Je m'appelle = I call myself — the French introduction."},{"prompt":"\"S'il vous plaît\" means…","correctChain":["Please"],"scrambledTokens":["Please","Thank you","Sorry","Welcome"],"explain":"The politeness key to every French request."},{"prompt":"Say \"Thank you very much\":","correctChain":["Merci","beaucoup"],"scrambledTokens":["beaucoup","Merci","bon","très"],"explain":"Merci beaucoup — beaucoup = a lot."},{"prompt":"\"À bientôt\" means…","correctChain":["See you soon"],"scrambledTokens":["See you soon","Good night","Good luck","Welcome back"],"explain":"À = until; bientôt = soon."},{"kind":"match","prompt":"Pair each phrase with what it does in a conversation.","correctChain":["5 pairs"],"scrambledTokens":["Comment ça va? → Ask how someone is","Je m'appelle → Introduce yourself","S'il vous plaît → Soften a request","Merci beaucoup → Thank someone warmly","À bientôt → Leave for now"],"explain":"The same five moves as Spanish, in French clothes: greet, name, ask, thank, part.","match":{"pairs":[{"left":"Comment ça va?","right":"Ask how someone is"},{"left":"Je m'appelle","right":"Introduce yourself"},{"left":"S'il vous plaît","right":"Soften a request"},{"left":"Merci beaucoup","right":"Thank someone warmly"},{"left":"À bientôt","right":"Leave for now"}]}},{"kind":"listen","prompt":"Listen and type how someone says their name.","correctChain":["Je m'appelle Marie"],"scrambledTokens":[],"explain":"The elision m’appelle swallows the vowel of je — one smooth jump, not two words.","listen":{"phrase":"Je m'appelle Marie","answers":["Je m'appelle Marie"]}},{"kind":"speak","prompt":"Thank someone generously, out loud.","correctChain":["Merci beaucoup"],"scrambledTokens":[],"explain":"mer-SEE boh-KOO — the l is silent and the final p never appears.","speak":{"phrase":"Merci beaucoup","passScore":75}}],"position":2},
  {"id":"french-tenses","course_id":"french","title":"French Tenses Lab","theory":["Present tense runs on endings: -e = I/he (parle), -es = you (parles), -ons = we (parlons), -ez = you all (parlez), -ent = they (parlent, silent -nt!).","Être is the king verb — memorise it whole: je suis, tu es, il est, nous sommes, vous êtes, ils sont."],"questions":[{"prompt":"\"___ parle français.\" (I speak French.)","correctChain":["Je"],"scrambledTokens":["Je","Tu","Il","Nous"],"explain":"-e ending with no -s → Je parle."},{"prompt":"Say \"We love bread\":","correctChain":["Nous","aimons","le","pain"],"scrambledTokens":["pain","Nous","le","aimons","aimez"],"explain":"-ons = we: nous aimons."},{"prompt":"\"Tu ___ à Paris.\" (You live in Paris.)","correctChain":["habites"],"scrambledTokens":["habite","habites","habitent","habiter"],"explain":"Tu verbs take -s: tu habites."},{"prompt":"Say \"She is tired\":","correctChain":["Elle","est","fatiguée"],"scrambledTokens":["fatiguée","Elle","est","sont"],"explain":"Elle est — she is. Est also pairs with il and on."},{"prompt":"\"Ils ___ contents.\" (They are happy.)","correctChain":["sont"],"scrambledTokens":["est","sommes","sont","êtes"],"explain":"Ils + être → sont."},{"kind":"match","prompt":"Pair each subject with its form of être (to be).","correctChain":["5 pairs"],"scrambledTokens":["Je → suis","Tu → es","Il ou Elle → est","Nous → sommes","Vous → êtes"],"explain":"Être is irregular from the ground up — memorise it whole, because every level of French builds on it.","match":{"pairs":[{"left":"Je","right":"suis"},{"left":"Tu","right":"es"},{"left":"Il ou Elle","right":"est"},{"left":"Nous","right":"sommes"},{"left":"Vous","right":"êtes"}]}},{"kind":"listen","prompt":"Listen and type the sentence about bread.","correctChain":["Nous aimons le pain"],"scrambledTokens":[],"explain":"-ons is the we-ending, and the n in pain is nasal — the air comes through the nose.","listen":{"phrase":"Nous aimons le pain","answers":["Nous aimons le pain"]}},{"kind":"speak","prompt":"Say that she is tired, out loud.","correctChain":["Elle est fatiguée"],"scrambledTokens":[],"explain":"Elle est runs together as one breath — el-AY — and fatiguée ends on the last e, not a silent one.","speak":{"phrase":"Elle est fatiguée","passScore":75}}],"position":3},
  {"id":"french-quiz","course_id":"french","title":"French Checkpoint","theory":["Checkpoint: greetings, phrases, gender, and tenses from the full French course."],"questions":[{"prompt":"\"Bonjour\" means…","correctChain":["Hello"],"scrambledTokens":["Hello","Goodbye","Thank you","Please"],"explain":"Bonjour = good day — the all-purpose hello."},{"prompt":"Say \"I eat apples\":","correctChain":["Je","mange","des","pommes"],"scrambledTokens":["pommes","Je","le","mange","des"],"explain":"Je = I, mange = (I) eat, des pommes = (some) apples."},{"prompt":"Which article goes with \"livre\" (book)?","correctChain":["le"],"scrambledTokens":["le","la","les","des"],"explain":"Livre is masculine → le. La fille, le livre."},{"prompt":"Say \"My name is Marie\":","correctChain":["Je","m'appelle","Marie"],"scrambledTokens":["Marie","m'appelle","Je","Tu"],"explain":"Je m'appelle Marie — introduce yourself anywhere."},{"prompt":"\"Merci\" means…","correctChain":["Thank you"],"scrambledTokens":["Thank you","Sorry","Welcome","Good night"],"explain":"Merci carries you through every café in Paris."},{"prompt":"\"Ils ___ contents.\" (They are happy.)","correctChain":["sont"],"scrambledTokens":["est","sommes","sont","êtes"],"explain":"Tenses check: ils + être → sont."},{"kind":"text","prompt":"You walk into a restaurant in Lyon. Type the French for “A table for two, please.”","correctChain":["Une table pour deux, s’il vous plaît."],"scrambledTokens":[],"explain":"Une table = a table, pour deux = for two, s’il vous plaît = please. The whole phrase is the polite request; dropping the final phrase makes it sound like a command.","text":{"answers":["Une table pour deux, s’il vous plaît.","Une table pour deux s’il vous plaît."],"misconceptions":{"Une table deux":"Name the party size with pour: une table pour deux."}}},{"kind":"match","prompt":"Pair each article with the noun shape it needs.","correctChain":["4 pairs"],"scrambledTokens":["le → masculine singular","la → feminine singular","les → any plural","un → one masculine thing"],"explain":"Gender is a property of the noun, not the object: livre is masculine, fille is feminine, and les makes either plural.","match":{"pairs":[{"left":"le","right":"masculine singular"},{"left":"la","right":"feminine singular"},{"left":"les","right":"any plural"},{"left":"un","right":"one masculine thing"}]}},{"kind":"listen","prompt":"Listen and type the sentence about apples.","correctChain":["Je mange des pommes"],"scrambledTokens":[],"explain":"des pommes is \"some apples\" — the partitive article you need whenever you eat or buy something.","listen":{"phrase":"Je mange des pommes","answers":["Je mange des pommes"]}},{"kind":"speak","prompt":"Ask a waiter for the table you already booked, out loud.","correctChain":["Une table pour deux"],"scrambledTokens":[],"explain":"Link the words: oon-table-poor-DUH — French hates a gap between them.","speak":{"phrase":"Une table pour deux","passScore":75}}],"position":4},
  {"id":"french-greetings","course_id":"french","title":"French Greetings & Politeness","theory":["Bonjour opens every door before evening, when Bonsoir takes over. Salut greets friends; Coucou is pure affection. Comment ça va? asks a friend, Comment allez-vous? respects an elder — tu for friends, vous for respect.","Land softly with s’il vous plaît, merci, pardon. De rien answers merci; Bienvenue welcomes all."],"questions":[{"prompt":"“Bonsoir” is said…","correctChain":["In the evening"],"scrambledTokens":["In the evening","In the morning","At noon","Only at bedtime"],"explain":"Bonjour → Bonsoir when the light fades."},{"prompt":"Ask a friend “How is it going?”:","correctChain":["Comment","ça","va"],"scrambledTokens":["va","Comment","allez","ça"],"explain":"Comment ça va? — tu form, friends and family."},{"prompt":"“Comment allez-vous?” differs from “Comment ça va?” in…","correctChain":["Formality"],"scrambledTokens":["Formality","Tense","Number","Speed"],"explain":"Vous = respect (elders, officials). Tu = friends."},{"prompt":"Answer “thanks” with “you are welcome”:","correctChain":["De","rien"],"scrambledTokens":["rien","De","Merci","Plaît"],"explain":"Merci → De rien. A tiny perfect pair."},{"prompt":"“Bienvenue!” means…","correctChain":["Welcome!"],"scrambledTokens":["Welcome!","Goodbye!","Good luck!","Congratulations!"],"explain":"Bienvenue opens every home, shop, and classroom."},{"kind":"match","prompt":"Pair each French phrase with the moment it fits.","correctChain":["5 pairs"],"scrambledTokens":["Bonjour → Greeting someone before evening","Bonsoir → Greeting someone after dark","Salut → Greeting a friend","Merci → Someone handed you what you asked for","De rien → Someone just thanked you"],"explain":"Bonjour and bonsoir split the day, salut stays informal, and merci/de rien are a fixed pair — the reply to thanks is never oui.","match":{"pairs":[{"left":"Bonjour","right":"Greeting someone before evening"},{"left":"Bonsoir","right":"Greeting someone after dark"},{"left":"Salut","right":"Greeting a friend"},{"left":"Merci","right":"Someone handed you what you asked for"},{"left":"De rien","right":"Someone just thanked you"}]}},{"kind":"listen","prompt":"Listen and type the small-talk question a friend asks you.","correctChain":["Comment ça va"],"scrambledTokens":[],"explain":"Ça va carries all the small talk — the ç makes an s sound, so typing sa or ca still counts here.","listen":{"phrase":"Comment ça va","answers":["Comment ça va","Comment sa va","Comment ca va"]}},{"kind":"speak","prompt":"Greet a friend and ask how they are, out loud.","correctChain":["Salut comment ça va"],"scrambledTokens":[],"explain":"Salut lands fast and flat, then let the question rise at the end — French asks with pitch, not word order.","speak":{"phrase":"Salut comment ça va","passScore":75}}],"position":5},
  {"id":"french-numbers-time","course_id":"french","title":"French Numbers & Time","theory":["Count: un, deux, trois, quatre, cinq, six, sept, huit, neuf, dix — then the famous rebels: quatre-vingts (80, four-twenties!). Il est trois heures = it is 3 o’clock; et demie = half past, et quart = quarter past.","Days run lundi to dimanche; mois janvier to décembre. Aujourd’hui = today, demain = tomorrow, hier = yesterday."],"questions":[{"prompt":"“Huit” means…","correctChain":["Eight"],"scrambledTokens":["Eight","Seven","Nine","Eighteen"],"explain":"Sept 7, huit 8, neuf 9 — chant the run."},{"prompt":"Say “It is 3 o’clock”:","correctChain":["Il","est","trois","heures"],"scrambledTokens":["heures","Il","trois","est","sont"],"explain":"Il est + number + heures. Half past adds et demie."},{"prompt":"“Quatre-vingts” literally means…","correctChain":["Four-twenties (80)"],"scrambledTokens":["Four-twenties (80)","Four winds","Four wines","Eighty wines"],"explain":"French counts by twenties: 80 = 4×20. Glorious chaos."},{"prompt":"Say “tomorrow”:","correctChain":["Demain"],"scrambledTokens":["Hier","Demain","Aujourd’hui","Soir"],"explain":"Hier → aujourd’hui → demain: yesterday, today, tomorrow."},{"prompt":"“Et quart” after an hour means…","correctChain":["Quarter past"],"scrambledTokens":["Quarter past","Quarter to","Half past","Sharp"],"explain":"Trois heures et quart = 3:15. Moins le quart = quarter to."},{"kind":"match","prompt":"Pair each French number with its value.","correctChain":["5 pairs"],"scrambledTokens":["Sept → 7","Huit → 8","Neuf → 9","Dix → 10","Quatre-vingts → 80"],"explain":"The run 7-8-9-10 rhymes, then French breaks the pattern: 80 is four twenties, not a word of its own.","match":{"pairs":[{"left":"Sept","right":"7"},{"left":"Huit","right":"8"},{"left":"Neuf","right":"9"},{"left":"Dix","right":"10"},{"left":"Quatre-vingts","right":"80"}]}},{"kind":"listen","prompt":"Listen and type the time being announced.","correctChain":["Il est trois heures"],"scrambledTokens":[],"explain":"Il est, never c’est, and heures keeps a silent s you still have to type.","listen":{"phrase":"Il est trois heures","answers":["Il est trois heures"]}},{"kind":"speak","prompt":"Tell someone the hour out loud.","correctChain":["Il est dix heures"],"scrambledTokens":[],"explain":"The x in dix links into heures — say it dee-zez, and the final s stays silent.","speak":{"phrase":"Il est dix heures","passScore":75}}],"position":6},
  {"id":"french-food","course_id":"french","title":"French Food & Drink","theory":["Order like a Parisian: Je voudrais… (I would like…), L’addition, s’il vous plaît (the bill, please). Le pain, le fromage, le café, le lait, le riz, le poulet, le poisson — hunger solved.","J’ai faim = I am hungry (I HAVE hunger), j’ai soif = I am thirsty. J’aime = I like; j’adore = I love."],"questions":[{"prompt":"“Le fromage” means…","correctChain":["The cheese"],"scrambledTokens":["The cheese","The bread","The fish","The chicken"],"explain":"Fromage = cheese, pain = bread, poisson = fish."},{"prompt":"Say “I would like coffee” politely:","correctChain":["Je","voudrais","café"],"scrambledTokens":["café","Je","voudrais","veux"],"explain":"Je voudrais = polished wanting. Je veux = blunt."},{"prompt":"“J’ai faim” literally means…","correctChain":["I have hunger"],"scrambledTokens":["I have hunger","I eat hunger","I am hunger","My hunger eats"],"explain":"French HAS hunger and thirst: j’ai faim, j’ai soif."},{"prompt":"Ask for the bill politely:","correctChain":["L’addition"],"scrambledTokens":["Le menu","L’addition","La carte","Le café"],"explain":"L’addition, s’il vous plaît — the magic exit words."},{"prompt":"“J’adore” means…","correctChain":["I love"],"scrambledTokens":["I love","I hate","I want","I need"],"explain":"J’aime = I like, j’adore = I love. J’adore le café!"},{"kind":"match","prompt":"Pair each word with what you are asking for at the table.","correctChain":["5 pairs"],"scrambledTokens":["Le pain → Bread","Le fromage → Cheese","Le poisson → Fish","Le poulet → Chicken","L’addition → The bill"],"explain":"Pain, fromage, poisson, poulet all take le; addition starts with a vowel so it takes l’. It is also the word that ends the meal.","match":{"pairs":[{"left":"Le pain","right":"Bread"},{"left":"Le fromage","right":"Cheese"},{"left":"Le poisson","right":"Fish"},{"left":"Le poulet","right":"Chicken"},{"left":"L’addition","right":"The bill"}]}},{"kind":"listen","prompt":"Listen and type the polite order.","correctChain":["Je voudrais un café"],"scrambledTokens":[],"explain":"Je voudrais is the conditional — the soft way to want. Je veux would read as a demand.","listen":{"phrase":"Je voudrais un café","answers":["Je voudrais un café","Je voudrais un cafe"]}},{"kind":"speak","prompt":"Order a coffee the polite way, out loud.","correctChain":["Je voudrais un café"],"scrambledTokens":[],"explain":"Voudrais ends in a silent s: voo-dray. Add s’il vous plaît and the order becomes a request.","speak":{"phrase":"Je voudrais un café","passScore":75}}],"position":7},
  {"id":"french-travel","course_id":"french","title":"French Travel & Directions","theory":["Move with grace: Où est…? (where is…?), à gauche (left), à droite (right), tout droit (straight). La gare, l’aéroport, l’hôtel, les toilettes — the big four.","Ride anything: le bus, le train, le taxi. C’est combien? (how much?), À quelle heure part-il? (what time does it leave?)."],"questions":[{"prompt":"“Où est la gare?” asks for…","correctChain":["The station’s location"],"scrambledTokens":["The station’s location","The station’s price","Station time","A guarded room"],"explain":"Où = where. Où est…? unlocks every city."},{"prompt":"Say “to the left”:","correctChain":["À","gauche"],"scrambledTokens":["gauche","À","droite","tout"],"explain":"Gauche = left, droite = right. Tout droit = straight on."},{"prompt":"“C’est combien?” asks for…","correctChain":["The price"],"scrambledTokens":["The price","The time","The number","The name"],"explain":"Combien = how much. C’est combien? bargains anywhere."},{"prompt":"Ask where the hotel is:","correctChain":["Où","est","l’hôtel"],"scrambledTokens":["l’hôtel","Où","est","combien"],"explain":"Où est…? + place. L’hôtel, la gare, l’aéroport."},{"prompt":"“Le train” means…","correctChain":["The train"],"scrambledTokens":["The train","The bus","The taxi","The plane"],"explain":"Train = train, bus = bus, avion = plane."},{"kind":"match","prompt":"Pair each travel word with what it gives you.","correctChain":["5 pairs"],"scrambledTokens":["À gauche → Turn left","À droite → Turn right","Tout droit → Keep going straight","La gare → Catch a train here","C’est combien → Ask the price"],"explain":"Gauche and droite are the two words that save you on any street; combien asks price, where asks place.","match":{"pairs":[{"left":"À gauche","right":"Turn left"},{"left":"À droite","right":"Turn right"},{"left":"Tout droit","right":"Keep going straight"},{"left":"La gare","right":"Catch a train here"},{"left":"C’est combien","right":"Ask the price"}]}},{"kind":"listen","prompt":"Listen and type the question about the station.","correctChain":["Où est la gare"],"scrambledTokens":[],"explain":"Où = where; the accent separates it from ou (or), but hearing it is the same sound.","listen":{"phrase":"Où est la gare","answers":["Où est la gare","Ou est la gare"]}},{"kind":"speak","prompt":"Tell a passer-by which way to go, out loud.","correctChain":["Allez tout droit"],"scrambledTokens":[],"explain":"Allez is the vous imperative — ah-lay with the nasal -ez — and tout droit means straight ahead.","speak":{"phrase":"Allez tout droit","passScore":75}}],"position":8},
  {"id":"french-family","course_id":"french","title":"French Family & Descriptions","theory":["Meet la famille: la mère, le père, le frère, la sœur, le fils, la fille, l’ami. Mon/ma/mes = my, ton/ta/tes = your, son/sa/ses = his/her.","Describe with être + adjective, matching gender and number: grand/grande, petit/petite, heureux/heureuse. Je suis grand = I am tall."],"questions":[{"prompt":"“La sœur” means…","correctChain":["The sister"],"scrambledTokens":["The sister","The brother","The mother","The daughter"],"explain":"Sœur = sister, frère = brother. La famille grows."},{"prompt":"Say “my brothers” (more than one):","correctChain":["Mes","frères"],"scrambledTokens":["frères","Mon","Mes","Ton"],"explain":"Mon → mes before plurals: mes frères, mes amis."},{"prompt":"“Je suis grande” is said by…","correctChain":["A tall woman/girl"],"scrambledTokens":["A tall woman/girl","A tall man","Tall children","Anyone tall"],"explain":"Adjectives agree: grand/grande, petits/petites."},{"prompt":"Say “your (friend’s) mother”:","correctChain":["Ta","mère"],"scrambledTokens":["mère","Sa","Ta","Ma"],"explain":"Ta = your (friend), sa = his/her. Mère = mother."},{"prompt":"“Le fils” means…","correctChain":["The son"],"scrambledTokens":["The son","The daughter","The father","The thread"],"explain":"Fils = son, fille = daughter. Pronounced “feece”."},{"kind":"match","prompt":"Pair each family word with who it names.","correctChain":["5 pairs"],"scrambledTokens":["La mère → Mother","Le père → Father","Le frère → Brother","La sœur → Sister","La fille → Daughter"],"explain":"La/le carry the gender, and fils (son) and fille (daughter) differ only in that final e you do not pronounce.","match":{"pairs":[{"left":"La mère","right":"Mother"},{"left":"Le père","right":"Father"},{"left":"Le frère","right":"Brother"},{"left":"La sœur","right":"Sister"},{"left":"La fille","right":"Daughter"}]}},{"kind":"listen","prompt":"Listen and type who you are talking about.","correctChain":["C’est ma mère"],"scrambledTokens":[],"explain":"Ma agrees with the feminine noun; mon would only return before a vowel word like mon amie.","listen":{"phrase":"C’est ma mère","answers":["C’est ma mère","C est ma mere","C’est ma mere"]}},{"kind":"speak","prompt":"Say you have a big family, out loud.","correctChain":["J’ai une grande famille"],"scrambledTokens":[],"explain":"Grande keeps its final -d before the vowel of famille — that linking sound is what makes French flow.","speak":{"phrase":"J’ai une grande famille","passScore":75}}],"position":9},
  {"id":"french-verbs-present","course_id":"french","title":"French Present Verbs","theory":["Three families rule the present: -er (parler), -ir (finir), -re (vendre). Je parle, tu parles, il parle, nous parlons, ils parlent — the endings sing the person.","Must-knows: je suis (I am), j’ai (I have), je veux (I want), je peux (I can). Avoir describes age and hunger: j’ai dix ans, j’ai faim."],"questions":[{"prompt":"Say “I speak French”:","correctChain":["Je","parle","français"],"scrambledTokens":["français","Je","parles","parle"],"explain":"-er verbs: je parle (I), tu parles (you), il parle (he)."},{"prompt":"“Nous finissons” means…","correctChain":["We finish"],"scrambledTokens":["We finish","You finish","They finish","He finishes"],"explain":"-ir verbs: je finis, nous finissons, ils finissent."},{"prompt":"Say “I am happy” (être):","correctChain":["Je","suis","heureux"],"scrambledTokens":["heureux","Je","suis","es"],"explain":"Être: je suis, tu es, il est. Je suis heureux!"},{"prompt":"“Je peux” means…","correctChain":["I can"],"scrambledTokens":["I can","I want","I have","I go"],"explain":"Pouvoir → je peux. Vouloir → je veux."},{"prompt":"Say “They sell bread” (vendre):","correctChain":["Ils","vendent","pain"],"scrambledTokens":["pain","Ils","vendent","vends","vendons"],"explain":"-re verbs: je vends, ils vendent. Pain = bread."},{"kind":"match","prompt":"Pair each verb form with the person it marks.","correctChain":["5 pairs"],"scrambledTokens":["Je parle → I speak","Tu parles → You speak, informally","Nous parlons → We speak","Ils parlent → They speak","Je finis → I finish"],"explain":"The ending names the person: -e, -es, -ons, -ent. Speak and finish use the same endings, different stems.","match":{"pairs":[{"left":"Je parle","right":"I speak"},{"left":"Tu parles","right":"You speak, informally"},{"left":"Nous parlons","right":"We speak"},{"left":"Ils parlent","right":"They speak"},{"left":"Je finis","right":"I finish"}]}},{"kind":"listen","prompt":"Listen and type what they sell.","correctChain":["Je peux vendre du pain"],"scrambledTokens":[],"explain":"Can + infinitive is the pattern: je peux vendre (I can sell), and pain is bread.","listen":{"phrase":"Je peux vendre du pain","answers":["Je peux vendre du pain"],"misconceptions":{"Je peut vendre du pain":"Peut is the il form. The two sound identical, but only je takes peux."}}},{"kind":"speak","prompt":"Say you speak a little French, out loud.","correctChain":["Je parle un peu français"],"scrambledTokens":[],"explain":"Parle is one syllable (parl), peu is \"puh\", and français ends in the nasal an — zhuh parl uhn puh fran-SAY.","speak":{"phrase":"Je parle un peu français","passScore":75}}],"position":10},
  {"id":"french-past","course_id":"french","title":"French Past Stories","theory":["Yesterday speaks in passé composé: j’ai parlé (I spoke), j’ai fini (I finished), je suis allé (I went). Most verbs take avoir; movement verbs (aller, venir, arriver) take être.","The rebels: j’ai eu (I had), j’ai fait (I did/made), j’ai dit (I said). Hier = yesterday, la semaine dernière = last week."],"questions":[{"prompt":"“J’ai parlé” means…","correctChain":["I spoke"],"scrambledTokens":["I spoke","I speak","I will speak","Speak!"],"explain":"Avoir + parlé = finished past. Je parle = now."},{"prompt":"Say “I finished” (finir):","correctChain":["J’ai","fini"],"scrambledTokens":["fini","J’ai","Je","finis"],"explain":"J’ai fini: avoir + past participle (fini)."},{"prompt":"“Je suis allé” uses être because…","correctChain":["Aller is a movement verb"],"scrambledTokens":["Aller is a movement verb","Aller is long","Allé is formal","Avoir is broken"],"explain":"DR MRS VANDERTRAMP verbs take être: aller, venir, arriver…"},{"prompt":"Say “last week”:","correctChain":["La","semaine","dernière"],"scrambledTokens":["dernière","La","semaine","hier"],"explain":"La semaine dernière frames any finished story."},{"prompt":"“J’ai fait” means…","correctChain":["I did / I made"],"scrambledTokens":["I did / I made","I do","I say","I have"],"explain":"Faire → fait. J’ai dit = I said, j’ai eu = I had."},{"kind":"match","prompt":"Pair each past form with what it says.","correctChain":["5 pairs"],"scrambledTokens":["J’ai parlé → I spoke","J’ai fini → I finished","Je suis allé → I went","J’ai fait → I did something","La semaine dernière → When it happened"],"explain":"Passé composé is auxiliary + past participle. Only movement verbs like aller borrow être instead of avoir.","match":{"pairs":[{"left":"J’ai parlé","right":"I spoke"},{"left":"J’ai fini","right":"I finished"},{"left":"Je suis allé","right":"I went"},{"left":"J’ai fait","right":"I did something"},{"left":"La semaine dernière","right":"When it happened"}]}},{"kind":"listen","prompt":"Listen and type what they did yesterday.","correctChain":["Hier j’ai mangé au restaurant"],"scrambledTokens":[],"explain":"Hier sets the frame, j’ai mangé is the finished action, and au restaurant is à + le fused into one word.","listen":{"phrase":"Hier j’ai mangé au restaurant","answers":["Hier j’ai mangé au restaurant","Hier j ai mange au restaurant"]}},{"kind":"speak","prompt":"Say you spoke French yesterday, out loud.","correctChain":["Hier j’ai parlé français"],"scrambledTokens":[],"explain":"Parlé drops the final e sound: par-LAY. The whole sentence is one breath group, stress on the last syllable.","speak":{"phrase":"Hier j’ai parlé français","passScore":75}}],"position":11},
  {"id":"french-final","course_id":"french","title":"French Final Exam","theory":["Final exam: greetings, numbers, food, travel, family, present verbs, and past stories — the whole comprehensive course."],"questions":[{"prompt":"Ask a friend “How is it going?”:","correctChain":["Comment","ça","va"],"scrambledTokens":["va","Comment","allez","ça"],"explain":"Tu form for friends: Comment ça va?"},{"prompt":"“Quatre-vingts” means…","correctChain":["80"],"scrambledTokens":["80","84","20","420"],"explain":"Four-twenties: 4 × 20 = 80. Only in French!"},{"prompt":"Say “They sell bread”:","correctChain":["Ils","vendent","pain"],"scrambledTokens":["pain","Ils","vendent","vends","vendre"],"explain":"-re present: ils vendent = they sell."},{"prompt":"“J’ai faim” means…","correctChain":["I am hungry"],"scrambledTokens":["I am hungry","I have fame","I eat bread","I am thirsty"],"explain":"J’ai faim = I have hunger. J’ai soif = thirsty."},{"prompt":"“J’ai parlé” vs “je parle”: the difference is…","correctChain":["Past vs present"],"scrambledTokens":["Past vs present","Formal vs casual","Loud vs quiet","None"],"explain":"Passé composé marks the finished past: j’ai parlé = I spoke."},{"prompt":"Ask “Where is the station?”:","correctChain":["Où","est","la","gare"],"scrambledTokens":["gare","Où","est","la","combien"],"explain":"Où est…? + place. La gare = the station."},{"prompt":"You are at a boulangerie. You want two croissants and need to pay. Which is most natural?","correctChain":["Deux croissants, s’il vous plaît. Je peux payer ?"],"scrambledTokens":["Deux croissants, s’il vous plaît. Je peux payer ?","Deux croissants je payer.","Je veux deux croissants maintenant.","Croissants deux, payer oui."],"explain":"S’il vous plaît makes the order polite; “Je peux payer ?” asks to pay without demanding."},{"kind":"text","prompt":"Type the French for “I don’t understand.”","correctChain":["Je ne comprends pas."],"scrambledTokens":[],"explain":"Je ne comprends pas wraps the verb in ne … pas. In casual speech you may hear “Je comprends pas,” but the full form is the standard.","text":{"answers":["Je ne comprends pas."],"misconceptions":{"Je ne comprende pas":"Comprendre is an -re verb: the first person is je comprends, not je comprende."}}},{"kind":"match","prompt":"Pair each word from the course with what it does for you.","correctChain":["5 pairs"],"scrambledTokens":["De rien → Reply to thanks","Combien → Ask a price","La semaine dernière → Frame a finished story","Je suis allé → Movement in the past","Une pharmacie → Where you buy medicine"],"explain":"The final mixes politeness, numbers, past tense and travel — five different jobs, one sentence each.","match":{"pairs":[{"left":"De rien","right":"Reply to thanks"},{"left":"Combien","right":"Ask a price"},{"left":"La semaine dernière","right":"Frame a finished story"},{"left":"Je suis allé","right":"Movement in the past"},{"left":"Une pharmacie","right":"Where you buy medicine"}]}},{"kind":"listen","prompt":"Listen and type the order at the counter.","correctChain":["Je voudrais un thé"],"scrambledTokens":[],"explain":"Voudrais is the polite want and un thé is one syllable — thé ends in an aspirated h, so no liaison after it.","listen":{"phrase":"Je voudrais un thé","answers":["Je voudrais un thé","Je voudrais un the"]}},{"kind":"speak","prompt":"Admit you did not follow, out loud.","correctChain":["Je ne comprends pas"],"scrambledTokens":[],"explain":"Say both halves: zhuh nuh kohm-PRAH pa. Dropping the ne is casual speech, not the standard form.","speak":{"phrase":"Je ne comprends pas","passScore":75}}],"position":12},
  {"id":"french-questions","course_id":"french","title":"French Questions & Negation","theory":["French asks questions three ways: rising intonation (Tu parles français ?), est-ce que (Est-ce que tu parles français ?), or inversion (Parles-tu français ?). Inversion is the most formal; est-ce que is the safest everyday form.","Question words: où (where), quand (when), pourquoi (why), comment (how), qui (who), combien (how much/many), and qu’est-ce que (what). The question word comes first: Où est la gare ?","Negation wraps the verb in ne … pas: Je ne parle pas français. In speech the ne often disappears: Je parle pas français. Other pairs: ne … jamais (never), ne … rien (nothing). Use tu with friends and vous in formal situations."],"questions":[{"prompt":"Which is the formal way to ask “Do you speak French?”","correctChain":["Parlez-vous français ?"],"scrambledTokens":["Parlez-vous français ?","Tu parles français ?","Vous parlez français.","Parles-tu français ?"],"explain":"Inversion with vous is formal: Parlez-vous…? Tu parles…? is informal; the third option is a statement."},{"prompt":"Ask “Where is the station?”","correctChain":["Où","est","la","gare"],"scrambledTokens":["gare","Où","est","la","combien"],"explain":"Où est…? + place. La gare = the station; combien asks how much."},{"prompt":"“Je ne parle pas français” means…","correctChain":["I don’t speak French"],"scrambledTokens":["I don’t speak French","I speak French","I don’t study French","I want to learn French"],"explain":"Ne … pas surrounds the verb: ne parle pas = don’t speak."},{"prompt":"Say “I don’t eat meat”:","correctChain":["Je","ne","mange","pas","de","viande"],"scrambledTokens":["viande","Je","ne","mange","pas","de","jamais"],"explain":"Je ne mange pas de viande. After a negation, de replaces the article: pas de viande."},{"prompt":"“Je ne vois rien” means…","correctChain":["I see nothing"],"scrambledTokens":["I see nothing","I don’t see the water","I see everything","I don’t want to see"],"explain":"Ne … rien is the “nothing” pair. French keeps both halves around the verb."},{"kind":"match","prompt":"Pair each question word with the answer it demands.","correctChain":["5 pairs"],"scrambledTokens":["Où → A place","Quand → A time","Pourquoi → A reason","Combien → An amount","Qui → A person"],"explain":"Each word demands a different kind of answer: où wants a place, combien wants a number, pourquoi wants an excuse.","match":{"pairs":[{"left":"Où","right":"A place"},{"left":"Quand","right":"A time"},{"left":"Pourquoi","right":"A reason"},{"left":"Combien","right":"An amount"},{"left":"Qui","right":"A person"}]}},{"kind":"listen","prompt":"Listen and type the refusal.","correctChain":["Je ne mange pas de viande"],"scrambledTokens":[],"explain":"Ne … pas closes around the verb, and after a negation de replaces the article: pas de viande, not pas la viande.","listen":{"phrase":"Je ne mange pas de viande","answers":["Je ne mange pas de viande"],"misconceptions":{"Je ne mange pas la viande":"A negation turns the article into de: je ne mange pas de viande."}}},{"kind":"speak","prompt":"Ask how much something costs, out loud.","correctChain":["Combien ça coûte"],"scrambledTokens":[],"explain":"Combien is kohm-NYEN with the nasal, coûte is one syllable (koót) — the stress always falls on the last sound of the phrase.","speak":{"phrase":"Combien ça coûte","passScore":75}}],"position":13},
  {"id":"french-health","course_id":"french","title":"French Health & Emergencies","theory":["Say where it hurts with avoir mal à: J’ai mal à la tête (headache), J’ai mal au ventre (stomach ache). The preposition contracts: à + le = au, à + les = aux.","Symptoms: J’ai de la fièvre (I have a fever), je tousse (I cough). Ask for help with J’ai besoin d’un médecin (I need a doctor), Où est la pharmacie ?, or Appelez une ambulance (call an ambulance — formal).","Allergies: Je suis allergique aux arachides. For polite help say Pouvez-vous m’aider ?"],"questions":[{"prompt":"“J’ai mal à la tête” means…","correctChain":["I have a headache"],"scrambledTokens":["I have a headache","I have a stomach ache","My feet hurt","I am dizzy"],"explain":"Avoir mal à + body part: la tête = the head. Au ventre is the stomach."},{"prompt":"Say “I need a doctor”:","correctChain":["J’ai","besoin","d’un","médecin"],"scrambledTokens":["médecin","J’ai","besoin","d’un","pharmacie"],"explain":"J’ai besoin de… = I need…; de + un contracts to d’un médecin."},{"prompt":"“J’ai de la fièvre” means…","correctChain":["I have a fever"],"scrambledTokens":["I have a fever","I have a cough","I am cold","I have a headache"],"explain":"Avoir de la fièvre = to have a fever. Je tousse = I cough."},{"prompt":"Ask “Where is the pharmacy?”","correctChain":["Où","est","la","pharmacie"],"scrambledTokens":["pharmacie","Où","est","la","le"],"explain":"Où est la pharmacie ? — pharmacie is feminine, so la pharmacie."},{"prompt":"“Je suis allergique aux arachides” means…","correctChain":["Peanuts make me ill"],"scrambledTokens":["Peanuts make me ill","I love peanuts","I am carrying peanuts","Peanuts are expensive"],"explain":"Allergique à… names the trigger; à + les contracts to aux."},{"kind":"match","prompt":"Pair each symptom with what the pharmacist hears.","correctChain":["5 pairs"],"scrambledTokens":["J’ai mal à la tête → My head hurts","J’ai mal au ventre → My stomach hurts","J’ai de la fièvre → I have a fever","Je tousse → I cannot stop coughing","J’ai besoin d’un médecin → I need a doctor"],"explain":"Avoir mal à + body part for pain, avoir de la fièvre for fever, besoin de for need — three different frames, one visit.","match":{"pairs":[{"left":"J’ai mal à la tête","right":"My head hurts"},{"left":"J’ai mal au ventre","right":"My stomach hurts"},{"left":"J’ai de la fièvre","right":"I have a fever"},{"left":"Je tousse","right":"I cannot stop coughing"},{"left":"J’ai besoin d’un médecin","right":"I need a doctor"}]}},{"kind":"listen","prompt":"Listen and type the question they ask in the street.","correctChain":["Où est la pharmacie"],"scrambledTokens":[],"explain":"Où est + place is the survival question; pharmacie is feminine, so la pharmacie.","listen":{"phrase":"Où est la pharmacie","answers":["Où est la pharmacie","Ou est la pharmacie"]}},{"kind":"speak","prompt":"Tell someone to call an ambulance, out loud.","correctChain":["Appelez une ambulance"],"scrambledTokens":[],"explain":"Appelez is the vous imperative — ah-play-lay — and the final z links into une: ah-play-LAY-zoon.","speak":{"phrase":"Appelez une ambulance","passScore":75}}],"position":14},
  {"id":"french-adjectives","course_id":"french","title":"French Adjectives & Agreement","theory":["French adjectives match the gender and number of the noun. Masculine singular: un grand garçon; feminine singular adds -e: une grande fille. Plural adds -s: des grands garçons, des grandes filles.","Most adjectives follow the noun (un livre rouge), but BANGS adjectives (beauty, age, number, goodness, size) go before: un beau tableau, un vieux livre. Comparatives use plus... que (more... than) or moins... que (less... than)."],"questions":[{"prompt":"Which form of \"grand\" goes with \"une maison\" (a house, fem.)?","correctChain":["grande"],"scrambledTokens":["grande","grand","grands","grandes"],"explain":"Maison is feminine singular, so add -e: une grande maison."},{"prompt":"Say “The boy is tall” in French:","correctChain":["Le","garçon","est","grand"],"scrambledTokens":["grand","Le","garçon","est","grande"],"explain":"Garçon is masculine, so it takes grand without -e."},{"prompt":"“Plus rapide que le train” means…","correctChain":["Faster than the train"],"scrambledTokens":["Faster than the train","Slower than the train","As fast as the train","Behind the train"],"explain":"Plus... que is the comparative of superiority: faster than."},{"prompt":"Say “She is as tall as Marie”:","correctChain":["Elle","est","aussi","grande","que","Marie"],"scrambledTokens":["que","Elle","est","aussi","grande","Marie","plus"],"explain":"Aussi... que expresses equality with adjectives: as tall as."},{"prompt":"What is the irregular comparative of \"bon\" (good)?","correctChain":["Meilleur"],"scrambledTokens":["Meilleur","Plus bon","Pire","Moindre"],"explain":"Bon becomes meilleur (better), just as bueno becomes mejor in Spanish."},{"kind":"match","prompt":"Pair each French adjective with its opposite.","correctChain":["5 pairs"],"scrambledTokens":["Grand → Petit","Bon → Mauvais","Rapide → Lent","Chaud → Froid","Facile → Difficile"],"explain":"French adjective opposites: grand/petit, bon/mauvais, rapide/lent.","match":{"pairs":[{"left":"Grand","right":"Petit"},{"left":"Bon","right":"Mauvais"},{"left":"Rapide","right":"Lent"},{"left":"Chaud","right":"Froid"},{"left":"Facile","right":"Difficile"}]}},{"kind":"listen","prompt":"Listen and type the comparison.","correctChain":["Plus rapide que le train"],"scrambledTokens":[],"explain":"Plus is followed by que to introduce what you compare against.","listen":{"phrase":"Plus rapide que le train","answers":["Plus rapide que le train"]}},{"kind":"speak","prompt":"Say “The boy is tall” out loud in French.","correctChain":["Le garçon est grand"],"scrambledTokens":[],"explain":"luh gar-SON ay GRAN: the final d in grand is silent.","speak":{"phrase":"Le garçon est grand","passScore":75}}],"position":15},
  {"id":"french-politeness","course_id":"french","title":"French Politeness & Courtesy","theory":["French conversation requires polite framing. S’il vous plaît (please - formal) opens requests; Pardon or Excusez-moi gains attention or apologizes for an interruption.","Désolé means sorry. Thank with Merci beaucoup (Thank you very much); reply formally with Je vous en prie (You are very welcome) or casually with De rien (It’s nothing) or Pas de problème (No problem)."],"questions":[{"prompt":"You bump into someone on the metro. What do you say?","correctChain":["Pardon"],"scrambledTokens":["Pardon","Merci","De rien","Au revoir"],"explain":"Pardon is the immediate, instinctive French word when bumping into someone."},{"prompt":"Say “Excuse me, sir” politely:","correctChain":["Excusez-moi","monsieur"],"scrambledTokens":["monsieur","Excusez-moi","Merci","Bonjour"],"explain":"Excusez-moi is the formal imperative with the pronoun vous."},{"prompt":"“Je vous en prie” means…","correctChain":["You are welcome (formal)"],"scrambledTokens":["You are welcome (formal)","I am sorry","Please leave","Good night"],"explain":"Je vous en prie is the refined, respectful way to answer merci."},{"prompt":"Say “Thank you very much”:","correctChain":["Merci","beaucoup"],"scrambledTokens":["beaucoup","Merci","Bien","De"],"explain":"Merci beaucoup is the standard heartfelt thank-you."},{"prompt":"A colleague says “Merci”. What is a casual, friendly answer?","correctChain":["De rien"],"scrambledTokens":["De rien","S’il vous plaît","Désolé","Pardon"],"explain":"De rien (it is nothing) or Pas de souci is everyday and natural."},{"kind":"match","prompt":"Pair each polite French phrase with its meaning.","correctChain":["5 pairs"],"scrambledTokens":["Excusez-moi → Excuse me","Désolé → Sorry","Merci beaucoup → Thank you very much","Je vous en prie → You are welcome (formal)","De rien → You are welcome (casual)"],"explain":"Excusez-moi gets attention; désolé apologizes; je vous en prie and de rien answer thanks.","match":{"pairs":[{"left":"Excusez-moi","right":"Excuse me"},{"left":"Désolé","right":"Sorry"},{"left":"Merci beaucoup","right":"Thank you very much"},{"left":"Je vous en prie","right":"You are welcome (formal)"},{"left":"De rien","right":"You are welcome (casual)"}]}},{"kind":"listen","prompt":"Listen and type the sincere French apology.","correctChain":["Je suis vraiment désolé"],"scrambledTokens":[],"explain":"Vraiment = truly / really; désolé = sorry.","listen":{"phrase":"Je suis vraiment désolé","answers":["Je suis vraiment désolé"]}},{"kind":"speak","prompt":"Say “You are welcome” out loud casually.","correctChain":["De rien"],"scrambledTokens":[],"explain":"duh ree-EN: two quick beats, nasal on the final en.","speak":{"phrase":"De rien","passScore":75}}],"position":16},
  {"id":"french-introductions","course_id":"french","title":"French Introductions & Origins","theory":["Introduce yourself with Je m’appelle... (My name is...). Ask someone with Comment vous vous appelez ? (formal) or Comment tu t’appelles ? (casual).","Origins use venir de: D’où venez-vous ? -> Je viens de France / Je viens du Canada (de + le = du). Residence uses habiter: J’habite à Paris. Close with Enchanté (Pleased to meet you; women write enchantée)."],"questions":[{"prompt":"“Comment vous vous appelez ?” asks for…","correctChain":["Your name (formal)"],"scrambledTokens":["Your name (formal)","Your age","Where you live","Your country"],"explain":"Comment vous vous appelez ? is the formal polite way to ask someone’s name."},{"prompt":"Say “My name is Pierre”:","correctChain":["Je","m’appelle","Pierre"],"scrambledTokens":["Pierre","Je","m’appelle","Tu","t’appelles"],"explain":"Je m’appelle + name is the universal French introduction."},{"prompt":"“D’où venez-vous ?” means…","correctChain":["Where do you come from?"],"scrambledTokens":["Where do you come from?","Where are you going?","Where do you live?","What is your job?"],"explain":"D’où = from where; venez-vous = do you come (venir)."},{"prompt":"Say “I live in Paris”:","correctChain":["J’habite","à","Paris"],"scrambledTokens":["Paris","J’habite","à","Je","viens"],"explain":"J’habite + à + city: J’habite à Paris."},{"prompt":"Someone you just met says “Enchanté”. What does it mean?","correctChain":["Pleased to meet you"],"scrambledTokens":["Pleased to meet you","Goodbye","Good morning","Have a nice day"],"explain":"Enchanté (literally \"enchanted\") is the classic French handshake phrase."},{"kind":"match","prompt":"Pair each introduction line with its role.","correctChain":["5 pairs"],"scrambledTokens":["Je m’appelle → Stating your name","Je viens de → Stating where you are from","J’habite à → Stating where you live","Enchanté → Pleased to meet you","D’où viens-tu → Where are you from (casual)"],"explain":"Je m’appelle gives your name, je viens de gives your roots, and j’habite gives your town.","match":{"pairs":[{"left":"Je m’appelle","right":"Stating your name"},{"left":"Je viens de","right":"Stating where you are from"},{"left":"J’habite à","right":"Stating where you live"},{"left":"Enchanté","right":"Pleased to meet you"},{"left":"D’où viens-tu","right":"Where are you from (casual)"}]}},{"kind":"listen","prompt":"Listen and type the classic introduction greeting.","correctChain":["Enchanté de faire votre connaissance"],"scrambledTokens":[],"explain":"Enchanté de faire votre connaissance = Delighted to make your acquaintance.","listen":{"phrase":"Enchanté de faire votre connaissance","answers":["Enchanté de faire votre connaissance"]}},{"kind":"speak","prompt":"Say where you come from, out loud in French.","correctChain":["Je viens de France"],"scrambledTokens":[],"explain":"zhuh vee-EN duh FRAHNS: keep the nasal en clean and round.","speak":{"phrase":"Je viens de France","passScore":75}}],"position":17},
  {"id":"french-language","course_id":"french","title":"French Languages & Understanding","theory":["Ask about language ability with parler: Parlez-vous anglais ? (Do you speak English?) or casual Tu parles français ?. Reply with Je parle un peu français (I speak a little French).","If you lose the thread in Paris, rescue yourself with: Je ne comprends pas (I don’t understand), Pouvez-vous répéter, s’il vous plaît ? (Can you repeat, please?), and Parlez plus lentement (Speak more slowly)."],"questions":[{"prompt":"“Je ne comprends pas” means…","correctChain":["I do not understand"],"scrambledTokens":["I do not understand","I do not know","I do not speak","I am not listening"],"explain":"Comprendre = to understand. Je ne comprends pas is the essential tourist phrase."},{"prompt":"Ask “Do you speak English?” formally:","correctChain":["Parlez-vous","anglais"],"scrambledTokens":["anglais","Parlez-vous","Tu","parles"],"explain":"Parlez-vous anglais ? uses the polite inverted vous form."},{"prompt":"You need someone to speak more slowly. What do you say?","correctChain":["Plus lentement, s’il vous plaît."],"scrambledTokens":["Plus lentement, s’il vous plaît.","Plus vite, s’il vous plaît.","Je parle bien.","Au revoir."],"explain":"Lentement = slowly; plus lentement = more slowly."},{"prompt":"Say “I speak a little French”:","correctChain":["Je","parle","un","peu","français"],"scrambledTokens":["français","Je","parle","un","peu","beaucoup"],"explain":"Un peu = a little; beaucoup = a lot."},{"prompt":"“Pouvez-vous répéter ?” asks…","correctChain":["Can you repeat?"],"scrambledTokens":["Can you repeat?","Can you write it down?","Can you call a taxi?","Can you speak louder?"],"explain":"Répéter = to repeat. Pouvez-vous is the polite modal request."},{"kind":"match","prompt":"Pair each language phrase with what you are communicating.","correctChain":["5 pairs"],"scrambledTokens":["Je ne comprends pas → I do not understand","Plus lentement → Speak slower","Pouvez-vous répéter → Can you repeat","Un peu → A little bit","Parlez-vous anglais → Do you speak English"],"explain":"Je ne comprends pas signals confusion; plus lentement and répéter guide the speaker.","match":{"pairs":[{"left":"Je ne comprends pas","right":"I do not understand"},{"left":"Plus lentement","right":"Speak slower"},{"left":"Pouvez-vous répéter","right":"Can you repeat"},{"left":"Un peu","right":"A little bit"},{"left":"Parlez-vous anglais","right":"Do you speak English"}]}},{"kind":"listen","prompt":"Listen and type the plea for a slower pace in French.","correctChain":["Parlez plus lentement s’il vous plaît"],"scrambledTokens":[],"explain":"Parlez = speak; plus lentement = more slowly; s’il vous plaît = please.","listen":{"phrase":"Parlez plus lentement s’il vous plaît","answers":["Parlez plus lentement s’il vous plaît","Parlez plus lentement sil vous plait"]}},{"kind":"speak","prompt":"Admit you speak a little French, out loud.","correctChain":["Je parle un peu français"],"scrambledTokens":[],"explain":"zhuh PARL oon PUH frahn-SAY: un peu is the modest way to start speaking.","speak":{"phrase":"Je parle un peu français","passScore":75}}],"position":18},
  {"id":"french-money","course_id":"french","title":"French Shopping & Money","theory":["In French shops and markets, ask the price with Combien ça coûte ? (How much does that cost?) or simply C’est combien ? (How much is it?).","Comment on prices with C’est cher (It’s expensive) or Ce n’est pas cher (It’s not expensive). At payment, ask: Je peux payer par carte ? (Can I pay by card?) or en espèces (in cash). At a café, ask L’addition, s’il vous plaît (The check, please)."],"questions":[{"prompt":"“Combien ça coûte ?” asks…","correctChain":["How much does it cost?"],"scrambledTokens":["How much does it cost?","What is it?","Where is the shop?","When do you open?"],"explain":"Combien = how much; coûter = to cost. It is the primary shopping question."},{"prompt":"Say “It is too expensive”:","correctChain":["C’est","trop","cher"],"scrambledTokens":["cher","C’est","trop","bon","marché"],"explain":"Trop = too; cher = expensive."},{"prompt":"How do you ask “Can I pay by card?” in French?","correctChain":["Je peux payer par carte ?"],"scrambledTokens":["Je peux payer par carte ?","Avez-vous de la monnaie ?","C’est combien ?","Où est la caisse ?"],"explain":"Carte = card; payer = to pay. Par carte is the standard prepositional phrase."},{"prompt":"Ask for the check at a French bistro:","correctChain":["L’addition","s’il","vous","plaît"],"scrambledTokens":["plaît","L’addition","s’il","vous","Le"],"explain":"L’addition, s’il vous plaît = The bill/addition, please."},{"prompt":"“En espèces” means…","correctChain":["In cash"],"scrambledTokens":["In cash","By check","On credit","Tax-free"],"explain":"Espèces = cash coins and bills. Par carte = by card."},{"kind":"match","prompt":"Pair each French shopping phrase with its meaning.","correctChain":["5 pairs"],"scrambledTokens":["Combien ça coûte → How much does it cost","Trop cher → Too expensive","Par carte → By card","En espèces → In cash","L’addition → The restaurant check"],"explain":"Combien asks the cost, cher evaluates it, and l’addition closes the meal.","match":{"pairs":[{"left":"Combien ça coûte","right":"How much does it cost"},{"left":"Trop cher","right":"Too expensive"},{"left":"Par carte","right":"By card"},{"left":"En espèces","right":"In cash"},{"left":"L’addition","right":"The restaurant check"}]}},{"kind":"listen","prompt":"Listen and type the common question asked at the market.","correctChain":["C’est combien s’il vous plaît"],"scrambledTokens":[],"explain":"C’est combien = How much is it; s’il vous plaît = please.","listen":{"phrase":"C’est combien s’il vous plaît","answers":["C’est combien s’il vous plaît","Cest combien sil vous plait"]}},{"kind":"speak","prompt":"Ask for the check at a restaurant, out loud.","correctChain":["L’addition s’il vous plaît"],"scrambledTokens":[],"explain":"lah-dee-SYON seel voo PLAY: crisp and polite, understood instantly in every café.","speak":{"phrase":"L’addition s’il vous plaît","passScore":75}}],"position":19},
  {"id":"german-basics","course_id":"german","title":"German Basics","theory":["German starts crisp: Hallo (hello), Danke (thank you), Bitte (please/you are welcome). Every noun is capitalised — Morgen, Apfel, Frau.","German has three genders: der (masculine), die (feminine), das (neuter). Frau (woman) is feminine → die Frau."],"questions":[{"prompt":"\"Hallo\" means…","correctChain":["Hello"],"scrambledTokens":["Hello","Goodbye","Thank you","Please"],"explain":"Hallo works everywhere — shops, streets, friends."},{"prompt":"\"Danke\" means…","correctChain":["Thank you"],"scrambledTokens":["Thank you","Please","Sorry","Welcome"],"explain":"Danke schön = thank you very much."},{"prompt":"Say \"I eat apples\":","correctChain":["Ich","esse","Äpfel"],"scrambledTokens":["Äpfel","Ich","der","esse"],"explain":"Ich = I, esse = (I) eat, Äpfel = apples. Note the capital Ä!"},{"prompt":"Which article goes with \"Frau\" (woman)?","correctChain":["die"],"scrambledTokens":["die","der","das","den"],"explain":"Frau is feminine → die. Der Mann, das Kind."},{"prompt":"Say \"Good morning\":","correctChain":["Guten","Morgen"],"scrambledTokens":["Morgen","Hallo","Guten","Abend"],"explain":"Guten Morgen — capital M, always."},{"kind":"match","prompt":"Pair each German word with its meaning.","correctChain":["5 pairs"],"scrambledTokens":["Hallo → Hello","Danke → Thank you","Frau → Woman","Äpfel → Apples","Morgen → Morning"],"explain":"Every German noun is capitalised — Morgen and Äpfel wear their capitals even mid-sentence.","match":{"pairs":[{"left":"Hallo","right":"Hello"},{"left":"Danke","right":"Thank you"},{"left":"Frau","right":"Woman"},{"left":"Äpfel","right":"Apples"},{"left":"Morgen","right":"Morning"}]}},{"kind":"listen","prompt":"Listen and type the sentence about apples.","correctChain":["Ich esse Äpfel"],"scrambledTokens":[],"explain":"Ich = I, esse = (I) eat, Äpfel = apples. The umlaut Ä is a different vowel, not a decorated A.","listen":{"phrase":"Ich esse Äpfel","answers":["Ich esse Äpfel"]}},{"kind":"speak","prompt":"Greet someone before noon, out loud.","correctChain":["Guten Morgen"],"scrambledTokens":[],"explain":"Guten takes the \"goo-ten\" glide and Morgen stresses first: GOO-ten MOR-gen.","speak":{"phrase":"Guten Morgen","passScore":75}}],"position":1},
  {"id":"german-phrases","course_id":"german","title":"German Phrases","theory":["Go beyond words: ask how people are (Wie geht’s?), introduce yourself (Ich heiße…), and excuse yourself (Entschuldigung).","Danke grows to Vielen Dank; goodbyes split into formal Auf Wiedersehen and casual Tschüss."],"questions":[{"prompt":"\"Wie geht's?\" means…","correctChain":["How are you?"],"scrambledTokens":["How are you?","What is your name?","Where are you from?","What is that?"],"explain":"Short for Wie geht es dir — the casual check-in."},{"prompt":"Say \"My name is Anna\":","correctChain":["Ich","heiße","Anna"],"scrambledTokens":["Anna","Du","Ich","heiße"],"explain":"Ich heiße = I am called — the German introduction."},{"prompt":"\"Entschuldigung\" means…","correctChain":["Excuse me / Sorry"],"scrambledTokens":["Excuse me / Sorry","Thank you","Please","Welcome"],"explain":"Use it to pass by, apologise, or get attention."},{"prompt":"Say \"Thank you very much\":","correctChain":["Vielen","Dank"],"scrambledTokens":["Dank","Danke","Vielen","Bitte"],"explain":"Vielen Dank — never Danke viel!"},{"prompt":"\"Tschüss\" means…","correctChain":["Bye (informal)"],"scrambledTokens":["Bye (informal)","Good night","Good luck","Welcome back"],"explain":"Tschüss for friends; Auf Wiedersehen for formal farewells."},{"kind":"match","prompt":"Pair each phrase with what it does in a conversation.","correctChain":["5 pairs"],"scrambledTokens":["Wie geht's? → Ask how someone is","Ich heiße → Introduce yourself","Entschuldigung → Apologise or get past","Vielen Dank → Thank someone warmly","Tschüss → Say bye to a friend"],"explain":"Entschuldigung covers both sorry and excuse me — the register comes from your tone, not the word.","match":{"pairs":[{"left":"Wie geht's?","right":"Ask how someone is"},{"left":"Ich heiße","right":"Introduce yourself"},{"left":"Entschuldigung","right":"Apologise or get past"},{"left":"Vielen Dank","right":"Thank someone warmly"},{"left":"Tschüss","right":"Say bye to a friend"}]}},{"kind":"listen","prompt":"Listen and type how someone says their name.","correctChain":["Ich heiße Anna"],"scrambledTokens":[],"explain":"The ß (Eszett) is a sharp s — heisse and heiße are the same word spelled two ways.","listen":{"phrase":"Ich heiße Anna","answers":["Ich heiße Anna","Ich heisse Anna"]}},{"kind":"speak","prompt":"Thank someone generously, out loud.","correctChain":["Vielen Dank"],"scrambledTokens":[],"explain":"VEE-len DANK — stress the first syllable of each word and keep the vowel short and clean.","speak":{"phrase":"Vielen Dank","passScore":75}}],"position":2},
  {"id":"german-tenses","course_id":"german","title":"German Tenses Lab","theory":["Present tense: ich takes -e (spreche), du takes -st (sprichst), er takes -t (spricht); wir/sie take the bare infinitive (lernen).","Questions flip the verb first: Bist du müde? Haben memorises as: ich habe, du hast, er hat."],"questions":[{"prompt":"\"___ spreche Deutsch.\" (I speak German.)","correctChain":["Ich"],"scrambledTokens":["Ich","Du","Er","Wir"],"explain":"-e ending → ich: ich spreche."},{"prompt":"Say \"We are learning German\":","correctChain":["Wir","lernen","Deutsch"],"scrambledTokens":["Deutsch","Wir","lernen","lernt"],"explain":"Wir + bare verb: wir lernen. No ending added!"},{"prompt":"\"Er ___ ein Auto.\" (He has a car.)","correctChain":["hat"],"scrambledTokens":["habe","hast","hat","haben"],"explain":"Haben: ich habe, du hast, er/sie/es hat."},{"prompt":"Ask \"Are you tired?\":","correctChain":["Bist","du","müde"],"scrambledTokens":["müde","du","Bist","Bin"],"explain":"Bist du = are you (informal). Verb first in questions!"},{"prompt":"\"Sie (they) ___ müde.\" (They are tired.)","correctChain":["sind"],"scrambledTokens":["bin","bist","ist","sind"],"explain":"Sein: ich bin, du bist, er ist, wir/sie sind."},{"kind":"match","prompt":"Pair each subject with its haben (to have) ending.","correctChain":["4 pairs"],"scrambledTokens":["ich → habe","du → hast","er sie es → hat","wir → haben"],"explain":"du adds -st and er drops it entirely — and the plural just reuses the infinitive.","match":{"pairs":[{"left":"ich","right":"habe"},{"left":"du","right":"hast"},{"left":"er sie es","right":"hat"},{"left":"wir","right":"haben"}]}},{"kind":"listen","prompt":"Listen and type the sentence about learning German.","correctChain":["Wir lernen Deutsch"],"scrambledTokens":[],"explain":"Wir takes the bare infinitive: no ending at all. Deutsch wears its capital D because nouns are capitalised.","listen":{"phrase":"Wir lernen Deutsch","answers":["Wir lernen Deutsch"]}},{"kind":"speak","prompt":"Ask a friend whether they are tired, out loud.","correctChain":["Bist du müde"],"scrambledTokens":[],"explain":"Verb first turns it into a question — no word order change needed, just the ü: BYST doo MUE-deh.","speak":{"phrase":"Bist du müde","passScore":75}}],"position":3},
  {"id":"german-quiz","course_id":"german","title":"German Checkpoint","theory":["Checkpoint: greetings, phrases, gender, and tenses from the full German course."],"questions":[{"prompt":"\"Hallo\" means…","correctChain":["Hello"],"scrambledTokens":["Hello","Goodbye","Thank you","Please"],"explain":"Hallo works everywhere."},{"prompt":"Say \"I eat apples\":","correctChain":["Ich","esse","Äpfel"],"scrambledTokens":["Äpfel","Ich","der","esse"],"explain":"Ich = I, esse = (I) eat, Äpfel = apples. Capital Ä!"},{"prompt":"Which article goes with \"Mann\" (man)?","correctChain":["der"],"scrambledTokens":["der","die","das","den"],"explain":"Mann is masculine → der. Die Frau, das Kind."},{"prompt":"Say \"My name is Anna\":","correctChain":["Ich","heiße","Anna"],"scrambledTokens":["Anna","heiße","Ich","Du"],"explain":"Ich heiße Anna — introduce yourself anywhere."},{"prompt":"\"Danke\" means…","correctChain":["Thank you"],"scrambledTokens":["Thank you","Please","Sorry","Welcome"],"explain":"Danke schön = thank you very much."},{"prompt":"\"Sie (they) ___ müde.\" (They are tired.)","correctChain":["sind"],"scrambledTokens":["bin","bist","ist","sind"],"explain":"Tenses check: wir/sie + sein → sind."},{"kind":"text","prompt":"Ask a stranger in Berlin, politely, where the station is. Type the German question.","correctChain":["Wo ist der Bahnhof, bitte?"],"scrambledTokens":[],"explain":"Wo = where, ist = is, der Bahnhof = the station. Add bitte or Entschuldigung to soften a direct question to a stranger.","text":{"answers":["Wo ist der Bahnhof, bitte?","Entschuldigung, wo ist der Bahnhof?","Wo ist der Bahnhof?"],"misconceptions":{"Wo der Bahnhof ist?":"German questions put the verb second: wo ist der Bahnhof?"}}},{"kind":"match","prompt":"Pair each subject with its form of sein (to be).","correctChain":["4 pairs"],"scrambledTokens":["ich → bin","du → bist","er → ist","wir → sind"],"explain":"Sein is the most irregular verb in German — and the one you cannot speak without.","match":{"pairs":[{"left":"ich","right":"bin"},{"left":"du","right":"bist"},{"left":"er","right":"ist"},{"left":"wir","right":"sind"}]}},{"kind":"listen","prompt":"Listen and type the question a stranger would ask you.","correctChain":["Wo ist der Bahnhof"],"scrambledTokens":[],"explain":"Verb sits in second position even in a question: wo (1) ist (2) der Bahnhof (3).","listen":{"phrase":"Wo ist der Bahnhof","answers":["Wo ist der Bahnhof"]}},{"kind":"speak","prompt":"Take your leave of someone formally, out loud.","correctChain":["Auf Wiedersehen"],"scrambledTokens":[],"explain":"owf VEE-der-zay-en — literally \"to the seeing again\", so keep the two words welded together.","speak":{"phrase":"Auf Wiedersehen","passScore":75}}],"position":4},
  {"id":"german-greetings","course_id":"german","title":"German Greetings & Politeness","theory":["Hallo fits everywhere; Guten Morgen (morning), Guten Tag (day), Guten Abend (evening) ride the clock. Wie geht’s? asks a friend, Wie geht es Ihnen? respects an elder — du for friends, Sie for respect.","Always land with bitte, danke, and Entschuldigung. Gern geschehen answers danke; Willkommen welcomes all."],"questions":[{"prompt":"“Guten Abend” is said…","correctChain":["In the evening"],"scrambledTokens":["In the evening","In the morning","At noon","Only at bedtime"],"explain":"Morgen → Tag → Abend: morning, day, evening."},{"prompt":"Ask a friend “How is it going?”:","correctChain":["Wie","geht’s"],"scrambledTokens":["geht’s","Wie","geht","Ihnen"],"explain":"Wie geht’s? — du form, friends and family."},{"prompt":"“Wie geht es Ihnen?” differs from “Wie geht’s?” in…","correctChain":["Formality"],"scrambledTokens":["Formality","Tense","Number","Speed"],"explain":"Sie (capital S) = respect. du = friends."},{"prompt":"Answer “thanks” with “you are welcome”:","correctChain":["Gern","geschehen"],"scrambledTokens":["geschehen","Gern","Danke","Bitte"],"explain":"Danke → Gern geschehen. A tiny perfect pair."},{"prompt":"“Willkommen!” means…","correctChain":["Welcome!"],"scrambledTokens":["Welcome!","Goodbye!","Good luck!","Congratulations!"],"explain":"Willkommen opens every home, shop, and classroom."},{"kind":"match","prompt":"Pair each German phrase with the moment it fits.","correctChain":["5 pairs"],"scrambledTokens":["Hallo → Any hour of the day","Guten Morgen → Before noon","Guten Tag → Daytime","Guten Abend → After the light fades","Entschuldigung → You bumped into someone"],"explain":"German greets by clock, not by mood. Entschuldigung is the apology; bitte is never the apology.","match":{"pairs":[{"left":"Hallo","right":"Any hour of the day"},{"left":"Guten Morgen","right":"Before noon"},{"left":"Guten Tag","right":"Daytime"},{"left":"Guten Abend","right":"After the light fades"},{"left":"Entschuldigung","right":"You bumped into someone"}]}},{"kind":"listen","prompt":"Listen and type the formal question about how someone is.","correctChain":["Wie geht es Ihnen"],"scrambledTokens":[],"explain":"Ihnen is the formal you — the capital I is what marks respect; wie geht’s drops it all for friends.","listen":{"phrase":"Wie geht es Ihnen","answers":["Wie geht es Ihnen"],"misconceptions":{"Wie geht es dir":"Dir is the friend form — the recording used the formal Ihnen."}}},{"kind":"speak","prompt":"Thank someone warmly, out loud.","correctChain":["Danke schön"],"scrambledTokens":[],"explain":"The ch in schön is the soft sh sound — DAHN-keh shurn — and stress sits on schön.","speak":{"phrase":"Danke schön","passScore":75}}],"position":5},
  {"id":"german-numbers-time","course_id":"german","title":"German Numbers & Time","theory":["Count: eins, zwei, drei, vier, fünf, sechs, sieben, acht, neun, zehn — then zwanzig, dreißig… hundert. Es ist drei Uhr = it is 3 o’clock; halb vier = half past THREE (halfway TO four!).","Days run Montag to Sonntag; Monate Januar to Dezember. Heute = today, morgen = tomorrow, gestern = yesterday."],"questions":[{"prompt":"“Sieben” means…","correctChain":["Seven"],"scrambledTokens":["Seven","Six","Eight","Seventeen"],"explain":"Sechs 6, sieben 7, acht 8 — chant the run."},{"prompt":"Say “It is 3 o’clock”:","correctChain":["Es","ist","drei","Uhr"],"scrambledTokens":["Uhr","Es","drei","ist","sind"],"explain":"Es ist + number + Uhr. Half past is halb + NEXT hour."},{"prompt":"“Halb vier” means…","correctChain":["3:30"],"scrambledTokens":["3:30","4:30","4:00","3:00"],"explain":"Halb vier = halfway to four = 3:30. Famous trap!"},{"prompt":"Say “tomorrow”:","correctChain":["Morgen"],"scrambledTokens":["Gestern","Morgen","Heute","Abend"],"explain":"Gestern → heute → morgen: yesterday, today, tomorrow."},{"prompt":"“Viertel nach drei” means…","correctChain":["Quarter past three"],"scrambledTokens":["Quarter past three","Quarter to three","Half past three","Three quarters"],"explain":"Viertel nach = quarter past; vor = to."},{"kind":"match","prompt":"Pair each German number with its value.","correctChain":["5 pairs"],"scrambledTokens":["Sieben → 7","Acht → 8","Neun → 9","Zehn → 10","Zwanzig → 20"],"explain":"Sieben keeps its stress on the first syllable, and -zig becomes -ßig in writing: zwanzig, dreißig.","match":{"pairs":[{"left":"Sieben","right":"7"},{"left":"Acht","right":"8"},{"left":"Neun","right":"9"},{"left":"Zehn","right":"10"},{"left":"Zwanzig","right":"20"}]}},{"kind":"listen","prompt":"Listen and type the time being announced.","correctChain":["Es ist halb vier"],"scrambledTokens":[],"explain":"Halb vier is 3:30 — halfway toward four, not half past four.","listen":{"phrase":"Es ist halb vier","answers":["Es ist halb vier"],"misconceptions":{"Es ist vier Uhr":"Halb vier names the hour you are approaching, so it is half past three."}}},{"kind":"speak","prompt":"Say what time it is, out loud.","correctChain":["Es ist halb acht"],"scrambledTokens":[],"explain":"Acht starts with a hard glottal stop — ah-kt — and halb keeps its a long: HALP aht.","speak":{"phrase":"Es ist halb acht","passScore":75}}],"position":6},
  {"id":"german-food","course_id":"german","title":"German Food & Drink","theory":["Order like a Berliner: Ich möchte… (I would like…), Die Rechnung, bitte (the bill, please). Das Brot, der Käse, der Kaffee, die Milch, der Reis, das Hähnchen — hunger solved.","Ich habe Hunger = I am hungry (I HAVE hunger), ich habe Durst = thirsty. Ich mag = I like; ich liebe = I love. Articles matter: der/die/das!"],"questions":[{"prompt":"“Der Käse” means…","correctChain":["The cheese"],"scrambledTokens":["The cheese","The bread","The fish","The chicken"],"explain":"Käse = cheese, Brot = bread, Fisch = fish."},{"prompt":"Say “I would like coffee” politely:","correctChain":["Ich","möchte","Kaffee"],"scrambledTokens":["Kaffee","Ich","möchte","will"],"explain":"Ich möchte = polished wanting. Ich will = blunt."},{"prompt":"“Ich habe Hunger” literally means…","correctChain":["I have hunger"],"scrambledTokens":["I have hunger","I eat hunger","I am hunger","My hunger eats"],"explain":"German HAS hunger and thirst: Hunger, Durst."},{"prompt":"Ask for the bill politely:","correctChain":["Die","Rechnung"],"scrambledTokens":["Rechnung","Die","Speisekarte","Das"],"explain":"Die Rechnung, bitte — the magic exit words."},{"prompt":"“Das Hähnchen” means…","correctChain":["The chicken"],"scrambledTokens":["The chicken","The fish","The bread","The rice"],"explain":"Neuter das for Hähnchen; der for Käse. Learn noun + article!"},{"kind":"match","prompt":"Pair each grocery word with its article and meaning.","correctChain":["5 pairs"],"scrambledTokens":["Das Brot → Bread","Der Käse → Cheese","Die Milch → Milk","Der Kaffee → Coffee","Das Hähnchen → Chicken"],"explain":"The article is part of the noun: der, die, das decide how every later sentence agrees. Learn Brot and Käse as whole chunks.","match":{"pairs":[{"left":"Das Brot","right":"Bread"},{"left":"Der Käse","right":"Cheese"},{"left":"Die Milch","right":"Milk"},{"left":"Der Kaffee","right":"Coffee"},{"left":"Das Hähnchen","right":"Chicken"}]}},{"kind":"listen","prompt":"Listen and type the polite order.","correctChain":["Ich möchte einen Kaffee"],"scrambledTokens":[],"explain":"Möchte is the polite want, and einen marks Kaffee as the masculine accusative object — what you want wears -en.","listen":{"phrase":"Ich möchte einen Kaffee","answers":["Ich möchte einen Kaffee","Ich moechte einen Kaffee"],"misconceptions":{"Ich möchte ein Kaffee":"Kaffee is masculine, so the accusative is einen, not ein."}}},{"kind":"speak","prompt":"Order coffee the polite way, out loud.","correctChain":["Ich möchte einen Kaffee"],"scrambledTokens":[],"explain":"Möchte is two syllables with the soft ch: IRKH MEH-ktuh; adding bitte turns the order into a request.","speak":{"phrase":"Ich möchte einen Kaffee","passScore":75}}],"position":7},
  {"id":"german-travel","course_id":"german","title":"German Travel & Directions","theory":["Move with precision: Wo ist…? (where is…?), links (left), rechts (right), geradeaus (straight). Der Bahnhof, der Flughafen, das Hotel, die Toilette — the big four.","Ride anything: der Bus, der Zug, das Taxi. Wie viel kostet das? (how much?), Wann fährt er ab? (when does it leave?)."],"questions":[{"prompt":"“Wo ist der Bahnhof?” asks for…","correctChain":["The station’s location"],"scrambledTokens":["The station’s location","The station’s price","Station time","A farm road"],"explain":"Wo = where. Wo ist…? unlocks every city."},{"prompt":"Say “to the left”:","correctChain":["Nach","links"],"scrambledTokens":["links","Nach","rechts","geradeaus"],"explain":"Links = left, rechts = right, geradeaus = straight."},{"prompt":"“Wie viel kostet das?” asks for…","correctChain":["The price"],"scrambledTokens":["The price","The time","The weight","The name"],"explain":"Wie viel = how much. Kostet = costs."},{"prompt":"Ask where the hotel is:","correctChain":["Wo","ist","Hotel"],"scrambledTokens":["Hotel","Wo","das","ist"],"explain":"Wo ist…? + place. Das Hotel, der Bahnhof."},{"prompt":"“Der Zug” means…","correctChain":["The train"],"scrambledTokens":["The train","The bus","The taxi","The plane"],"explain":"Zug = train, Bus = bus, Flugzeug = plane."},{"kind":"match","prompt":"Pair each travel word with what it gives you.","correctChain":["5 pairs"],"scrambledTokens":["Nach links → Turn left","Nach rechts → Turn right","Geradeaus → Keep going straight","Der Bahnhof → Catch a train here","Wie viel → Ask the price"],"explain":"Links and rechts are mirror words that must be instant; wie viel asks cost while wo asks place.","match":{"pairs":[{"left":"Nach links","right":"Turn left"},{"left":"Nach rechts","right":"Turn right"},{"left":"Geradeaus","right":"Keep going straight"},{"left":"Der Bahnhof","right":"Catch a train here"},{"left":"Wie viel","right":"Ask the price"}]}},{"kind":"listen","prompt":"Listen and type the question about the station.","correctChain":["Wo ist der Bahnhof"],"scrambledTokens":[],"explain":"Wo ist + the noun with its article: der Bahnhof. Asking without the article still works, but the article is what you will be understood by.","listen":{"phrase":"Wo ist der Bahnhof","answers":["Wo ist der Bahnhof"],"misconceptions":{"Wo ist das Bahnhof":"Bahnhof is masculine: der Bahnhof, never das."}}},{"kind":"speak","prompt":"Give someone the route, out loud.","correctChain":["Geradeaus und dann links"],"scrambledTokens":[],"explain":"Geradeaus is stress-last (guh-rah-DOWS), dann links is short and flat — direction-giving in German never decorates.","speak":{"phrase":"Geradeaus und dann links","passScore":75}}],"position":8},
  {"id":"german-family","course_id":"german","title":"German Family & Descriptions","theory":["Meet die Familie: die Mutter, der Vater, der Bruder, die Schwester, der Sohn, die Tochter, der Freund. Mein/meine = my, dein/deine = your, sein/seine = his.","Describe with sein + adjective, matching gender and case: groß, klein, glücklich. Ich bin groß = I am tall. Capitalize every noun — always!"],"questions":[{"prompt":"“Die Schwester” means…","correctChain":["The sister"],"scrambledTokens":["The sister","The brother","The mother","The daughter"],"explain":"Schwester = sister, Bruder = brother. Die Familie grows."},{"prompt":"Say “my brothers” (more than one):","correctChain":["Meine","Brüder"],"scrambledTokens":["Brüder","Mein","Meine","Dein"],"explain":"Mein → meine before plurals/feminine: meine Brüder."},{"prompt":"“Ich bin groß” is said by…","correctChain":["A tall person"],"scrambledTokens":["A tall person","A big group","A tall building","Anyone large"],"explain":"Groß = tall/big, klein = small, glücklich = happy."},{"prompt":"Say “your (friend’s) mother”:","correctChain":["Deine","Mutter"],"scrambledTokens":["Mutter","Seine","Deine","Meine"],"explain":"Deine = your (friend), seine = his. Mutter = mother."},{"prompt":"“Der Sohn” means…","correctChain":["The son"],"scrambledTokens":["The son","The daughter","The father","The sun"],"explain":"Sohn = son, Tochter = daughter. (Die Sonne = the sun!)"},{"kind":"match","prompt":"Pair each family word with who it names.","correctChain":["5 pairs"],"scrambledTokens":["Die Mutter → Mother","Der Vater → Father","Der Bruder → Brother","Die Schwester → Sister","Die Tochter → Daughter"],"explain":"Tochter is daughter and die Sonne is the sun — one letter apart, and the -er ending hides in every pair here.","match":{"pairs":[{"left":"Die Mutter","right":"Mother"},{"left":"Der Vater","right":"Father"},{"left":"Der Bruder","right":"Brother"},{"left":"Die Schwester","right":"Sister"},{"left":"Die Tochter","right":"Daughter"}]}},{"kind":"listen","prompt":"Listen and type who you are talking about.","correctChain":["Das ist mein Bruder"],"scrambledTokens":[],"explain":"Mein agrees with a masculine noun; meine returns for die Schwester.","listen":{"phrase":"Das ist mein Bruder","answers":["Das ist mein Bruder"],"misconceptions":{"Das ist meine Bruder":"Bruder is masculine, so the possessive is mein — meine belongs to die Schwester."}}},{"kind":"speak","prompt":"Say you have a sister, out loud.","correctChain":["Ich habe eine Schwester"],"scrambledTokens":[],"explain":"Habe stresses the long i: HA-buh; eine is AY-nuh, and Schwester is two crisp SHWES-ter.","speak":{"phrase":"Ich habe eine Schwester","passScore":75}}],"position":9},
  {"id":"german-verbs-present","course_id":"german","title":"German Present Verbs","theory":["Stems wear endings: sprechen (speak) → ich spreche, du sprichst, er spricht, wir sprechen, sie sprechen. Note the vowel shift e→i in du/er for strong verbs!","Must-knows: ich bin (I am), ich habe (I have), ich möchte (I want), ich kann (I can). Sein describes identity; haben holds hunger, age, time."],"questions":[{"prompt":"Say “I speak German”:","correctChain":["Ich","spreche","Deutsch"],"scrambledTokens":["Deutsch","Ich","sprichst","spreche"],"explain":"Ich spreche, du sprichst, er spricht — feel the shift."},{"prompt":"“Wir essen” means…","correctChain":["We eat"],"scrambledTokens":["We eat","You eat","They ate","He eats"],"explain":"Regular -en verbs: ich esse, wir essen, sie essen."},{"prompt":"Say “I am happy” (sein):","correctChain":["Ich","bin","glücklich"],"scrambledTokens":["glücklich","Ich","bin","bist"],"explain":"Sein: ich bin, du bist, er ist. Ich bin glücklich!"},{"prompt":"“Ich kann” means…","correctChain":["I can"],"scrambledTokens":["I can","I want","I have","I go"],"explain":"Können → ich kann. Möchten → ich möchte."},{"prompt":"Say “They sell bread” (verkaufen):","correctChain":["Sie","verkaufen","Brot"],"scrambledTokens":["Brot","Sie","verkaufen","verkauft","verkaufe"],"explain":"Regular verbs: wir/sie/Sie keep the -en: verkaufen."},{"kind":"match","prompt":"Pair each verb form with the person it marks.","correctChain":["5 pairs"],"scrambledTokens":["Ich spreche → I speak","Du sprichst → You speak, informally","Er spricht → He speaks","Wir sprechen → We speak","Ich bin → I am"],"explain":"Sprechen is a strong verb: du and er shift the vowel e→i and du adds an extra -s. Wir and sie stay on the infinitive.","match":{"pairs":[{"left":"Ich spreche","right":"I speak"},{"left":"Du sprichst","right":"You speak, informally"},{"left":"Er spricht","right":"He speaks"},{"left":"Wir sprechen","right":"We speak"},{"left":"Ich bin","right":"I am"}]}},{"kind":"listen","prompt":"Listen and type what they claim to be good at.","correctChain":["Ich kann gut kochen"],"scrambledTokens":[],"explain":"kann + infinitive: the modal takes second position and the real verb is thrown to the very end — kochen.","listen":{"phrase":"Ich kann gut kochen","answers":["Ich kann gut kochen"]}},{"kind":"speak","prompt":"Say you are happy, out loud.","correctChain":["Ich bin glücklich"],"scrambledTokens":[],"explain":"Glücklich doubles the soft ch twice: GLIKH-likh; the ich ending is the same sound in every German word.","speak":{"phrase":"Ich bin glücklich","passScore":75}}],"position":10},
  {"id":"german-past","course_id":"german","title":"German Past Stories","theory":["Stories speak in Perfekt: ich habe gesprochen (I spoke), ich habe gegessen (I ate), ich bin gegangen (I went). Ge- + stem + -t/-en; movement verbs take sein.","The rebels: ich hatte (I had), ich war (I was), ich habe gemacht (I did/made). Gestern = yesterday, letzte Woche = last week."],"questions":[{"prompt":"“Ich habe gesprochen” means…","correctChain":["I spoke"],"scrambledTokens":["I spoke","I speak","I will speak","Speak!"],"explain":"Haben + gesprochen = finished past. Ich spreche = now."},{"prompt":"Say “I ate” (essen → gegessen):","correctChain":["Ich","habe","gegessen"],"scrambledTokens":["gegessen","Ich","habe","esse"],"explain":"Ge- + gess + -en: gegessen. Verb goes last!"},{"prompt":"“Ich bin gegangen” uses sein because…","correctChain":["Gehen is movement"],"scrambledTokens":["Gehen is movement","Gehen is long","Gegangen is formal","Haben is broken"],"explain":"Movement/change verbs take sein: gehen, kommen, fahren."},{"prompt":"Say “last week”:","correctChain":["Letzte","Woche"],"scrambledTokens":["Woche","Letzte","Gestern","Morgen"],"explain":"Letzte Woche frames any finished story."},{"prompt":"“Ich hatte” means…","correctChain":["I had"],"scrambledTokens":["I had","I have","I hate","I hated"],"explain":"Haben → hatte. Sein → war (ich war = I was)."},{"kind":"match","prompt":"Pair each past form with what it says.","correctChain":["5 pairs"],"scrambledTokens":["Ich habe gesprochen → I spoke","Ich habe gegessen → I ate","Ich bin gegangen → I went","Ich war → I was","Letzte Woche → When it happened"],"explain":"Perfekt is haben or sein plus a ge-…-t/-en participle at the end. Only movement and change of state borrow sein.","match":{"pairs":[{"left":"Ich habe gesprochen","right":"I spoke"},{"left":"Ich habe gegessen","right":"I ate"},{"left":"Ich bin gegangen","right":"I went"},{"left":"Ich war","right":"I was"},{"left":"Letzte Woche","right":"When it happened"}]}},{"kind":"listen","prompt":"Listen and type what happened last night.","correctChain":["Ich habe gestern gegessen"],"scrambledTokens":[],"explain":"The two verbs split the sentence: habe sits second, gegessen goes last — that frame is German past storytelling.","listen":{"phrase":"Ich habe gestern gegessen","answers":["Ich habe gestern gegessen"]}},{"kind":"speak","prompt":"Say you drove to Berlin, out loud.","correctChain":["Ich bin nach Berlin gefahren"],"scrambledTokens":[],"explain":"The ge- prefix is a short, soft keh — kuh-FAH-ren — and bin pulls the participle to the very end of the clause.","speak":{"phrase":"Ich bin nach Berlin gefahren","passScore":75}}],"position":11},
  {"id":"german-final","course_id":"german","title":"German Final Exam","theory":["Final exam: greetings, numbers, food, travel, family, present verbs, and past stories — the whole comprehensive course."],"questions":[{"prompt":"Ask a friend “How is it going?”:","correctChain":["Wie","geht’s"],"scrambledTokens":["geht’s","Wie","Ihnen","geht"],"explain":"Du form for friends: Wie geht’s?"},{"prompt":"“Halb vier” means…","correctChain":["3:30"],"scrambledTokens":["3:30","4:30","4:00","Half four (4:30)"],"explain":"Halfway TO four = 3:30. The classic trap — nailed!"},{"prompt":"Say “They sell bread”:","correctChain":["Sie","verkaufen","Brot"],"scrambledTokens":["Brot","Sie","verkaufen","verkauft","verkaufe"],"explain":"Sie + -en verb: sie verkaufen = they sell."},{"prompt":"“Ich habe Hunger” means…","correctChain":["I am hungry"],"scrambledTokens":["I am hungry","I hate hunger","I eat bread","I am thirsty"],"explain":"Ich habe Hunger = I have hunger. Durst = thirst."},{"prompt":"“Ich habe gesprochen” vs “ich spreche”: the difference is…","correctChain":["Past vs present"],"scrambledTokens":["Past vs present","Formal vs casual","Loud vs quiet","None"],"explain":"Perfekt marks the finished past: habe gesprochen = spoke."},{"prompt":"Ask “Where is the station?”:","correctChain":["Wo","ist","Bahnhof"],"scrambledTokens":["Bahnhof","Wo","der","ist"],"explain":"Wo ist…? + place. Der Bahnhof = the station."},{"prompt":"At a Berlin ticket machine, you need one ticket to the city centre. Which is most natural?","correctChain":["Eine Fahrkarte ins Zentrum, bitte. Was kostet das?"],"scrambledTokens":["Eine Fahrkarte ins Zentrum, bitte. Was kostet das?","Ich Fahrkarte Zentrum.","Fahrkarte bitte billig.","Wo ist die Fahrkarte?"],"explain":"Name the ticket, add bitte, then ask Was kostet das? — the everyday polite pattern."},{"kind":"text","prompt":"Type the German for “I don’t understand.”","correctChain":["Ich verstehe nicht."],"scrambledTokens":[],"explain":"The verb goes second in a main clause: Ich verstehe nicht. Nicht follows the verb it negates.","text":{"answers":["Ich verstehe nicht."],"misconceptions":{"Ich nicht verstehe":"German keeps the verb in second position: Ich verstehe nicht."}}},{"kind":"match","prompt":"Pair each word from the course with what it does for you.","correctChain":["5 pairs"],"scrambledTokens":["Gern geschehen → Reply to thanks","Wie viel → Ask a price","Letzte Woche → Frame a finished story","Ich bin gegangen → Movement in the past","Die Apotheke → Where you buy medicine"],"explain":"The final mixes politeness, numbers, past tense and travel — five different jobs, one phrase each.","match":{"pairs":[{"left":"Gern geschehen","right":"Reply to thanks"},{"left":"Wie viel","right":"Ask a price"},{"left":"Letzte Woche","right":"Frame a finished story"},{"left":"Ich bin gegangen","right":"Movement in the past"},{"left":"Die Apotheke","right":"Where you buy medicine"}]}},{"kind":"listen","prompt":"Listen and type the order at the counter.","correctChain":["Ich möchte einen Tee"],"scrambledTokens":[],"explain":"Möchte softens the want and Tee is one long syllable; the drink needs no article because it is uncountable here.","listen":{"phrase":"Ich möchte einen Tee","answers":["Ich möchte einen Tee","Ich moechte einen Tee"]}},{"kind":"speak","prompt":"Admit you did not follow, out loud.","correctChain":["Ich verstehe das nicht"],"scrambledTokens":[],"explain":"Verstehe stresses the last syllable — fer-STAY-eh — and nicht closes the clause like a door.","speak":{"phrase":"Ich verstehe das nicht","passScore":75}}],"position":12},
  {"id":"german-questions","course_id":"german","title":"German Questions & Negation","theory":["W-questions put the question word first and the verb second: Wo wohnst du? (Where do you live?), Wann kommst du? (When are you coming?), Warum lernst du Deutsch? (Why are you learning German?).","Yes/no questions start with the verb: Sprichst du Deutsch? (Do you speak German?), Hast du Zeit? (Do you have time?). The verb keeps its second position even when the subject follows it.","Negation: nicht for verbs, adjectives and definite nouns (Das ist nicht mein Buch); kein/keine for indefinite nouns (Ich habe keine Zeit, Ich spreche kein Deutsch). Use du with friends and Sie in formal situations."],"questions":[{"prompt":"Which is the correct question for “Where do you live?”","correctChain":["Wo wohnst du?"],"scrambledTokens":["Wo wohnst du?","Wo du wohnst?","Wohnst wo du?","Du wohnst wo?"],"explain":"Question word first, verb second: Wo + wohnst + du."},{"prompt":"Ask “Do you speak German?”","correctChain":["Sprichst","du","Deutsch"],"scrambledTokens":["Deutsch","Sprichst","du","sprechen"],"explain":"Yes/no question: verb first, then subject. Sprichst du Deutsch?"},{"prompt":"“Ich habe keine Zeit” means…","correctChain":["I have no time"],"scrambledTokens":["I have no time","I have lots of time","I am late","I don’t like time"],"explain":"Keine negates the indefinite noun Zeit: keine Zeit = no time."},{"prompt":"Say “I don’t speak German”:","correctChain":["Ich","spreche","kein","Deutsch"],"scrambledTokens":["Deutsch","Ich","spreche","kein","keine"],"explain":"Kein precedes the neuter noun Deutsch: kein Deutsch. Keine is for feminine/plural nouns."},{"prompt":"“Das ist nicht mein Buch” means…","correctChain":["That is not my book"],"scrambledTokens":["That is not my book","That is my book","That is no book","I don’t read that book"],"explain":"Nicht negates the definite phrase mein Buch; kein would negate an indefinite noun."},{"kind":"match","prompt":"Pair each question word with the answer it demands.","correctChain":["5 pairs"],"scrambledTokens":["Wo → A place","Wann → A time","Warum → A reason","Wie viel → An amount","Wer → A person"],"explain":"Every German W-word wants its own kind of answer, and the verb still comes second: Wo wohnst du?","match":{"pairs":[{"left":"Wo","right":"A place"},{"left":"Wann","right":"A time"},{"left":"Warum","right":"A reason"},{"left":"Wie viel","right":"An amount"},{"left":"Wer","right":"A person"}]}},{"kind":"listen","prompt":"Listen and type the flat denial.","correctChain":["Ich spreche kein Deutsch"],"scrambledTokens":[],"explain":"Deutsch is an indefinite noun here, so kein negates it — nicht Deutsch would deny a specific German you both already named.","listen":{"phrase":"Ich spreche kein Deutsch","answers":["Ich spreche kein Deutsch"],"misconceptions":{"Ich spreche nicht Deutsch":"Before an unnamed object German uses kein: ich spreche kein Deutsch."}}},{"kind":"speak","prompt":"Ask a friend if they have time, out loud.","correctChain":["Hast du Zeit"],"scrambledTokens":[],"explain":"A yes/no question just moves the verb to the front: Hast + du. The stress falls on Zeit — tseyt.","speak":{"phrase":"Hast du Zeit","passScore":75}}],"position":13},
  {"id":"german-health","course_id":"german","title":"German Health & Emergencies","theory":["Say what hurts with haben + a compound noun: Ich habe Kopfschmerzen (headache), Ich habe Bauchschmerzen (stomach ache). Also Ich habe Fieber (fever) and Ich huste (I cough).","Ask for help: Ich brauche einen Arzt (I need a doctor), Wo ist die Apotheke? (where is the pharmacy?), Rufen Sie einen Krankenwagen (call an ambulance — formal).","Allergies: Ich bin allergisch gegen Erdnüsse. For polite help say Können Sie mir helfen?"],"questions":[{"prompt":"“Ich habe Kopfschmerzen” means…","correctChain":["I have a headache"],"scrambledTokens":["I have a headache","I have a stomach ache","My feet hurt","I am dizzy"],"explain":"Kopf = head, Schmerzen = pain. Kopfschmerzen is the everyday headache."},{"prompt":"Say “I need a doctor”:","correctChain":["Ich","brauche","einen","Arzt"],"scrambledTokens":["Arzt","Ich","brauche","einen","Ärztin"],"explain":"Brauchen takes einen Arzt (masculine accusative); Ärztin is the female doctor."},{"prompt":"“Ich habe Fieber” means…","correctChain":["I have a fever"],"scrambledTokens":["I have a fever","I have a cough","I am cold","I have a headache"],"explain":"Fieber = fever. Ich huste = I cough."},{"prompt":"Ask “Where is the pharmacy?”","correctChain":["Wo","ist","die","Apotheke"],"scrambledTokens":["Apotheke","Wo","ist","die","der"],"explain":"Wo ist die Apotheke? — Apotheke is feminine, so die Apotheke."},{"prompt":"“Ich bin allergisch gegen Erdnüsse” means…","correctChain":["Peanuts make me ill"],"scrambledTokens":["Peanuts make me ill","I love peanuts","I am carrying peanuts","Peanuts are expensive"],"explain":"Allergisch gegen… names the trigger. Erdnüsse = peanuts."},{"kind":"match","prompt":"Pair each symptom with what the pharmacist hears.","correctChain":["5 pairs"],"scrambledTokens":["Ich habe Kopfschmerzen → My head hurts","Ich habe Bauchschmerzen → My stomach hurts","Ich habe Fieber → I have a fever","Ich huste → I cannot stop coughing","Ich brauche einen Arzt → I need a doctor"],"explain":"German bolts body parts onto Schmerzen: Kopf + Bauch. Fever and coughing get their own verbs.","match":{"pairs":[{"left":"Ich habe Kopfschmerzen","right":"My head hurts"},{"left":"Ich habe Bauchschmerzen","right":"My stomach hurts"},{"left":"Ich habe Fieber","right":"I have a fever"},{"left":"Ich huste","right":"I cannot stop coughing"},{"left":"Ich brauche einen Arzt","right":"I need a doctor"}]}},{"kind":"listen","prompt":"Listen and type the question they ask in the street.","correctChain":["Wo ist die Apotheke"],"scrambledTokens":[],"explain":"Apotheke is feminine, so die Apotheke — and the p is aspirated, the h is audible.","listen":{"phrase":"Wo ist die Apotheke","answers":["Wo ist die Apotheke"],"misconceptions":{"Wo ist der Apotheke":"Apotheke takes die; der belongs to der Bahnhof and der Arzt."}}},{"kind":"speak","prompt":"Ask someone politely for help, out loud.","correctChain":["Können Sie mir helfen"],"scrambledTokens":[],"explain":"Capital Sie marks respect, and the infinitive helfen closes the clause — KUR-nen zee meer HEL-fen.","speak":{"phrase":"Können Sie mir helfen","passScore":75}}],"position":14},
  {"id":"german-adjectives","course_id":"german","title":"German Adjectives & Comparison","theory":["Predicative adjectives (after sein or werden) never take endings: Das Auto ist schnell, Die Autos sind schnell. Only attributive adjectives before a noun decline.","Compare with -er + als: schneller als der Zug (faster than the train). For equality, use so... wie: Er ist so groß wie ich (He is as tall as me). Irregulars: gut -> besser -> am besten; viel -> mehr -> am meisten."],"questions":[{"prompt":"In “Das Haus ist schön”, why does “schön” have no ending?","correctChain":["It sits after the verb sein (predicative)"],"scrambledTokens":["It sits after the verb sein (predicative)","Because Haus is neuter","Because schön is irregular","It is an error in German"],"explain":"Predicative adjectives after sein/werden never take case endings in German."},{"prompt":"Say “The car is fast”:","correctChain":["Das","Auto","ist","schnell"],"scrambledTokens":["schnell","Das","Auto","ist","schnelle"],"explain":"Predicative: ist schnell, without any suffix."},{"prompt":"“Schneller als der Zug” means…","correctChain":["Faster than the train"],"scrambledTokens":["Faster than the train","Slower than the train","Next to the train","As fast as the train"],"explain":"Comparative suffix -er plus als means faster than."},{"prompt":"Say “He is as tall as Lukas”:","correctChain":["Er","ist","so","groß","wie","Lukas"],"scrambledTokens":["wie","Er","ist","so","groß","Lukas","als"],"explain":"So... wie expresses equality: as tall as."},{"prompt":"What is the comparative form of “gut” (good)?","correctChain":["Besser"],"scrambledTokens":["Besser","Guter","Mehr gut","Bestens"],"explain":"Gut is irregular: gut -> besser -> am besten."},{"kind":"match","prompt":"Pair each German adjective with its opposite.","correctChain":["5 pairs"],"scrambledTokens":["Groß → Klein","Schnell → Langsam","Gut → Schlecht","Heiß → Kalt","Einfach → Schwer"],"explain":"German adjective pairs: groß/klein, schnell/langsam, gut/schlecht.","match":{"pairs":[{"left":"Groß","right":"Klein"},{"left":"Schnell","right":"Langsam"},{"left":"Gut","right":"Schlecht"},{"left":"Heiß","right":"Kalt"},{"left":"Einfach","right":"Schwer"}]}},{"kind":"listen","prompt":"Listen and type the comparison.","correctChain":["Schneller als der Zug"],"scrambledTokens":[],"explain":"Schneller = faster; als = than (used with comparatives).","listen":{"phrase":"Schneller als der Zug","answers":["Schneller als der Zug"]}},{"kind":"speak","prompt":"Say “The car is fast” out loud in German.","correctChain":["Das Auto ist schnell"],"scrambledTokens":[],"explain":"dahs OW-toh ist SHNELL: the sch- makes a crisp sh sound.","speak":{"phrase":"Das Auto ist schnell","passScore":75}}],"position":15},
  {"id":"german-politeness","course_id":"german","title":"German Politeness & Courtesy","theory":["German manners use clear, direct courtesy words. Entschuldigung (excuse me) opens questions to strangers or apologizes for small mishaps; Verzeihung is a slightly more formal variant.","Es tut mir leid expresses heartfelt sympathy or deep apology. Bitte means please and you are welcome; Danke schön (thank you very much) is answered warmly with Gern geschehen (gladly done) or Keine Ursache (no trouble)."],"questions":[{"prompt":"You bump into someone at the train station. What do you say?","correctChain":["Entschuldigung"],"scrambledTokens":["Entschuldigung","Tschüss","Guten Appetit","Keine Ahnung"],"explain":"Entschuldigung is the natural, universal apology for bumping into someone."},{"prompt":"Say “Excuse me, please”:","correctChain":["Entschuldigung","bitte"],"scrambledTokens":["bitte","Entschuldigung","Danke","Hallo"],"explain":"Entschuldigung, bitte softens your entrance before asking a question."},{"prompt":"“Es tut mir leid” means…","correctChain":["I am sorry"],"scrambledTokens":["I am sorry","Thank you very much","You are welcome","Good evening"],"explain":"Es tut mir leid literally means “It does sorrow to me”."},{"prompt":"Say “Thank you very much”:","correctChain":["Danke","schön"],"scrambledTokens":["schön","Danke","Sehr","Bitte"],"explain":"Danke schön or Vielen Dank is the warm, standard thank-you."},{"prompt":"Someone says “Vielen Dank”. What is a friendly reply?","correctChain":["Gern geschehen"],"scrambledTokens":["Gern geschehen","Es tut mir leid","Entschuldigung","Auf Wiedersehen"],"explain":"Gern geschehen (gladly done) or Bitte schön replies to thanks."},{"kind":"match","prompt":"Pair each German courtesy word with its meaning.","correctChain":["5 pairs"],"scrambledTokens":["Entschuldigung → Excuse me","Es tut mir leid → I am sorry","Danke schön → Thank you very much","Gern geschehen → My pleasure / gladly done","Bitte schön → You are welcome"],"explain":"Entschuldigung gains attention, es tut mir leid apologizes, and gern geschehen answers thanks.","match":{"pairs":[{"left":"Entschuldigung","right":"Excuse me"},{"left":"Es tut mir leid","right":"I am sorry"},{"left":"Danke schön","right":"Thank you very much"},{"left":"Gern geschehen","right":"My pleasure / gladly done"},{"left":"Bitte schön","right":"You are welcome"}]}},{"kind":"listen","prompt":"Listen and type the sincere German apology.","correctChain":["Es tut mir sehr leid"],"scrambledTokens":[],"explain":"Sehr adds \"very\": Es tut mir sehr leid = I am very sorry.","listen":{"phrase":"Es tut mir sehr leid","answers":["Es tut mir sehr leid"]}},{"kind":"speak","prompt":"Say “Excuse me” out loud in German.","correctChain":["Entschuldigung bitte"],"scrambledTokens":[],"explain":"ent-SHOOL-dee-goong BIT-teh: articulate the three clear syllables.","speak":{"phrase":"Entschuldigung bitte","passScore":75}}],"position":16},
  {"id":"german-introductions","course_id":"german","title":"German Introductions & Origins","theory":["Introduce yourself with Ich heiße... (My name is...) or Mein Name ist... (My name is...). Ask someone with Wie heißen Sie? (formal) or Wie heißt du? (casual).","Talk about origins with kommen aus: Woher kommen Sie? -> Ich komme aus Deutschland / Ich komme aus den USA. Residence uses wohnen in: Ich wohne in Berlin. Close an introduction politely with Freut mich (Pleased to meet you)."],"questions":[{"prompt":"“Wie heißen Sie?” asks for…","correctChain":["Your name (formal)"],"scrambledTokens":["Your name (formal)","Your age","Where you live","Your country"],"explain":"Wie heißen Sie? is the polite formal way to ask a stranger their name."},{"prompt":"Say “My name is Thomas”:","correctChain":["Ich","heiße","Thomas"],"scrambledTokens":["Thomas","Ich","heiße","Du","heißt"],"explain":"Ich heiße + name is the most common German introduction."},{"prompt":"“Woher kommen Sie?” means…","correctChain":["Where do you come from?"],"scrambledTokens":["Where do you come from?","Where are you going?","Where do you work?","Where is the hotel?"],"explain":"Woher = from where; kommen = to come; Sie = formal you."},{"prompt":"Say “I live in Berlin”:","correctChain":["Ich","wohne","in","Berlin"],"scrambledTokens":["Berlin","Ich","wohne","in","aus"],"explain":"Wohnen + in + city: Ich wohne in Berlin."},{"prompt":"When introduced, someone says “Freut mich”. What does that mean?","correctChain":["Pleased to meet you"],"scrambledTokens":["Pleased to meet you","Goodbye","Good morning","Good night"],"explain":"Freut mich (short for Es freut mich) = It pleases me / Pleased to meet you."},{"kind":"match","prompt":"Pair each introduction phrase with its role.","correctChain":["5 pairs"],"scrambledTokens":["Ich heiße → Stating your name","Ich komme aus → Stating where you are from","Ich wohne in → Stating where you live","Freut mich → Pleased to meet you","Woher kommst du → Where are you from (casual)"],"explain":"Ich heiße gives your name, komme aus gives your homeland, and wohne in gives your town.","match":{"pairs":[{"left":"Ich heiße","right":"Stating your name"},{"left":"Ich komme aus","right":"Stating where you are from"},{"left":"Ich wohne in","right":"Stating where you live"},{"left":"Freut mich","right":"Pleased to meet you"},{"left":"Woher kommst du","right":"Where are you from (casual)"}]}},{"kind":"listen","prompt":"Listen and type the polite introduction greeting.","correctChain":["Sehr erfreut Sie kennenzulernen"],"scrambledTokens":[],"explain":"Sehr erfreut = very pleased; kennenzulernen = to get to know.","listen":{"phrase":"Sehr erfreut Sie kennenzulernen","answers":["Sehr erfreut Sie kennenzulernen"]}},{"kind":"speak","prompt":"Say where you come from, out loud in German.","correctChain":["Ich komme aus Deutschland"],"scrambledTokens":[],"explain":"ikh KOH-meh ows DOYTCH-lahnt: aus takes dative and Deutschland is Germany.","speak":{"phrase":"Ich komme aus Deutschland","passScore":75}}],"position":17},
  {"id":"german-language","course_id":"german","title":"German Languages & Understanding","theory":["Ask about languages with sprechen: Sprechen Sie Englisch? (Do you speak English?) or casual Sprichst du Deutsch?. Answer with Ich spreche ein bisschen Deutsch (I speak a little German).","When overwhelmed by fast German, rescue yourself with: Ich verstehe nicht (I don’t understand), Können Sie das bitte wiederholen? (Can you please repeat that?), and Bitte sprechen Sie langsamer (Please speak slower)."],"questions":[{"prompt":"“Ich verstehe nicht” means…","correctChain":["I do not understand"],"scrambledTokens":["I do not understand","I do not speak","I do not want","I do not hear"],"explain":"Verstehen = to understand. Ich verstehe nicht saves any awkward moment."},{"prompt":"Ask “Do you speak English?” formally:","correctChain":["Sprechen","Sie","Englisch"],"scrambledTokens":["Englisch","Sprechen","Sie","Sprichst","du"],"explain":"Sprechen Sie Englisch? — verb first for yes/no question, capital Sie for respect."},{"prompt":"You need someone to speak more slowly. What do you say?","correctChain":["Bitte sprechen Sie langsamer."],"scrambledTokens":["Bitte sprechen Sie langsamer.","Bitte sprechen Sie schneller.","Ich verstehe alles.","Auf Wiedersehen."],"explain":"Langsam = slow; langsamer = slower."},{"prompt":"Say “I speak a little German”:","correctChain":["Ich","spreche","ein","bisschen","Deutsch"],"scrambledTokens":["Deutsch","Ich","spreche","ein","bisschen","viel"],"explain":"Ein bisschen = a little bit. Ich spreche ein bisschen Deutsch."},{"prompt":"“Können Sie das bitte wiederholen?” asks…","correctChain":["Can you please repeat that?"],"scrambledTokens":["Can you please repeat that?","Can you please write that?","Can you speak louder?","Can you help me?"],"explain":"Wiederholen = to repeat; können = modal verb can."},{"kind":"match","prompt":"Pair each language phrase with what it communicates.","correctChain":["5 pairs"],"scrambledTokens":["Ich verstehe nicht → I do not understand","Bitte langsamer → Speak slower","Bitte wiederholen → Please repeat","Ein bisschen → A little bit","Sprechen Sie Englisch → Do you speak English"],"explain":"Ich verstehe nicht admits the gap; langsamer and wiederholen ask for adjustments.","match":{"pairs":[{"left":"Ich verstehe nicht","right":"I do not understand"},{"left":"Bitte langsamer","right":"Speak slower"},{"left":"Bitte wiederholen","right":"Please repeat"},{"left":"Ein bisschen","right":"A little bit"},{"left":"Sprechen Sie Englisch","right":"Do you speak English"}]}},{"kind":"listen","prompt":"Listen and type the polite request for slower speech in German.","correctChain":["Bitte sprechen Sie etwas langsamer"],"scrambledTokens":[],"explain":"Etwas = somewhat / a bit; langsamer = slower.","listen":{"phrase":"Bitte sprechen Sie etwas langsamer","answers":["Bitte sprechen Sie etwas langsamer"]}},{"kind":"speak","prompt":"Say you speak a little German, out loud.","correctChain":["Ich spreche ein bisschen Deutsch"],"scrambledTokens":[],"explain":"ikh SHPREH-kheh ayn BIS-khen DOYTCH: crisp and clear.","speak":{"phrase":"Ich spreche ein bisschen Deutsch","passScore":75}}],"position":18},
  {"id":"german-money","course_id":"german","title":"German Shopping & Money","theory":["In stores and bakeries, ask the price with Wie viel kostet das? (How much does that cost?) or Was kostet das?.","Assess prices with Das ist zu teuer (That is too expensive) or Das ist günstig (That is reasonably priced / good value). Payment: Kann ich mit Karte zahlen? (Can I pay with card?) or Bar zahlen (pay in cash). At a restaurant: Die Rechnung, bitte (The check, please)."],"questions":[{"prompt":"“Wie viel kostet das?” asks…","correctChain":["How much does that cost?"],"scrambledTokens":["How much does that cost?","What is that called?","Where is that from?","Who made that?"],"explain":"Wie viel = how much; kosten = to cost."},{"prompt":"Say “That is too expensive” in German:","correctChain":["Das","ist","zu","teuer"],"scrambledTokens":["teuer","Das","ist","zu","billig"],"explain":"Zu = too (excessive); teuer = expensive. Billig = cheap."},{"prompt":"How do you ask “Can I pay by card?” in German?","correctChain":["Kann ich mit Karte zahlen?"],"scrambledTokens":["Kann ich mit Karte zahlen?","Haben Sie Kleingeld?","Wo ist der Geldautomat?","Kostet das extra?"],"explain":"Karte = card; zahlen = to pay."},{"prompt":"Ask for the check at a German restaurant:","correctChain":["Die","Rechnung","bitte"],"scrambledTokens":["bitte","Die","Rechnung","Der","Kellner"],"explain":"Die Rechnung, bitte = The check/bill, please."},{"prompt":"“Bar zahlen” means…","correctChain":["To pay with cash"],"scrambledTokens":["To pay with cash","To pay with card","To drink at the bar","To pay tomorrow"],"explain":"Bar = cash in German: Barzahlung or bar zahlen."},{"kind":"match","prompt":"Pair each German shopping phrase with its meaning.","correctChain":["5 pairs"],"scrambledTokens":["Wie viel kostet das → How much does that cost","Zu teuer → Too expensive","Mit Karte → With card","Bar zahlen → Pay cash","Die Rechnung bitte → The check please"],"explain":"Wie viel kostet asks the price, teuer assesses it, and die Rechnung asks to settle.","match":{"pairs":[{"left":"Wie viel kostet das","right":"How much does that cost"},{"left":"Zu teuer","right":"Too expensive"},{"left":"Mit Karte","right":"With card"},{"left":"Bar zahlen","right":"Pay cash"},{"left":"Die Rechnung bitte","right":"The check please"}]}},{"kind":"listen","prompt":"Listen and type the price question.","correctChain":["Was kostet das bitte"],"scrambledTokens":[],"explain":"Was kostet das? is the everyday short form of Wie viel kostet das?.","listen":{"phrase":"Was kostet das bitte","answers":["Was kostet das bitte"]}},{"kind":"speak","prompt":"Ask for the restaurant check, out loud in German.","correctChain":["Die Rechnung bitte"],"scrambledTokens":[],"explain":"dee REKH-noong BIT-teh: polite, standard, and used in every German café or gasthaus.","speak":{"phrase":"Die Rechnung bitte","passScore":75}}],"position":19},
  {"id":"swahili-basics","course_id":"swahili","title":"Swahili Basics","theory":["Kiswahili is spoken by 200M+ people across East Africa. Greetings carry respect: Habari (hello/how are you), Asante (thank you), Karibu (welcome), Tafadhali (please).","Swahili verbs build like blocks: Ni-na-kula = I-am-eating. One word can be a whole sentence!"],"questions":[{"prompt":"\"Habari\" means…","correctChain":["Hello / How are you"],"scrambledTokens":["Hello / How are you","Thank you","Goodbye","Welcome"],"explain":"Habari = news — you ask for their news to say hello."},{"prompt":"\"Asante\" means…","correctChain":["Thank you"],"scrambledTokens":["Thank you","Please","Sorry","Welcome"],"explain":"Asante sana = thank you very much."},{"prompt":"Say \"I am eating mangoes\":","correctChain":["Ninakula","maembe"],"scrambledTokens":["maembe","Habari","Ninakula","asante"],"explain":"Ni-na-kula = I-am-eating; maembe = mangoes."},{"prompt":"\"Karibu\" means…","correctChain":["Welcome"],"scrambledTokens":["Welcome","Goodbye","Hurry","Sorry"],"explain":"Karibu welcomes every guest — hospitality in one word."},{"prompt":"Ask \"How are you?\":","correctChain":["Habari","yako"],"scrambledTokens":["yako","Asante","Habari","karibu"],"explain":"Habari yako? = your news? — the everyday greeting."},{"kind":"match","prompt":"Pair each Swahili word with its meaning.","correctChain":["5 pairs"],"scrambledTokens":["Habari → Hello / How are you","Asante → Thank you","Karibu → Welcome","Tafadhali → Please","Maembe → Mangoes"],"explain":"Habari literally asks after someone’s news; the other four are the politeness set.","match":{"pairs":[{"left":"Habari","right":"Hello / How are you"},{"left":"Asante","right":"Thank you"},{"left":"Karibu","right":"Welcome"},{"left":"Tafadhali","right":"Please"},{"left":"Maembe","right":"Mangoes"}]}},{"kind":"listen","prompt":"Listen and type the sentence about mangoes.","correctChain":["Ninakula maembe"],"scrambledTokens":[],"explain":"Ni-na-kula is one block: I + present -na- + eat. Maembe = mangoes.","listen":{"phrase":"Ninakula maembe","answers":["Ninakula maembe"]}},{"kind":"speak","prompt":"Ask a friend how they are, out loud.","correctChain":["Habari yako"],"scrambledTokens":[],"explain":"Every syllable gets its vowel: hah-BAR-ee YAH-koh, with the h breathed out.","speak":{"phrase":"Habari yako","passScore":75}}],"position":1},
  {"id":"swahili-phrases","course_id":"swahili","title":"Swahili Phrases","theory":["Speak in sentences: introduce yourself (Jina langu ni…), greet the morning (Habari za asubuhi?), and mind your manners (Tafadhali, Asante sana).","Pole expresses sympathy (sorry about that); polepole means slowly — the most useful word pair in Swahili."],"questions":[{"prompt":"Say \"My name is Amina\":","correctChain":["Jina","langu","ni","Amina"],"scrambledTokens":["Amina","Jina","langu","ni","Wewe"],"explain":"Jina langu ni = my name is — word by word."},{"prompt":"\"Habari za asubuhi?\" means…","correctChain":["Good morning?"],"scrambledTokens":["Good morning?","Good night?","How are you?","Where are you?"],"explain":"Asubuhi = morning. Jioni = evening."},{"prompt":"Say \"Thank you very much\":","correctChain":["Asante","sana"],"scrambledTokens":["sana","Asante","ndiyo","pole"],"explain":"Sana = very. Asante sana goes a long way."},{"prompt":"\"Pole\" means…","correctChain":["Sorry"],"scrambledTokens":["Sorry","Please","Welcome","Hurry"],"explain":"Pole = sorry (sympathy). Polepole = slowly!"},{"prompt":"\"Tafadhali\" means…","correctChain":["Please"],"scrambledTokens":["Please","Thank you","Sorry","Welcome"],"explain":"Tafadhali softens every request."},{"kind":"match","prompt":"Pair each phrase with what it does in a conversation.","correctChain":["5 pairs"],"scrambledTokens":["Jina langu ni → Introduce yourself","Habari za asubuhi → Greet in the morning","Asante sana → Thank someone warmly","Pole → Show sympathy","Tafadhali → Soften a request"],"explain":"Pole is sympathy (\"sorry that happened\"), not an admission of blame — that is samahani.","match":{"pairs":[{"left":"Jina langu ni","right":"Introduce yourself"},{"left":"Habari za asubuhi","right":"Greet in the morning"},{"left":"Asante sana","right":"Thank someone warmly"},{"left":"Pole","right":"Show sympathy"},{"left":"Tafadhali","right":"Soften a request"}]}},{"kind":"listen","prompt":"Listen and type how someone says their name.","correctChain":["Jina langu ni Amina"],"scrambledTokens":[],"explain":"Word for word: name my is Amina. No verb to conjugate — Swahili keeps introductions cheap.","listen":{"phrase":"Jina langu ni Amina","answers":["Jina langu ni Amina"]}},{"kind":"speak","prompt":"Thank someone warmly, out loud.","correctChain":["Asante sana"],"scrambledTokens":[],"explain":"ah-SAHN-teh SAH-nah — every syllable is pronounced, and sana doubles the gratitude.","speak":{"phrase":"Asante sana","passScore":75}}],"position":2},
  {"id":"swahili-tenses","course_id":"swahili","title":"Swahili Tenses Lab","theory":["Swahili verbs wear their tense in the middle: ni-na-soma (I am reading), ni-li-soma (I read), ni-ta-soma (I will read). -na- now, -li- past, -ta- future.","The subject prefix opens every verb: ni- (I), u- (you), a- (he/she), tu- (we), wa- (they)."],"questions":[{"prompt":"Pick the present tense: “I am reading”.","correctChain":["Ninasoma"],"scrambledTokens":["Ninasoma","Nilisoma","Nitasoma","Soma"],"explain":"ni-na-soma: I + present -na- + read."},{"prompt":"Say \"They read books every day\":","correctChain":["Wanasoma","vitabu","kila","siku"],"scrambledTokens":["siku","Wanasoma","kila","vitabu","jioni"],"explain":"wa-na-soma: they + present -na- + read. Kila siku = every day."},{"prompt":"“Alipika” means he cooked — the past marker is…","correctChain":["-li-"],"scrambledTokens":["-na-","-li-","-ta-","-me-"],"explain":"-li- = past: a-li-pika. -na- is present, -ta- is future."},{"prompt":"Say \"I will come tomorrow\":","correctChain":["Nitakuja","kesho"],"scrambledTokens":["kesho","Nitakuja","Ninakuja","Nilikuja"],"explain":"ni-ta-kuja: I + future -ta- + come. Kesho = tomorrow."},{"prompt":"“Tutakula” breaks down to…","correctChain":["We will eat"],"scrambledTokens":["We will eat","We are eating","We ate","Let us eat"],"explain":"tu-ta-kula: we + future -ta- + eat."},{"kind":"match","prompt":"Pair each subject prefix with the person it means.","correctChain":["5 pairs"],"scrambledTokens":["ni- → I","u- → you","a- → he or she","tu- → we","wa- → they"],"explain":"The prefix opens the verb, then the tense infix, then the root — one word, whole sentence.","match":{"pairs":[{"left":"ni-","right":"I"},{"left":"u-","right":"you"},{"left":"a-","right":"he or she"},{"left":"tu-","right":"we"},{"left":"wa-","right":"they"}]}},{"kind":"listen","prompt":"Listen and type the sentence about reading.","correctChain":["Wanasoma vitabu kila siku"],"scrambledTokens":[],"explain":"wa-na-soma = they-are-reading; kila siku = every day, the habit cue that makes the present fit.","listen":{"phrase":"Wanasoma vitabu kila siku","answers":["Wanasoma vitabu kila siku"]}},{"kind":"speak","prompt":"Say that you will come tomorrow, out loud.","correctChain":["Nitakuja kesho"],"scrambledTokens":[],"explain":"ni-ta-kuja is three morphemes welded into one word — nee-tah-KOO-jah, then KEH-shoh.","speak":{"phrase":"Nitakuja kesho","passScore":75}}],"position":3},
  {"id":"swahili-quiz","course_id":"swahili","title":"Swahili Checkpoint","theory":["Checkpoint: greetings, questions and negation, adjective agreement, health, verbs, and tenses from the full Swahili course."],"questions":[{"prompt":"\"Habari\" means…","correctChain":["Hello / How are you"],"scrambledTokens":["Hello / How are you","Thank you","Goodbye","Welcome"],"explain":"Habari = news — ask for their news to say hello."},{"prompt":"Say \"I am eating mangoes\":","correctChain":["Ninakula","maembe"],"scrambledTokens":["maembe","Habari","Ninakula","asante"],"explain":"Ni-na-kula = I-am-eating; maembe = mangoes."},{"prompt":"\"Karibu\" means…","correctChain":["Welcome"],"scrambledTokens":["Welcome","Goodbye","Hurry","Sorry"],"explain":"Karibu welcomes every guest."},{"prompt":"Say \"My name is Amina\":","correctChain":["Jina","langu","ni","Amina"],"scrambledTokens":["Amina","ni","Jina","langu"],"explain":"Jina langu ni Amina — introduce yourself anywhere."},{"prompt":"\"Asante\" means…","correctChain":["Thank you"],"scrambledTokens":["Thank you","Please","Sorry","Welcome"],"explain":"Asante sana = thank you very much."},{"prompt":"\"Tutakula\" breaks down to…","correctChain":["We will eat"],"scrambledTokens":["We will eat","We are eating","We ate","Let us eat"],"explain":"Tenses check: tu-ta-kula = we + future -ta- + eat."},{"prompt":"“Anafanya kazi” (he works) becomes which negative?","correctChain":["Hafanyi kazi"],"scrambledTokens":["Hafanyi kazi","Hafanya kazi","Anafanya kazi","Hakufanya kazi"],"explain":"Present negative: ha- replaces a-, -na- drops, and the final -a becomes -i — hafanyi kazi."},{"prompt":"Say “good children”:","correctChain":["Watoto","wazuri"],"scrambledTokens":["wazuri","Watoto","mzuri","wadogo"],"explain":"Watoto is class 2 plural, so the adjective takes wa-: watoto wazuri. Mzuri is the singular."},{"prompt":"Tell the doctor “My head hurts”:","correctChain":["Naumwa","na","kichwa"],"scrambledTokens":["kichwa","Naumwa","na","tumbo"],"explain":"Naumwa = it hurts me; na kichwa names the place. Naumwa na tumbo is the stomach."},{"kind":"text","prompt":"You are in a market in Nairobi and want the price of a shirt. Type the polite Swahili question.","correctChain":["Bei ya shati ni ngapi?"],"scrambledTokens":[],"explain":"Bei = price, ya = of, shati = shirt, ni ngapi = is how much. Bei gani? is the shorter alternative; either works in the market.","text":{"answers":["Bei ya shati ni ngapi?","Shati hili ni bei gani?","Bei gani ya shati?"],"misconceptions":{"Bei ya shati?":"A price label is not a question. Add ni ngapi? to ask how much."}}},{"kind":"match","prompt":"Pair each Swahili word or phrase with its meaning.","correctChain":["4 pairs"],"scrambledTokens":["Watoto → Children","Watoto wazuri → Good children","Naumwa na kichwa → My head hurts","Naumwa na tumbo → My stomach hurts"],"explain":"Watoto is a plural class, so the adjective must borrow its wa- prefix: wazuri, not mzuri.","match":{"pairs":[{"left":"Watoto","right":"Children"},{"left":"Watoto wazuri","right":"Good children"},{"left":"Naumwa na kichwa","right":"My head hurts"},{"left":"Naumwa na tumbo","right":"My stomach hurts"}]}},{"kind":"listen","prompt":"Listen and type the market question.","correctChain":["Bei ya shati ni ngapi"],"scrambledTokens":[],"explain":"Bei = price, ya shati = of the shirt, ni ngapi = is how much — the question marker comes last.","listen":{"phrase":"Bei ya shati ni ngapi","answers":["Bei ya shati ni ngapi"]}},{"kind":"speak","prompt":"Greet someone early in the morning, out loud.","correctChain":["Habari za asubuhi"],"scrambledTokens":[],"explain":"hah-BAR-ee zah ah-soo-BOO-hee — literally \"news of the morning\", so the za links the two halves.","speak":{"phrase":"Habari za asubuhi","passScore":75}}],"position":4},
  {"id":"swahili-greetings","course_id":"swahili","title":"Swahili Greetings & Replies","theory":["Swahili greets by time of day and by respect. Elders receive Shikamoo (I hold peace) and answer Marahaba (I accept). Peers trade Hujambo? (are you well?) and answer Sijambo (I am well). Habari za asubuhi? (morning news?) is answered Nzuri (good).","Never rush a greeting — ask twice, smile once. Follow any greeting with Uko vipi? (how are you, really?) and you sound like a local."],"questions":[{"prompt":"A young person greets an elder with “Shikamoo”. The elder replies…","correctChain":["Marahaba"],"scrambledTokens":["Marahaba","Sijambo","Nzuri","Karibu"],"explain":"Shikamoo → Marahaba. Respect offered, respect accepted."},{"prompt":"Greet a peer: “Are you well?”","correctChain":["Hujambo"],"scrambledTokens":["Sijambo","Hujambo","Marahaba","Nzuri"],"explain":"Hujambo? asks it; Sijambo answers it — a perfect pair."},{"prompt":"“Habari za asubuhi?” is the greeting for…","correctChain":["Morning"],"scrambledTokens":["Morning","Evening","Night","Midday meal"],"explain":"Asubuhi = morning. Jioni = evening, usiku = night."},{"prompt":"Answer “Habari yako?” (your news?) the short way:","correctChain":["Nzuri"],"scrambledTokens":["Mbaya","Nzuri","Pole","Tafadhali"],"explain":"Nzuri = good/fine. Short, warm, always correct."},{"prompt":"“Uko vipi?” means…","correctChain":["How are you (really)?"],"scrambledTokens":["How are you (really)?","Where are you?","Who are you?","How old are you?"],"explain":"Uko vipi deepens the greeting — ask it after Habari."},{"kind":"match","prompt":"Pair each greeting with who it is for.","correctChain":["5 pairs"],"scrambledTokens":["Shikamoo → A young person greeting an elder","Marahaba → The elder accepting that respect","Hujambo → Asking a peer if they are well","Sijambo → Answering Hujambo about yourself","Habari za asubuhi → The greeting before noon"],"explain":"Shikamoo and Marahaba are one-way respect: only the younger speaker opens with Shikamoo, and the elder never answers it with Sijambo.","match":{"pairs":[{"left":"Shikamoo","right":"A young person greeting an elder"},{"left":"Marahaba","right":"The elder accepting that respect"},{"left":"Hujambo","right":"Asking a peer if they are well"},{"left":"Sijambo","right":"Answering Hujambo about yourself"},{"left":"Habari za asubuhi","right":"The greeting before noon"}]}},{"kind":"listen","prompt":"Listen and type the morning greeting.","correctChain":["Habari za asubuhi"],"scrambledTokens":[],"explain":"Habari = news, za = of, asubuhi = morning — literally \"the news of the morning\".","listen":{"phrase":"Habari za asubuhi","answers":["Habari za asubuhi"],"misconceptions":{"Habari za jioni":"Jioni is evening. The greeting on the recording was asubuhi, the morning."}}},{"kind":"speak","prompt":"Greet an elder the respectful way, out loud.","correctChain":["Shikamoo"],"scrambledTokens":[],"explain":"Three even beats — shi-KA-moo. Swahili stress always lands on the second-to-last syllable, so lean on KA and let the final oo fall away.","speak":{"phrase":"Shikamoo","passScore":75}}],"position":5},
  {"id":"swahili-numbers","course_id":"swahili","title":"Swahili Numbers & Money","theory":["Count to ten: moja, mbili, tatu, nne, tano, sita, saba, nane, tisa, kumi. Eleven is kumi na moja (ten and one) — the pattern never breaks, so twenty is ishirini and one hundred is mia moja.","At the market ask Bei gani? (what price?) and hear Shilingi elfu tano (five thousand shillings). Pesa = money, ghali = expensive, rahisi = cheap."],"questions":[{"prompt":"“Tatu” means…","correctChain":["Three"],"scrambledTokens":["Three","Two","Five","Ten"],"explain":"Moja 1, mbili 2, tatu 3 — chant them in order."},{"prompt":"Say “ten”:","correctChain":["Kumi"],"scrambledTokens":["Tisa","Kumi","Saba","Nane"],"explain":"Tisa 9, kumi 10. Kumi na moja = 11."},{"prompt":"“Bei gani?” asks for…","correctChain":["The price"],"scrambledTokens":["The price","The time","The place","The name"],"explain":"Bei = price. Bei gani? opens every market bargain."},{"prompt":"Say “five thousand shillings”:","correctChain":["Shilingi","elfu","tano"],"scrambledTokens":["tano","Shilingi","elfu","mia"],"explain":"Elfu = thousand: elfu tano = 5000. Mia moja = 100."},{"prompt":"The seller names a wild price. You say “Ghali!” — meaning…","correctChain":["Expensive!"],"scrambledTokens":["Expensive!","Cheap!","Free!","Sold!"],"explain":"Ghali = expensive, rahisi = cheap. Bargain with a smile."},{"kind":"match","prompt":"Pair each Swahili number with its value.","correctChain":["5 pairs"],"scrambledTokens":["Moja → 1","Mbili → 2","Tatu → 3","Nne → 4","Kumi → 10"],"explain":"Kumi na moja is ten-and-one: Swahili never invents a new word for the teens, it just joins them with na.","match":{"pairs":[{"left":"Moja","right":"1"},{"left":"Mbili","right":"2"},{"left":"Tatu","right":"3"},{"left":"Nne","right":"4"},{"left":"Kumi","right":"10"}]}},{"kind":"listen","prompt":"Listen and type the price the seller calls out.","correctChain":["Shilingi elfu tano"],"scrambledTokens":[],"explain":"Elfu = thousand and tano = five, so 5,000. The noun comes first, then the number words in order.","listen":{"phrase":"Shilingi elfu tano","answers":["Shilingi elfu tano"],"misconceptions":{"Shilingi tano elfu":"Swahili keeps the counting order: elfu (thousand) before tano (five)."}}},{"kind":"speak","prompt":"Say five thousand shillings out loud.","correctChain":["Shilingi elfu tano"],"scrambledTokens":[],"explain":"Every vowel is its own beat — shi-LI-ngi EL-fu TA-no — and the stress always sits one syllable before the end of each word.","speak":{"phrase":"Shilingi elfu tano","passScore":75}}],"position":6},
  {"id":"swahili-noun-classes","course_id":"swahili","title":"Swahili Noun Classes","theory":["Every Swahili noun belongs to a family that changes its clothes. People take m-/wa-: mtoto (child) → watoto (children). Things take ki-/vi-: kiti (chair) → viti (chairs). Adjectives must match: mtoto mdogo (small child), viti vidogo (small chairs).","Learn the pair, not the word: mti/miti (tree/trees), kitabu/vitabu (book/books). The prefix tells you singular or plural at a glance."],"questions":[{"prompt":"“Watoto” means…","correctChain":["Children"],"scrambledTokens":["Children","Child","Chairs","Books"],"explain":"Mtoto → watoto: the m-/wa- people family."},{"prompt":"Make “chairs” from kiti:","correctChain":["Viti"],"scrambledTokens":["Viti","Kiti","Ziti","Miti"],"explain":"Ki-/vi- things family: kiti → viti, kitabu → vitabu."},{"prompt":"“Mtoto mdogo” shows…","correctChain":["Adjective agreement with the noun class"],"scrambledTokens":["Adjective agreement with the noun class","Past tense","A question","A plural verb"],"explain":"Mdogo matches m-: mtoto mdogo, but viti vidogo."},{"prompt":"Say “small books” (book = kitabu):","correctChain":["Vitabu","vidogo"],"scrambledTokens":["vidogo","Kitabu","Vitabu","kidogo"],"explain":"Plural first (vitabu), then the matching adjective (vidogo)."},{"prompt":"“Miti” (trees) is the plural of…","correctChain":["Mti"],"scrambledTokens":["Mti","Mto","Mtihani","Mita"],"explain":"M-/mi- family for plants: mti → miti."},{"kind":"match","prompt":"Pair each noun with its number and family.","correctChain":["5 pairs"],"scrambledTokens":["Kiti → One chair (ki- family)","Viti → Chairs (vi- family)","Kitabu → One book (ki- family)","Vitabu → Books (vi- family)","Miti → Trees (mi- family)"],"explain":"The prefix is the grammar: ki- singular things become vi- plural, and m- plants become mi-.","match":{"pairs":[{"left":"Kiti","right":"One chair (ki- family)"},{"left":"Viti","right":"Chairs (vi- family)"},{"left":"Kitabu","right":"One book (ki- family)"},{"left":"Vitabu","right":"Books (vi- family)"},{"left":"Miti","right":"Trees (mi- family)"}]}},{"kind":"listen","prompt":"Listen and type the phrase about the children.","correctChain":["Watoto wazuri"],"scrambledTokens":[],"explain":"Wa- class 2 plural carries both words: watoto (children) needs wazuri (good), never mzuri.","listen":{"phrase":"Watoto wazuri","answers":["Watoto wazuri"],"misconceptions":{"Watoto mzuri":"Mzuri agrees with one child (mtoto). Plural watoto takes the wa- form, wazuri."}}},{"kind":"speak","prompt":"Say a good book, out loud.","correctChain":["Kitabu kizuri"],"scrambledTokens":[],"explain":"Kitabu is ki-TA-boo and kizuri is ki-ZU-ri — the adjective repeats the noun’s ki- prefix, which is what makes the pair sound right.","speak":{"phrase":"Kitabu kizuri","passScore":75}}],"position":7},
  {"id":"swahili-family","course_id":"swahili","title":"Swahili Family & Possessives","theory":["Family first: mama (mother), baba (father), kaka (brother), dada (sister), mtoto (child), rafiki (friend). Possessives glue to the noun: mama yangu (my mother), baba yako (your father), kaka yake (his/her sibling).","Yangu = my, yako = your, yake = his/her, yetu = our. Jina langu ni… (my name is…) already taught you the pattern — now own it."],"questions":[{"prompt":"“Dada” means…","correctChain":["Sister"],"scrambledTokens":["Sister","Brother","Mother","Aunt"],"explain":"Dada = sister, kaka = brother. Shikamoo, dada!"},{"prompt":"Say “my mother”:","correctChain":["Mama","yangu"],"scrambledTokens":["yangu","Mama","yako","Baba"],"explain":"Mama + yangu. Swap in yako (your) or yake (his/her)."},{"prompt":"“Baba yako” means…","correctChain":["Your father"],"scrambledTokens":["Your father","My father","His father","Our father"],"explain":"Yako = your. Baba yako — ask about family with respect."},{"prompt":"Say “our friend” (friend = rafiki):","correctChain":["Rafiki","yetu"],"scrambledTokens":["yetu","Rafiki","yangu","yake"],"explain":"Yetu = our. Rafiki yetu — friendship, plural included."},{"prompt":"“Kaka yake” means…","correctChain":["His/her brother"],"scrambledTokens":["His/her brother","My brother","Your sister","Their mother"],"explain":"Yake = his/her. One word covers both — context decides."},{"kind":"match","prompt":"Pair each family word with who it names.","correctChain":["5 pairs"],"scrambledTokens":["Mama → Mother","Baba → Father","Kaka → Brother","Dada → Sister","Rafiki → Friend"],"explain":"Kaka and dada are siblings by gender, not by age — and the possessive comes after the noun: kaka yangu, my brother.","match":{"pairs":[{"left":"Mama","right":"Mother"},{"left":"Baba","right":"Father"},{"left":"Kaka","right":"Brother"},{"left":"Dada","right":"Sister"},{"left":"Rafiki","right":"Friend"}]}},{"kind":"listen","prompt":"Listen and type what your mother loves.","correctChain":["Mama yangu anapenda chai"],"scrambledTokens":[],"explain":"Mama yangu = my mother, then a-na-penda = she + present + like. The possessive never comes first.","listen":{"phrase":"Mama yangu anapenda chai","answers":["Mama yangu anapenda chai"]}},{"kind":"speak","prompt":"Say you love your family, out loud.","correctChain":["Ninapenda familia yangu"],"scrambledTokens":[],"explain":"Ninapenda is ni-na-PEN-da: the ni-na- block means I-am and -penda is love. Each word leans on its second-to-last syllable — fa-MI-lia, YA-ngu.","speak":{"phrase":"Ninapenda familia yangu","passScore":75}}],"position":8},
  {"id":"swahili-food-market","course_id":"swahili","title":"Swahili Food & Market","theory":["Eat your way fluent: chakula (food), wali (rice), samaki (fish), nyama (meat), matunda (fruit), maji (water), chai (tea). Hungry? Nasikia njaa (I feel hunger). Thirsty? Nasikia kiu.","At the sokoni (market): Nataka… (I want…), Kuna…? (is there…?), Bei gani? (what price?). Tafadhali and asante wrap every deal."],"questions":[{"prompt":"“Samaki” means…","correctChain":["Fish"],"scrambledTokens":["Fish","Meat","Rice","Fruit"],"explain":"Samaki = fish, nyama = meat, wali = rice."},{"prompt":"Say “I want water”:","correctChain":["Nataka","maji"],"scrambledTokens":["maji","Nataka","Chakula","Kuna"],"explain":"Nataka + anything: nataka chai, nataka matunda."},{"prompt":"“Nasikia njaa” means…","correctChain":["I am hungry"],"scrambledTokens":["I am hungry","I am thirsty","I am tired","I am full"],"explain":"Kusikia njaa = to feel hunger. Kiu = thirst."},{"prompt":"Ask “Is there rice?” at the market:","correctChain":["Kuna","wali"],"scrambledTokens":["wali","Kuna","Nataka","Bei"],"explain":"Kuna…? = is there…? Kuna samaki? Kuna matunda?"},{"prompt":"“Matunda” means…","correctChain":["Fruit"],"scrambledTokens":["Fruit","Vegetables","Spices","Bread"],"explain":"Matunda = fruit (plural). Tunda moja = one fruit."},{"kind":"match","prompt":"Pair each market word with what you are buying.","correctChain":["5 pairs"],"scrambledTokens":["Wali → Rice","Samaki → Fish","Nyama → Meat","Matunda → Fruit","Maji → Water"],"explain":"Wali and maji are uncountable — you never count them with a class prefix. Matunda is already the plural of tunda.","match":{"pairs":[{"left":"Wali","right":"Rice"},{"left":"Samaki","right":"Fish"},{"left":"Nyama","right":"Meat"},{"left":"Matunda","right":"Fruit"},{"left":"Maji","right":"Water"}]}},{"kind":"listen","prompt":"Listen and type the polite order for a drink.","correctChain":["Nataka maji tafadhali"],"scrambledTokens":[],"explain":"Nataka = I want, maji = water, tafadhali = please. Swahili puts the politeness at either end, never in the middle.","listen":{"phrase":"Nataka maji tafadhali","answers":["Nataka maji tafadhali"]}},{"kind":"speak","prompt":"Tell the cook you are hungry, out loud.","correctChain":["Nasikia njaa"],"scrambledTokens":[],"explain":"Say every vowel of nasikia separately — na-see-kee-ah — and njaa is one long beat: the nj is a single sound, like the j in jam.","speak":{"phrase":"Nasikia njaa","passScore":75}}],"position":9},
  {"id":"swahili-travel","course_id":"swahili","title":"Swahili Travel & Directions","theory":["Move like a local: Wapi? (where?), Hapa (here), Pale (there), kushoto (left), kulia (right), moja kwa moja (straight). Basi = bus, daladala = minibus, nauli = fare, tiketi = ticket.","Ask Wapi stesheni? (where is the station?) and follow Twende! (let us go!). Karibu Tanzania — safari njema (safe journey)!"],"questions":[{"prompt":"“Wapi?” means…","correctChain":["Where?"],"scrambledTokens":["Where?","When?","How?","Who?"],"explain":"Wapi = where. Wapi choo? has saved a thousand travellers."},{"prompt":"Ask “Where is the bus?”:","correctChain":["Basi","liko","wapi"],"scrambledTokens":["wapi","Basi","liko","Hapa"],"explain":"Basi liko wapi? Liko = it-is-located. Hapa = here."},{"prompt":"“Kushoto” means…","correctChain":["Left"],"scrambledTokens":["Left","Right","Straight","Back"],"explain":"Kushoto = left, kulia = right, moja kwa moja = straight."},{"prompt":"Say “Let us go!”:","correctChain":["Twende"],"scrambledTokens":["Twende","Njoo","Kaa","Rudi"],"explain":"Twende! — one word, whole journey. Safari njema!"},{"prompt":"“Nauli” is the…","correctChain":["Fare"],"scrambledTokens":["Fare","Ticket","Bus","Driver"],"explain":"Nauli = fare you pay; tiketi = the ticket itself."},{"kind":"match","prompt":"Pair each travel word with what it tells you.","correctChain":["5 pairs"],"scrambledTokens":["Kushoto → Turn left","Kulia → Turn right","Moja kwa moja → Keep going straight","Wapi → Ask where something is","Nauli → What you pay the driver"],"explain":"Kushoto and kulia are the ki-/ku- locative forms; nauli is the fare, tiketi the paper — pay one, rarely get the other.","match":{"pairs":[{"left":"Kushoto","right":"Turn left"},{"left":"Kulia","right":"Turn right"},{"left":"Moja kwa moja","right":"Keep going straight"},{"left":"Wapi","right":"Ask where something is"},{"left":"Nauli","right":"What you pay the driver"}]}},{"kind":"listen","prompt":"Listen and type the question about the bus.","correctChain":["Basi liko wapi"],"scrambledTokens":[],"explain":"Liko is the class 9/10 locative of \"to be\": basi liko wapi = the bus, where is it. Hapa answers it (here).","listen":{"phrase":"Basi liko wapi","answers":["Basi liko wapi"]}},{"kind":"speak","prompt":"Tell your companions to go, out loud.","correctChain":["Twende sasa"],"scrambledTokens":[],"explain":"TWEN-deh SAH-sah: the imperative twende is one breath, and sasa (now) makes it a departure instead of a suggestion.","speak":{"phrase":"Twende sasa","passScore":75}}],"position":10},
  {"id":"swahili-verbs-daily","course_id":"swahili","title":"Swahili Daily Verbs","theory":["Five verbs run your day: -enda (go), -ja (come), -fanya (do), -penda (like/love), -taka (want). Conjugate across people in the present: ninaenda (I go), unaenda (you go), anaenda (he/she goes), tunaenda (we go), wanaenda (they go).","Same skeleton every time: subject prefix + -na- + stem. Swap the stem, keep the rhythm — ninapenda, unataka, wanafanya."],"questions":[{"prompt":"Say “I love tea” (love = -penda):","correctChain":["Ninapenda","chai"],"scrambledTokens":["chai","Ninapenda","Unapenda","Anapenda"],"explain":"Ni-na-penda: I + present + love. Chai on the side."},{"prompt":"“Tunaenda” means…","correctChain":["We are going"],"scrambledTokens":["We are going","You are going","They are going","I am going"],"explain":"Tu- = we. Tunaenda sokoni = we are going to the market."},{"prompt":"Say “You (one person) want water”:","correctChain":["Unataka","maji"],"scrambledTokens":["maji","Unataka","Ninataka","Anataka"],"explain":"U-na-taka: you + present + want."},{"prompt":"“Wanafanya” breaks down to…","correctChain":["They are doing"],"scrambledTokens":["They are doing","We are doing","He is doing","I am doing"],"explain":"Wa-na-fanya: they + present + do."},{"prompt":"Say “She is coming” (come = -ja):","correctChain":["Anakuja"],"scrambledTokens":["Ninakuja","Anakuja","Unakuja","Tunakuja"],"explain":"A-na-kuja: she + present + come. -ja doubles the u."},{"kind":"match","prompt":"Pair each verb form with the person it marks.","correctChain":["5 pairs"],"scrambledTokens":["Ninaenda → I am going","Unaenda → You are going","Anaenda → She is going","Tunaenda → We are going","Wanaenda → They are going"],"explain":"Only the first letter changes: ni-, u-, a-, tu-, wa-. The -na- in the middle is always the present tense.","match":{"pairs":[{"left":"Ninaenda","right":"I am going"},{"left":"Unaenda","right":"You are going"},{"left":"Anaenda","right":"She is going"},{"left":"Tunaenda","right":"We are going"},{"left":"Wanaenda","right":"They are going"}]}},{"kind":"listen","prompt":"Listen and type where they are going.","correctChain":["Wanaenda sokoni"],"scrambledTokens":[],"explain":"Wa-na-enda = they are going, and sokoni is the locative of soko — the -ni ending means \"to/at the\".","listen":{"phrase":"Wanaenda sokoni","answers":["Wanaenda sokoni"]}},{"kind":"speak","prompt":"Say you are going to the market, out loud.","correctChain":["Ninaenda sokoni"],"scrambledTokens":[],"explain":"Ninaenda stacks three blocks you already know: ni (I) + na (present) + enda (go). Sokoni is soko with the locative -ni, which does the work of \"to\".","speak":{"phrase":"Ninaenda sokoni","passScore":75}}],"position":11},
  {"id":"swahili-time-tense","course_id":"swahili","title":"Swahili Time & Perfect Tense","theory":["Swahili time starts at sunrise: saa moja asubuhi = 7am (hour one of the morning), saa kumi na mbili jioni = 6pm. Jana = yesterday, leo = today, kesho = tomorrow, sasa = now.","Finished actions wear -me-: nimemaliza (I have finished), umekula? (have you eaten?). -me- = done and dusted; -li- = simple past story."],"questions":[{"prompt":"“Kesho” means…","correctChain":["Tomorrow"],"scrambledTokens":["Tomorrow","Yesterday","Today","Now"],"explain":"Jana → leo → kesho: yesterday, today, tomorrow."},{"prompt":"Say “I have finished” (finish = -maliza):","correctChain":["Nimemaliza"],"scrambledTokens":["Nilimaliza","Nimemaliza","Nitamaliza","Ninamaliza"],"explain":"Ni-me-maliza: -me- marks the completed state."},{"prompt":"“Saa moja asubuhi” is…","correctChain":["7 in the morning"],"scrambledTokens":["7 in the morning","1 in the morning","12 noon","6 in the evening"],"explain":"Swahili clocks start at 6am: saa moja = 7am. Asubuhi = morning."},{"prompt":"Ask “Have you eaten?” (eat = -kula):","correctChain":["Umekula"],"scrambledTokens":["Ulikula","Umekula","Utakula","Unakula"],"explain":"U-me-kula?: -me- asks about the finished state."},{"prompt":"“Sasa” means…","correctChain":["Now"],"scrambledTokens":["Now","Later","Never","Soon"],"explain":"Sasa = now. Twende sasa! = let us go now!"},{"kind":"match","prompt":"Pair each time word with when it means.","correctChain":["5 pairs"],"scrambledTokens":["Jana → Yesterday","Leo → Today","Kesho → Tomorrow","Sasa → Right now","Nimemaliza → A finished action"],"explain":"The -me- in nimemaliza is not a tense of when — it is a tense of done: the work is behind you.","match":{"pairs":[{"left":"Jana","right":"Yesterday"},{"left":"Leo","right":"Today"},{"left":"Kesho","right":"Tomorrow"},{"left":"Sasa","right":"Right now"},{"left":"Nimemaliza","right":"A finished action"}]}},{"kind":"listen","prompt":"Listen and type the report about work.","correctChain":["Nimemaliza kazi"],"scrambledTokens":[],"explain":"Ni-me-maliza: I + completed + finish. Kazi is work, so the whole phrase means I have finished the work.","listen":{"phrase":"Nimemaliza kazi","answers":["Nimemaliza kazi"]}},{"kind":"speak","prompt":"Say you will come tomorrow, out loud.","correctChain":["Nitakuja kesho"],"scrambledTokens":[],"explain":"The future lives in -ta-: ni-ta-kuja, I will come. Swap -ta- for -na- and the same sentence reports that you are coming right now.","speak":{"phrase":"Nitakuja kesho","passScore":75}}],"position":12},
  {"id":"swahili-final","course_id":"swahili","title":"Swahili Final Exam","theory":["Final exam: greetings, numbers, noun classes, family, food, travel, questions and negation, adjectives, health, verbs, and time — the whole comprehensive course."],"questions":[{"prompt":"Greet an elder respectfully and pick the reply pair:","correctChain":["Shikamoo"],"scrambledTokens":["Marahaba","Shikamoo","Sijambo","Nzuri"],"explain":"Shikamoo opens it; the elder answers Marahaba."},{"prompt":"“Vitabu vidogo” means…","correctChain":["Small books"],"scrambledTokens":["Small books","Big books","Small chairs","My books"],"explain":"Ki-/vi- agreement: vitabu + vidogo. Class match wins."},{"prompt":"Say “We are going to the market tomorrow”:","correctChain":["Tunaenda","sokoni","kesho"],"scrambledTokens":["kesho","Tunaenda","sokoni","jana"],"explain":"Tu-na-enda + sokoni (to the market) + kesho."},{"prompt":"“Umekula?” asks…","correctChain":["Have you eaten?"],"scrambledTokens":["Have you eaten?","Will you eat?","Are you eating?","Did you cook?"],"explain":"-me- perfect tense: the finished state, asked politely."},{"prompt":"“Bei gani?” + “Ghali!” means the buyer thinks it is…","correctChain":["Too expensive"],"scrambledTokens":["Too expensive","Too cheap","Free","Sold out"],"explain":"Price asked, price judged: ghali = expensive, rahisi = cheap."},{"prompt":"Say “My name is Amina, I love tea”:","correctChain":["Jina","langu","ni","Amina"],"scrambledTokens":["Amina","Jina","ni","langu"],"explain":"Introduce first: jina langu ni… — then ninapenda chai!"},{"prompt":"“Je, una pesa?” is asking…","correctChain":["Do you have money?"],"scrambledTokens":["Do you have money?","Where is the money?","How much is it?","Do you want money?"],"explain":"Je opens a yes/no question and una pesa is “you have money” — the answer is ndiyo or hapana."},{"prompt":"“Yeye ni mrefu kuliko mimi” means…","correctChain":["He is taller than me"],"scrambledTokens":["He is taller than me","He is as tall as me","I am taller than him","He is very tall"],"explain":"Kuliko = than, and mrefu takes the m- agreement of a class 1 person."},{"prompt":"Say “I have a fever”:","correctChain":["Nina","homa"],"scrambledTokens":["homa","Nina","kikohozi","dawa"],"explain":"Nina = I have; homa = fever. Kikohozi is a cough and dawa is medicine."},{"prompt":"At a market stall in Dar es Salaam, you want the price and two mangoes. Which pair is most natural?","correctChain":["Bei gani? Naomba maembe mawili."],"scrambledTokens":["Bei gani? Naomba maembe mawili.","Bei gani? Naomba maembe mbili.","Bei gani? Naomba embe mawili.","Bei gani? Nataka maembe mawili sana."],"explain":"Bei gani? asks the price; naomba is a polite request. Maembe is class 6, so the pair is mawili, not mbili."},{"kind":"text","prompt":"Type the Swahili for “I don’t understand.”","correctChain":["Sielewi."],"scrambledTokens":[],"explain":"Sielewi is the neutral “I don’t understand”; sikuelewi adds “you” — I don’t understand you. Both are useful, but sielewi is the safer default.","text":{"answers":["Sielewi.","Sikuelewi."],"misconceptions":{"Sijui":"Sijui means “I don’t know.” Use sielewi for “I don’t understand.”"}}},{"kind":"match","prompt":"Pair each course word with the job it does.","correctChain":["5 pairs"],"scrambledTokens":["Shikamoo → Greet an elder","Bei gani → Ask a price","Vitabu vizuri → Good books","Hakuna → Say there is none","Kuliko → Compare two things"],"explain":"The final pulls from greetings, market, noun classes, negation and comparison — one phrase from each family.","match":{"pairs":[{"left":"Shikamoo","right":"Greet an elder"},{"left":"Bei gani","right":"Ask a price"},{"left":"Vitabu vizuri","right":"Good books"},{"left":"Hakuna","right":"Say there is none"},{"left":"Kuliko","right":"Compare two things"}]}},{"kind":"listen","prompt":"Listen and type the plan for tomorrow.","correctChain":["Tunaenda sokoni kesho"],"scrambledTokens":[],"explain":"Tu-na-enda (we are going) + sokoni (to the market) + kesho (tomorrow) — Swahili needs no future ending when the time word already says when.","listen":{"phrase":"Tunaenda sokoni kesho","answers":["Tunaenda sokoni kesho"]}},{"kind":"speak","prompt":"Close an introduction, out loud.","correctChain":["Nimefurahi kukutana nawe"],"scrambledTokens":[],"explain":"Ni-me-fu-RA-hi ku-ku-TA-na NA-we: the -me- marks that the pleasure has already happened, and nawe is \"with you\".","speak":{"phrase":"Nimefurahi kukutana nawe","passScore":75}}],"position":13},
  {"id":"swahili-questions","course_id":"swahili","title":"Swahili Questions & Negation","theory":["Open a yes/no question with Je: Je, unakwenda sokoni? (Are you going to the market?). Question words take the answer’s place: Unakwenda wapi? (Where are you going?), Unaitwa nani? (What are you called?), Kwa nini unacheka? (Why are you laughing?).","The present negative drops -na- and swaps the subject prefix: ninapenda → sipendi (I don’t like), unasoma → husomi (you don’t read), anafanya kazi → hafanyi kazi (he doesn’t work). Plural follows the same pattern: hatupendi, hampendi, hawapendi.","For possession and existence: sina (I don’t have), hatuna (we don’t have), hakuna (there is no). Keep the noun after the verb — Hakuna maji means there is no water."],"questions":[{"prompt":"Which word opens a yes/no question in Swahili?","correctChain":["Je"],"scrambledTokens":["Je","Na","Ni","Kwa"],"explain":"Je, unakwenda sokoni? — Je turns the statement into a question."},{"prompt":"Ask “Where are you going?”","correctChain":["Unakwenda","wapi"],"scrambledTokens":["wapi","Unakwenda","nani","lini"],"explain":"Unakwenda (you are going) + wapi (where). The question word closes the question."},{"prompt":"“Sipendi chai” means…","correctChain":["I don’t like tea"],"scrambledTokens":["I don’t like tea","I am drinking tea","I want tea","I don’t have tea"],"explain":"Si- is the I-negative prefix; -penda = like. Sipendi chai = I don’t like tea."},{"prompt":"Say “We don’t have money”:","correctChain":["Hatuna","pesa"],"scrambledTokens":["pesa","Hatuna","Sina","chakula"],"explain":"Hatuna = we don’t have (hatu- + na). Sina is the singular I form."},{"prompt":"“Hakuna maji” means…","correctChain":["There is no water"],"scrambledTokens":["There is no water","The water is cold","I don’t want water","Bring the water"],"explain":"Hakuna = there is no. Maji = water."},{"kind":"match","prompt":"Pair each question tool with the answer it demands.","correctChain":["5 pairs"],"scrambledTokens":["Je → Nothing — it just turns the sentence into a yes/no question","Wapi → A place","Nani → A person","Lini → A time","Kwa nini → A reason"],"explain":"Je carries no meaning of its own; it only flags that a question has started. The other four replace the answer they want.","match":{"pairs":[{"left":"Je","right":"Nothing — it just turns the sentence into a yes/no question"},{"left":"Wapi","right":"A place"},{"left":"Nani","right":"A person"},{"left":"Lini","right":"A time"},{"left":"Kwa nini","right":"A reason"}]}},{"kind":"listen","prompt":"Listen and type the refusal about tea.","correctChain":["Sipendi chai"],"scrambledTokens":[],"explain":"The negative drops -na- and takes si-: ninapenda becomes sipendi. Sipendi chai = I do not like tea.","listen":{"phrase":"Sipendi chai","answers":["Sipendi chai"],"misconceptions":{"Sipenda chai":"Negatives end in -i, not -a: si-pendi, never si-penda."}}},{"kind":"speak","prompt":"Ask someone what they are called, out loud.","correctChain":["Jina lako ni nani"],"scrambledTokens":[],"explain":"JI-na LA-ko ni NA-ni: lako is \"your\" for the ji- class, and nani at the end does the asking for you.","speak":{"phrase":"Jina lako ni nani","passScore":75}}],"position":14},
  {"id":"swahili-adjectives","course_id":"swahili","title":"Swahili Adjectives & Agreement","theory":["Adjectives follow the noun and agree with its class: mtoto mzuri (a good child), watoto wazuri (good children); kitabu kizuri (a good book), vitabu vizuri (good books).","Class 9/10 nouns often take n-: nyumba nzuri (a good house), nyumba ndogo (a small house). Learn each noun with its adjective pair, not the adjective alone.","Compare with kuliko: Yeye ni mrefu kuliko mimi (He is taller than me). Common opposites: -kubwa/-dogo (big/small), -refu/-fupi (tall/short), -pya/-zee (new/old), -zuri/-baya (good/bad)."],"questions":[{"prompt":"Choose the correct pair for “a good child”:","correctChain":["mtoto mzuri"],"scrambledTokens":["mtoto mzuri","mtoto wazuri","watoto mzuri","mtoto vizuri"],"explain":"Mtoto is class 1; its adjective takes m-: mtoto mzuri. Watoto wazuri is the plural."},{"prompt":"Say “big books”:","correctChain":["Vitabu","vikubwa"],"scrambledTokens":["vikubwa","Vitabu","kubwa","vidogo"],"explain":"Vitabu is class 8 plural, so the adjective takes vi-: vitabu vikubwa."},{"prompt":"“Nyumba ndogo” means…","correctChain":["A small house"],"scrambledTokens":["A small house","A big house","A new house","Many houses"],"explain":"Nyumba is class 9/10; the adjective takes n-: ndogo = small."},{"prompt":"Say “The tree is tall”:","correctChain":["Mti","ni","mrefu"],"scrambledTokens":["mrefu","Mti","ni","fupi"],"explain":"Mti (tree) is class 3, so tall is mrefu. Ni links subject and adjective."},{"prompt":"“Kuliko” is used to…","correctChain":["Compare two things"],"scrambledTokens":["Compare two things","Mean “very”","Mark a question","Mean “and”"],"explain":"Yeye ni mrefu kuliko mimi — he is taller than me. Kuliko = than."},{"kind":"match","prompt":"Pair each adjective stem with what it says.","correctChain":["5 pairs"],"scrambledTokens":["Kubwa → Big","Dogo → Small","Refu → Tall / long","Fupi → Short","Zuri → Good / beautiful"],"explain":"These are bare stems. In a sentence the noun class glues on the front: mkubwa, mdogo, mrefu, nzuri, kikubwa, vikubwa.","match":{"pairs":[{"left":"Kubwa","right":"Big"},{"left":"Dogo","right":"Small"},{"left":"Refu","right":"Tall / long"},{"left":"Fupi","right":"Short"},{"left":"Zuri","right":"Good / beautiful"}]}},{"kind":"listen","prompt":"Listen and type the phrase about the house.","correctChain":["Nyumba nzuri"],"scrambledTokens":[],"explain":"Nyumba is class 9, so the adjective borrows its n-: nzuri. A book would be kitabu kizuri — same stem, different prefix.","listen":{"phrase":"Nyumba nzuri","answers":["Nyumba nzuri"]}},{"kind":"speak","prompt":"Say the tree is tall, out loud.","correctChain":["Mti ni mrefu"],"scrambledTokens":[],"explain":"Mti is one long beat and mrefu is MREH-foo: the m- on mrefu agrees with mti, so say the two words as a matched pair.","speak":{"phrase":"Mti ni mrefu","passScore":75}}],"position":15},
  {"id":"swahili-health","course_id":"swahili","title":"Swahili Health & Emergencies","theory":["Naumwa means I am ill — literally “it hurts me”. Name the place with na: Naumwa na kichwa (headache), Naumwa na tumbo (stomach ache).","Nina homa (I have a fever), nina kikohozi (I have a cough). Ask for help plainly: Nisaidie! (Help me!), Nahitaji daktari (I need a doctor), Hospitali iko wapi? (Where is the hospital?).","At the pharmacy ask for dawa (medicine); in an emergency say Piga simu ya dharura (call the emergency number)."],"questions":[{"prompt":"“Naumwa na tumbo” means…","correctChain":["My stomach hurts"],"scrambledTokens":["My stomach hurts","I am hungry","I ate too much","My head hurts"],"explain":"Naumwa = it hurts me; na tumbo = in the stomach. Naumwa na kichwa is the headache."},{"prompt":"Say “I need a doctor”:","correctChain":["Nahitaji","daktari"],"scrambledTokens":["daktari","Nahitaji","dawa","hospitali"],"explain":"Nahitaji = I need; daktari = doctor. Dawa is medicine, hospitali the building."},{"prompt":"“Nisaidie!” means…","correctChain":["Help me!"],"scrambledTokens":["Help me!","I am fine","Excuse me","Goodbye"],"explain":"Nisaidie is the direct plea for help — say it loudly and clearly."},{"prompt":"Ask “Where is the hospital?”","correctChain":["Hospitali","iko","wapi"],"scrambledTokens":["wapi","Hospitali","iko","daktari"],"explain":"Hospitali iko wapi? — iko = it is (located), wapi = where."},{"prompt":"At the pharmacy you ask for…","correctChain":["dawa"],"scrambledTokens":["dawa","chakula","maji","kitabu"],"explain":"Dawa = medicine. Chakula is food, maji is water, kitabu is a book."},{"kind":"match","prompt":"Pair each symptom with what the clinic hears.","correctChain":["5 pairs"],"scrambledTokens":["Naumwa na kichwa → My head hurts","Naumwa na tumbo → My stomach hurts","Nina homa → I have a fever","Nina kikohozi → I have a cough","Nahitaji daktari → I need a doctor"],"explain":"Naumwa means \"it hurts me\", and na then names the place — the pain is the subject, not you.","match":{"pairs":[{"left":"Naumwa na kichwa","right":"My head hurts"},{"left":"Naumwa na tumbo","right":"My stomach hurts"},{"left":"Nina homa","right":"I have a fever"},{"left":"Nina kikohozi","right":"I have a cough"},{"left":"Nahitaji daktari","right":"I need a doctor"}]}},{"kind":"listen","prompt":"Listen and type the question asked at the junction.","correctChain":["Hospitali iko wapi"],"scrambledTokens":[],"explain":"Iko is the locative for an i-/ki- class noun, and wapi closes the question. Hapa or pale answers it.","listen":{"phrase":"Hospitali iko wapi","answers":["Hospitali iko wapi"]}},{"kind":"speak","prompt":"Call for an emergency phone, out loud.","correctChain":["Piga simu ya dharura"],"scrambledTokens":[],"explain":"PEE-ga SEE-mu ya da-HU-ra: piga simu literally means \"hit a phone\", which is how Swahili says to call.","speak":{"phrase":"Piga simu ya dharura","passScore":75}}],"position":16},
  {"id":"swahili-politeness","course_id":"swahili","title":"Swahili Politeness & Sympathy","theory":["Swahili softens every request. Samahani (sorry / excuse me) opens one, Tafadhali (please) smooths it, and Asante (thank you) closes it. Karibu means welcome — the natural reply to Asante — and also “come in”.","Kumradhi is the formal “pardon me” heard in announcements and on phrase cards. Pole sana is sympathy, not an apology for a mistake: use it when someone is hurt or has bad news, and Samahani when you are the one who bumped, interrupted or arrived late. Hamna shida (or Hakuna shida) = no problem; Ni sawa = it’s fine."],"questions":[{"prompt":"You bump into someone in a crowd. What do you say?","correctChain":["Samahani"],"scrambledTokens":["Samahani","Asante","Karibu","Kwaheri"],"explain":"Samahani = sorry / excuse me. Asante thanks them, Karibu welcomes them, Kwaheri says goodbye."},{"prompt":"Say “Please help me”:","correctChain":["Nisaidie","tafadhali"],"scrambledTokens":["tafadhali","Nisaidie","asante","pole"],"explain":"Nisaidie = help me; tafadhali = please. Either order works — Tafadhali nisaidie is just as natural."},{"prompt":"“Asante sana” means…","correctChain":["Thank you very much"],"scrambledTokens":["Thank you very much","You are welcome","I am sorry","See you later"],"explain":"Asante = thank you; sana = very. Asante sana is the warm, everyday thank-you."},{"prompt":"Reply “You’re welcome” to Asante:","correctChain":["Karibu"],"scrambledTokens":["Karibu","Tafadhali","Pole","Kwaheri"],"explain":"Karibu is the standard reply to thanks. It also means welcome / come in."},{"prompt":"A friend tells you their grandmother died. Which reply fits?","correctChain":["Pole sana"],"scrambledTokens":["Pole sana","Tafadhali","Karibu","Asante sana"],"explain":"Pole sana expresses sympathy. Samahani would suggest you were at fault."},{"kind":"match","prompt":"Pair each polite word with the moment it belongs to.","correctChain":["5 pairs"],"scrambledTokens":["Samahani → You bumped into someone","Tafadhali → You are asking for something","Asante → You received what you asked for","Karibu → Someone just thanked you","Pole sana → Someone has bad news"],"explain":"Karibu answers Asante, never Samahani — and Pole sana is sympathy, not an apology for your own mistake.","match":{"pairs":[{"left":"Samahani","right":"You bumped into someone"},{"left":"Tafadhali","right":"You are asking for something"},{"left":"Asante","right":"You received what you asked for"},{"left":"Karibu","right":"Someone just thanked you"},{"left":"Pole sana","right":"Someone has bad news"}]}},{"kind":"listen","prompt":"Listen and type the warm thank-you.","correctChain":["Asante sana"],"scrambledTokens":[],"explain":"Sana doubles the thanks the way very doubles thank-you; the reply you will hear back is karibu.","listen":{"phrase":"Asante sana","answers":["Asante sana"]}},{"kind":"speak","prompt":"Wave off someone’s apology, out loud.","correctChain":["Hamna shida"],"scrambledTokens":[],"explain":"HAM-na SHEE-da: hamna is the class 1 negative of \"there is\", so the phrase literally says there is no trouble.","speak":{"phrase":"Hamna shida","passScore":75}}],"position":17},
  {"id":"swahili-introductions","course_id":"swahili","title":"Swahili Introductions & Origins","theory":["Ask a name formally with Jina lako ni nani? and casually with Unaitwaje? Answer Jina langu ni … or Ninaitwa …; Mimi ni … works in both registers.","Origin uses -toka: Umetoka wapi? (formal) / Unatoka wapi? Answer Nimetoka Kenya. Residence uses -ishi or -kaa: Unaishi wapi? / Unakaa wapi? — Naishi Nairobi. Close an introduction with Nimefurahi kukutana nawe (nice to meet you)."],"questions":[{"prompt":"Which question is the casual way to ask someone’s name?","correctChain":["Unaitwaje?"],"scrambledTokens":["Unaitwaje?","Jina lako ni nani?","Umetoka wapi?","Unaishi wapi?"],"explain":"Unaitwaje? = what are you called? Jina lako ni nani? is the formal version."},{"prompt":"Say “My name is Amina”:","correctChain":["Jina","langu","ni","Amina"],"scrambledTokens":["Amina","Jina","langu","ni","yako"],"explain":"Jina = name, langu = my, ni = is. Jina langu ni Amina. Ninaitwa Amina says the same thing."},{"prompt":"“Umetoka wapi?” asks…","correctChain":["Where are you from?"],"scrambledTokens":["Where are you from?","Where do you live?","What is your name?","How old are you?"],"explain":"-toka = come from. Answer Nimetoka Kenya (I am from Kenya). Residence uses -ishi instead."},{"prompt":"Say “I am from Kenya”:","correctChain":["Nimetoka","Kenya"],"scrambledTokens":["Nimetoka","Kenya","Naishi","Ujerumani"],"explain":"Nimetoka = I have come from / I am from. Naishi is “I live”, not “I am from”."},{"prompt":"You live in Nairobi. Best answer to “Unaishi wapi?”","correctChain":["Naishi Nairobi"],"scrambledTokens":["Naishi Nairobi","Nimetoka Nairobi","Ninaitwa Nairobi","Nimefurahi Nairobi"],"explain":"Naishi = I live. Nimetoka Nairobi would mean you come from Nairobi; the question asks where you live."},{"kind":"match","prompt":"Pair each introduction with the register it fits.","correctChain":["5 pairs"],"scrambledTokens":["Jina lako ni nani → Asking a name formally","Unaitwaje → Asking a name casually","Umetoka wapi → Where are you from (finished)","Unaishi wapi → Where do you live","Ninaitwa Amina → My name is Amina"],"explain":"-toka is come from, -ishi is live: the two questions look alike and demand different answers.","match":{"pairs":[{"left":"Jina lako ni nani","right":"Asking a name formally"},{"left":"Unaitwaje","right":"Asking a name casually"},{"left":"Umetoka wapi","right":"Where are you from (finished)"},{"left":"Unaishi wapi","right":"Where do you live"},{"left":"Ninaitwa Amina","right":"My name is Amina"}]}},{"kind":"listen","prompt":"Listen and type the introduction.","correctChain":["Jina langu ni Amina"],"scrambledTokens":[],"explain":"Langu is \"my\" for the ji- class, so jina langu (my name) — lako would be your.","listen":{"phrase":"Jina langu ni Amina","answers":["Jina langu ni Amina"]}},{"kind":"speak","prompt":"Introduce yourself, out loud.","correctChain":["Ninaitwa Amina"],"scrambledTokens":[],"explain":"Say the vowels apart — nee-na-ee-twa — and hear the root -itwa (be called) inside it. Ninaitwa Amina is I-am-called Amina.","speak":{"phrase":"Ninaitwa Amina","passScore":75}}],"position":18},
  {"id":"swahili-language","course_id":"swahili","title":"Swahili Languages & Understanding","theory":["Language names wear Ki-: Kiswahili, Kiingereza (English), Kiarabu (Arabic), Kijerumani (German), Kijapani (Japanese). Ask Unazungumza Kiingereza? — in the street you will also hear Unaongea Kiingereza?","When you are lost: Sielewi (I don’t understand), Sema polepole tafadhali (speak slowly, please), Unaweza kurudia? (can you repeat?). Naelewa = I understand; Kidogo tu = just a little."],"questions":[{"prompt":"“Sielewi” means…","correctChain":["I don’t understand"],"scrambledTokens":["I don’t understand","I don’t speak","I don’t know","I don’t want it"],"explain":"Sielewi is the negative of naelewa (I understand) — the phrase for “it has not landed”."},{"prompt":"Ask “Do you speak English?” in standard Swahili:","correctChain":["Unazungumza","Kiingereza"],"scrambledTokens":["Kiingereza","Unazungumza","Unaongea","Kiarabu"],"explain":"Unazungumza = you speak; Kiingereza = English. Unaongea Kiingereza? is the common colloquial variant."},{"prompt":"You need the speaker to slow down. Which sentence do you use?","correctChain":["Sema polepole tafadhali."],"scrambledTokens":["Sema polepole tafadhali.","Sema haraka tafadhali.","Unaweza kurudia?","Naelewa."],"explain":"Polepole = slowly; sema = speak. Unaweza kurudia? asks for a repeat, not a slower pace."},{"prompt":"Say “I speak a little Swahili”:","correctChain":["Nazungumza","Kiswahili","kidogo"],"scrambledTokens":["kidogo","Nazungumza","Kiswahili","Kiingereza"],"explain":"Nazungumza = I speak; kidogo = a little. Kidogo tu adds “just a little”."},{"prompt":"“Unaweza kurudia?” asks…","correctChain":["Can you repeat?"],"scrambledTokens":["Can you repeat?","Can you help me?","Can you write it?","Can you speak English?"],"explain":"Kurudia = to repeat. Add tafadhali to keep it polite."},{"kind":"match","prompt":"Pair each language name with the tongue it means.","correctChain":["5 pairs"],"scrambledTokens":["Kiswahili → Swahili","Kiingereza → English","Kiarabu → Arabic","Kijerumani → German","Kijapani → Japanese"],"explain":"Every language name is the Ki- class prefix bolted to the country: Kijerumani is German because Ujerumani is Germany.","match":{"pairs":[{"left":"Kiswahili","right":"Swahili"},{"left":"Kiingereza","right":"English"},{"left":"Kiarabu","right":"Arabic"},{"left":"Kijerumani","right":"German"},{"left":"Kijapani","right":"Japanese"}]}},{"kind":"listen","prompt":"Listen and type the request that saves a conversation.","correctChain":["Sema polepole tafadhali"],"scrambledTokens":[],"explain":"Sema = speak (imperative), polepole = slowly, tafadhali = please. Swahili reduplicates to soften: polepole is gentler than pole.","listen":{"phrase":"Sema polepole tafadhali","answers":["Sema polepole tafadhali"]}},{"kind":"speak","prompt":"Admit you only understand a little, out loud.","correctChain":["Naelewa kidogo"],"scrambledTokens":[],"explain":"na-e-LEH-wa ki-DO-go: -elewa is understand and kidogo is the ki- class form of small — a small amount.","speak":{"phrase":"Naelewa kidogo","passScore":75}}],"position":19},
  {"id":"swahili-money","course_id":"swahili","title":"Swahili Money & Bargaining","theory":["Ask the price with Bei gani? or Bei yake ni ngapi? (How much is it?). Ghali = expensive, rahisi = cheap; Punguza bei = lower the price. Numbers: moja … kumi, elfu = thousand, mia = hundred.","Money talk: standard Swahili is Una pesa? (do you have money?); in the market you will hear the colloquial Uko na pesa? Sina pesa = I have no money. Zimetosha = that’s enough (for things), and Bas! stops a negotiation."],"questions":[{"prompt":"“Bei yake ni ngapi?” asks…","correctChain":["How much does it cost?"],"scrambledTokens":["How much does it cost?","Where is it?","What is it?","Do you have it?"],"explain":"Bei = price, ngapi = how many / how much. Bei gani? asks the same thing."},{"prompt":"Say “It is very expensive”:","correctChain":["Ni","ghali","sana"],"scrambledTokens":["ghali","Ni","sana","rahisi"],"explain":"Ni = it is, ghali = expensive, sana = very. Rahisi is the opposite: cheap."},{"prompt":"You say “Punguza bei.” The seller understands…","correctChain":["Lower the price"],"scrambledTokens":["Lower the price","I will take it","It is cheap","No change"],"explain":"Punguza = reduce; bei = price. The friendly follow-up is “Punguza kidogo” — reduce it a little."},{"prompt":"Say “I don’t have money”:","correctChain":["Sina","pesa"],"scrambledTokens":["pesa","Sina","Nina","bei"],"explain":"Sina = I don’t have; pesa = money. Uko na pesa? is the colloquial way a seller asks if you have any."},{"prompt":"“Shilingi elfu tano” is…","correctChain":["5,000 shillings"],"scrambledTokens":["5,000 shillings","500 shillings","50 shillings","5 shillings"],"explain":"Elfu = thousand, tano = five. Shilingi elfu tano = 5,000 shillings."},{"kind":"match","prompt":"Pair each bargaining phrase with what the seller hears.","correctChain":["5 pairs"],"scrambledTokens":["Bei gani → You want the price","Punguza bei → You want it cheaper","Ghali → You think it is expensive","Rahisi → You think it is cheap","Sina pesa → You have no money with you"],"explain":"Punguza is an imperative — reduce. The reply to a smile and a punguza bei is usually a number only slightly lower.","match":{"pairs":[{"left":"Bei gani","right":"You want the price"},{"left":"Punguza bei","right":"You want it cheaper"},{"left":"Ghali","right":"You think it is expensive"},{"left":"Rahisi","right":"You think it is cheap"},{"left":"Sina pesa","right":"You have no money with you"}]}},{"kind":"listen","prompt":"Listen and type the price question.","correctChain":["Bei yake ni ngapi"],"scrambledTokens":[],"explain":"Yake = its (class 9/10 agreement), ni = is, ngapi = how many. Bei gani? asks the same thing in two words instead of four.","listen":{"phrase":"Bei yake ni ngapi","answers":["Bei yake ni ngapi"]}},{"kind":"speak","prompt":"Tell the seller it costs too much, out loud.","correctChain":["Ni ghali sana"],"scrambledTokens":[],"explain":"nee GHAH-lee SAH-nah: ghali carries a hard g, never the English j sound, and sana does the very for you.","speak":{"phrase":"Ni ghali sana","passScore":75}}],"position":20},
  {"id":"chess-basics","course_id":"chess","title":"Chess Basics","theory":["Chess is played on an 8×8 board with 16 pieces each. Every piece moves differently — knights jump in an L, bishops glide diagonally, rooks run straight, the queen does both.","The goal is checkmate: attack the enemy king so it cannot escape. Moves are written in notation — Nf3 means knight to f3, O-O means kingside castle."],"questions":[{"prompt":"How does a knight move?","correctChain":["In an L-shape: two squares one way, one sideways"],"scrambledTokens":["In an L-shape: two squares one way, one sideways","Diagonally any distance","Straight any distance","One square in any direction"],"explain":"Knights jump over pieces — the trickiest mover on the board."},{"prompt":"Which piece moves diagonally any number of squares?","correctChain":["Bishop"],"scrambledTokens":["Bishop","Rook","Knight","Pawn"],"explain":"Bishop = diagonals; rook = straights; queen = both."},{"prompt":"Knight on g1 jumps to f3. Write the move:","correctChain":["N","f3"],"scrambledTokens":["N","f3","g1","B"],"explain":"N = knight (K is the king). Then the destination square: f3."},{"prompt":"What does O-O mean in notation?","correctChain":["Kingside castle"],"scrambledTokens":["Kingside castle","Checkmate","Draw offer","Pawn promotion"],"explain":"O-O castles kingside; O-O-O castles queenside."},{"prompt":"Checkmate means…","correctChain":["The king is attacked and cannot escape — game over"],"scrambledTokens":["The king is attacked and cannot escape — game over","The king is attacked but can move","Both sides agree a draw","A pawn reaches the far rank"],"explain":"Check = attacked. Checkmate = no escape. Stalemate = draw."},{"prompt":"White pawn on e2 pushes two squares. Write it:","correctChain":["e4"],"scrambledTokens":["e4","e3","Nf3","e5"],"explain":"Pawns move straight; from rank 2 they may jump two squares."},{"kind":"match","prompt":"Pair each piece or symbol with what it does.","correctChain":["5 pairs"],"scrambledTokens":["Knight → Jumps in an L-shape","Bishop → Glides along diagonals","Rook → Runs along straight lines","O-O → Kingside castle","O-O-O → Queenside castle"],"explain":"Bishops never change colour, rooks never turn, and the two castles differ by how many O’s you write.","match":{"pairs":[{"left":"Knight","right":"Jumps in an L-shape"},{"left":"Bishop","right":"Glides along diagonals"},{"left":"Rook","right":"Runs along straight lines"},{"left":"O-O","right":"Kingside castle"},{"left":"O-O-O","right":"Queenside castle"}]}}],"position":1},
  {"id":"chess-tactics","course_id":"chess","title":"Chess Tactics","theory":["Tactics win games: a fork attacks two pieces at once, a pin freezes a piece that cannot move without exposing its king, and a discovered attack unveils a hidden attacker.","Strategy matters too: when ahead in material, trade pieces to simplify into an easy win; doubled rooks on the 7th rank feast on pawns and trap kings."],"questions":[{"prompt":"A knight attacks the king and rook at the same time. This tactic is a…","correctChain":["Fork"],"scrambledTokens":["Fork","Pin","Skewer","Discovered attack"],"explain":"One piece, two targets — the fork. Knights are fork machines."},{"prompt":"A bishop makes an enemy knight unable to move without exposing its king. This is a…","correctChain":["Pin"],"scrambledTokens":["Pin","Fork","Skewer","Castle"],"explain":"Pinned pieces are prisoners — attack what they defend."},{"prompt":"Moving a piece to unveil an attack from the piece behind it is a…","correctChain":["Discovered attack"],"scrambledTokens":["Discovered attack","Fork","Pin","Promotion"],"explain":"Two threats in one move — one of the strongest ideas in chess."},{"prompt":"When you are up a queen, trading queens is usually…","correctChain":["Good — it simplifies to an easy win"],"scrambledTokens":["Good — it simplifies to an easy win","Bad — keep the tension","Illegal","An automatic draw"],"explain":"Simplify when ahead: fewer pieces, fewer chances to blunder."},{"prompt":"Two rooks doubled on the 7th rank typically…","correctChain":["Win pawns and trap the enemy king"],"scrambledTokens":["Win pawns and trap the enemy king","Lose their power","Force a draw","Must be traded off"],"explain":"Pigs on the 7th: the most feared sight in an endgame."},{"kind":"match","prompt":"Pair each tactic with the shape it makes on the board.","correctChain":["4 pairs"],"scrambledTokens":["Fork → One piece attacks two targets","Pin → A piece is frozen to protect something better","Discovered attack → Moving aside unveils the attacker behind","Doubled rooks → Two rooks stacked on one file"],"explain":"A fork attacks twice, a pin paralyses, a discovery attacks from nowhere, and doubled rooks just eat.","match":{"pairs":[{"left":"Fork","right":"One piece attacks two targets"},{"left":"Pin","right":"A piece is frozen to protect something better"},{"left":"Discovered attack","right":"Moving aside unveils the attacker behind"},{"left":"Doubled rooks","right":"Two rooks stacked on one file"}]}}],"position":2},
  {"id":"chess-quiz","course_id":"chess","title":"Chess Checkpoint","theory":["Checkpoint: piece movement, notation, tactics, and mating from the full chess course."],"questions":[{"prompt":"How does a knight move?","correctChain":["In an L-shape: two squares one way, one sideways"],"scrambledTokens":["In an L-shape: two squares one way, one sideways","Diagonally any distance","Straight any distance","One square in any direction"],"explain":"Knights jump over pieces — the trickiest mover."},{"prompt":"White pawn on e2 pushes two squares. Write it:","correctChain":["e4"],"scrambledTokens":["e4","e3","Nf3","e5"],"explain":"Pawns move straight; from rank 2 they may jump two."},{"prompt":"A pawn attacks two pieces at once. This tactic is a…","correctChain":["Fork"],"scrambledTokens":["Fork","Pin","Skewer","Castle"],"explain":"Forks work with any piece — even lowly pawns."},{"prompt":"What does O-O mean in notation?","correctChain":["Kingside castle"],"scrambledTokens":["Kingside castle","Checkmate","Draw offer","Pawn promotion"],"explain":"O-O castles kingside; O-O-O castles queenside."},{"prompt":"Checkmate means…","correctChain":["The king is attacked and cannot escape — game over"],"scrambledTokens":["The king is attacked and cannot escape — game over","The king is attacked but can move","Both sides agree a draw","A pawn reaches the far rank"],"explain":"Check = attacked. Checkmate = no escape. Stalemate = draw."},{"kind":"text","prompt":"White has an unmoved king on e1 and rook on h1; f1 and g1 are empty and neither square is attacked. Type the notation for the legal kingside castle.","correctChain":["O-O"],"scrambledTokens":[],"explain":"O-O is kingside castling when the king and h1 rook are unmoved and the path is safe. O-O-O is queenside, which this position does not allow.","text":{"answers":["O-O","0-0"],"misconceptions":{"O-O-O":"That is queenside castling — it needs the a1 rook and the b1/c1/d1 squares clear."}}},{"kind":"match","prompt":"Pair each notation or term with what it means.","correctChain":["4 pairs"],"scrambledTokens":["Nf3 → Knight moves to f3","O-O → Kingside castle","Checkmate → The king is attacked and cannot escape","Stalemate → No legal move, but the king is not attacked"],"explain":"Checkmate and stalemate look alike from far away: the difference is whether the king is in check.","match":{"pairs":[{"left":"Nf3","right":"Knight moves to f3"},{"left":"O-O","right":"Kingside castle"},{"left":"Checkmate","right":"The king is attacked and cannot escape"},{"left":"Stalemate","right":"No legal move, but the king is not attacked"}]}}],"position":3},
  {"id":"chess-openings","course_id":"chess","title":"Chess Openings","theory":["Openings follow three laws: control the center (e4, d4, Nf3), develop knights and bishops fast, and castle early for king safety. Never move the same piece twice while others sleep.","Answer 1. e4 with 1…e5 or 1…c5; answer 1. d4 with 1…d5 or 1…Nf6. Traps punish greed — develop first, grab pawns later."],"questions":[{"prompt":"The opening’s first job is…","correctChain":["Control the center"],"scrambledTokens":["Control the center","Trade queens","Push flank pawns","Move the king up"],"explain":"Center pawns and knights first: e4, d4, Nf3, Nc3."},{"prompt":"Castle kingside in notation:","correctChain":["O-O"],"scrambledTokens":["O-O-O","O-O","0-0","Ke1"],"explain":"O-O (letter O) castles kingside; O-O-O queenside."},{"prompt":"After 1. e4, a sound Black reply is…","correctChain":["1…e5 or 1…c5"],"scrambledTokens":["1…e5 or 1…c5","1…h5","1…Na6","1…f6"],"explain":"Meet center with center or counterplay — not wing pawns."},{"prompt":"Castling early gives you…","correctChain":["A safe king + connected rooks"],"scrambledTokens":["A safe king + connected rooks","An extra queen","Two moves in a row","A draw"],"explain":"Castle by move 10 in most openings. Safety first."},{"prompt":"A knight develops toward the center. From g1 it goes to:","correctChain":["Nf3"],"scrambledTokens":["Nh3","Nf3","Ne2","Ng1"],"explain":"Nf3 attacks the center and frees castling. Nh3 sulks."},{"kind":"match","prompt":"Pair each opening law with what it is really about.","correctChain":["5 pairs"],"scrambledTokens":["e4, d4, Nf3 → Occupying or attacking the center","Develop knights and bishops → Get the sleeping pieces into the game","Castle before move ten → King safety","Never move one piece twice → Tempo — every move should do new work","1…c5 → Answering 1. e4 with counterplay instead of copying"],"explain":"The opening is a race to activate, not a grab for material. Greedy pawn snatching breaks the third law and gets punished.","match":{"pairs":[{"left":"e4, d4, Nf3","right":"Occupying or attacking the center"},{"left":"Develop knights and bishops","right":"Get the sleeping pieces into the game"},{"left":"Castle before move ten","right":"King safety"},{"left":"Never move one piece twice","right":"Tempo — every move should do new work"},{"left":"1…c5","right":"Answering 1. e4 with counterplay instead of copying"}]}}],"position":4},
  {"id":"chess-mate-patterns","course_id":"chess","title":"Checkmate Patterns","theory":["Mates repeat like songs. Back-rank mate: a rook or queen lands on the 8th rank while the king’s own pawns cage it. Scholar’s mate (Qh5/Qxf7) punishes beginners who ignore f7.","Smothered mate: a knight checks a king buried in its own pieces. Ladder mate: two rooks walk the king down the board, rank by rank."],"questions":[{"prompt":"Back-rank mate works because…","correctChain":["The king’s own pawns block its escape"],"scrambledTokens":["The king’s own pawns block its escape","The queen is pinned","Castling is illegal","The knight jumps far"],"explain":"A rook on the 8th rank + pawn wall = mate. Give luft with h3!"},{"prompt":"Scholar’s mate finishes on which square?","correctChain":["Qxf7"],"scrambledTokens":["Qxf7","Qxh5","Qxd5","Qe2"],"explain":"Qh5 then Qxf7#: f7 is weakest near the king. Defend it early!"},{"prompt":"Smothered mate is delivered by…","correctChain":["A knight"],"scrambledTokens":["A knight","A bishop","A pawn","The king"],"explain":"A knight checks a king smothered by its own pieces. Beautiful."},{"prompt":"Ladder mate uses which two pieces?","correctChain":["Rook","rook"],"scrambledTokens":["rook","Rook","queen","bishop"],"explain":"Two rooks alternate checks, pushing the king down. Rook + rook."},{"prompt":"To stop back-rank mates, you…","correctChain":["Push a luft pawn (h3/g3)"],"scrambledTokens":["Push a luft pawn (h3/g3)","Avoid castling","Trade rooks","Keep the queen home"],"explain":"Luft = breathing room. One pawn step saves the king."},{"kind":"match","prompt":"Pair each mating pattern with the weakness it exploits.","correctChain":["5 pairs"],"scrambledTokens":["Back-rank mate → A king walled in by its own pawns","Scholar’s mate → The f7 square, guarded only by the king","Smothered mate → A king buried under its own pieces","Ladder mate → A lone king with no defender nearby","Luft → The escape square a pawn push creates"],"explain":"Four patterns, one lesson: your own pieces are the walls that get your king mated. Knight delivers the smothered finish; two rooks climb the ladder.","match":{"pairs":[{"left":"Back-rank mate","right":"A king walled in by its own pawns"},{"left":"Scholar’s mate","right":"The f7 square, guarded only by the king"},{"left":"Smothered mate","right":"A king buried under its own pieces"},{"left":"Ladder mate","right":"A lone king with no defender nearby"},{"left":"Luft","right":"The escape square a pawn push creates"}]}}],"position":5},
  {"id":"chess-endgames","course_id":"chess","title":"Essential Endgames","theory":["Few pieces, pure technique. King + queen vs king: push to the edge, keep the queen a knight’s jump away, mate on the rim. King + rook vs king: box the king with the rook, march yours up, mate.","Opposition: kings face off with one square between — whoever does NOT move holds the key. A passed pawn plus a supporting king wins; alone, it falls."],"questions":[{"prompt":"Queen vs lone king: mate happens…","correctChain":["On the edge of the board"],"scrambledTokens":["On the edge of the board","In the center","On move one","By stalemate"],"explain":"Push to the rim, queen a knight-move away, king close. Mate."},{"prompt":"The winning endgame technique is called:","correctChain":["Opposition"],"scrambledTokens":["Opposition","Forking","Pinning","Fianchetto"],"explain":"Opposition: kings one square apart — the mover loses ground."},{"prompt":"Rook vs lone king wins by…","correctChain":["Boxing the king smaller, then mating"],"scrambledTokens":["Boxing the king smaller, then mating","Sacrificing the rook","Repeating checks fast","Promoting a pawn"],"explain":"Cut the box with rook checks, walk your king up, mate."},{"prompt":"A passed pawn usually needs…","correctChain":["Its king’s support to promote"],"scrambledTokens":["Its king’s support to promote","Nothing — it always queens","A knight beside it","To move twice"],"explain":"No blockers ahead, but the king must escort it home."},{"prompt":"Stalemate means the game is a:","correctChain":["Draw"],"scrambledTokens":["Win","Draw","Loss","Replay"],"explain":"No legal moves + not in check = draw. Mate needs CHECK."},{"kind":"match","prompt":"Pair each endgame word with what it means at the board.","correctChain":["5 pairs"],"scrambledTokens":["Opposition → Kings face to face, one square apart","Passed pawn → No enemy pawn stands in its way","Stalemate → No legal moves and not in check — a draw","The box → Shrinking the lone king’s space with rook checks","The rim → Where queen-versus-king mate is finished"],"explain":"Endgames are technique, not tactics: who moves last in the opposition loses ground, and a passed pawn needs its king as an escort.","match":{"pairs":[{"left":"Opposition","right":"Kings face to face, one square apart"},{"left":"Passed pawn","right":"No enemy pawn stands in its way"},{"left":"Stalemate","right":"No legal moves and not in check — a draw"},{"left":"The box","right":"Shrinking the lone king’s space with rook checks"},{"left":"The rim","right":"Where queen-versus-king mate is finished"}]}}],"position":6},
  {"id":"chess-tactics-2","course_id":"chess","title":"Advanced Tactics","theory":["Beyond forks and pins: discovered attacks (move one piece, unleash another), double checks (both pieces check — the king MUST move), and deflection (drag a defender away).","Decoys lure a piece to a bad square; clearance sacrifices open a line. Ask every move: what moved, what woke up, who is undefended?"],"questions":[{"prompt":"A discovered attack happens when…","correctChain":["Moving one piece unleashes another’s attack"],"scrambledTokens":["Moving one piece unleashes another’s attack","Two knights fork","A pawn promotes","The king castles"],"explain":"Move the mask, fire the battery. Two threats, one move."},{"prompt":"Against a double check, the king must:","correctChain":["Move"],"scrambledTokens":["Move","Block","Capture","Castle"],"explain":"Two checkers — no block, no capture both. King moves!"},{"prompt":"Deflection means…","correctChain":["Dragging a defender off its duty"],"scrambledTokens":["Dragging a defender off its duty","Blocking a check","Trading queens","Losing on purpose"],"explain":"Sacrifice to pull the guard away, then strike the target."},{"prompt":"“En passant” captures…","correctChain":["A pawn that just jumped two squares"],"scrambledTokens":["A pawn that just jumped two squares","Any pawn nearby","The king","A promoted piece"],"explain":"Side pawn takes as if it moved one. Use it or lose it — immediately!"},{"prompt":"A battery lines up queen + rook on the:","correctChain":["File"],"scrambledTokens":["Rank","File","Diagonal","Square"],"explain":"Battery on a file or rank: double the pressure, double the fun."},{"kind":"match","prompt":"Pair each tactic with the move it forces.","correctChain":["5 pairs"],"scrambledTokens":["Discovered attack → Step the mask aside, fire the piece behind it","Double check → The only legal answer is to move the king","Deflection → Pull a defender off the square it was guarding","Decoy → Lure a piece onto a square that ruins it","En passant → Capture immediately or lose the chance"],"explain":"Deflection removes a guard that already exists; decoy invites a piece somewhere new. Both are worth knowing apart.","match":{"pairs":[{"left":"Discovered attack","right":"Step the mask aside, fire the piece behind it"},{"left":"Double check","right":"The only legal answer is to move the king"},{"left":"Deflection","right":"Pull a defender off the square it was guarding"},{"left":"Decoy","right":"Lure a piece onto a square that ruins it"},{"left":"En passant","right":"Capture immediately or lose the chance"}]}}],"position":7},
  {"id":"chess-strategy","course_id":"chess","title":"Positional Strategy","theory":["Tactics win pieces; strategy wins positions. Place knights on outposts (supported, unattackable by pawns), bishops on long diagonals, rooks on open files and the 7th rank.","Pawn structure is destiny: doubled pawns are weak, isolated pawns need guarding, passed pawns must be pushed. Trade bad bishops, keep good ones."],"questions":[{"prompt":"A knight outpost is…","correctChain":["A supported square no enemy pawn can attack"],"scrambledTokens":["A supported square no enemy pawn can attack","Any corner square","The starting square","A square with two knights"],"explain":"Outpost knights (e.g. Nd5 supported) rule whole sectors."},{"prompt":"Rooks belong…","correctChain":["On open files and the 7th rank"],"scrambledTokens":["On open files and the 7th rank","Behind pawns","In corners","On diagonals"],"explain":"Open file + 7th rank = rook heaven, feasting on pawns."},{"prompt":"A pawn with no enemies ahead of it is:","correctChain":["Passed"],"scrambledTokens":["Isolated","Passed","Doubled","Backward"],"explain":"Passed pawns must be pushed! They demand the enemy’s attention."},{"prompt":"Doubled pawns are usually…","correctChain":["Weak — hard to defend, block each other"],"scrambledTokens":["Weak — hard to defend, block each other","Strong — double power","Equal — no difference","Winning — always"],"explain":"Stacked pawns guard nothing and clog files. Avoid them."},{"prompt":"“Good bishop” means…","correctChain":["Its pawns stand on the opposite color"],"scrambledTokens":["Its pawns stand on the opposite color","It never moves","It is near the king","It takes knights"],"explain":"Pawns on light squares → dark bishop is “good”. Free the bad one!"},{"kind":"match","prompt":"Pair each positional word with the plan it suggests.","correctChain":["5 pairs"],"scrambledTokens":["Outpost → Plant a knight where no enemy pawn can reach it","Open file → Put a rook where no pawns block it","The 7th rank → Feed the rook on enemy pawns","Isolated pawn → Guard it, or trade down around it","Doubled pawns → They cannot defend each other"],"explain":"Strategy is asking which piece is worse placed and fixing it. Doubled pawns clog a file; an isolated pawn has no neighbours to hold it.","match":{"pairs":[{"left":"Outpost","right":"Plant a knight where no enemy pawn can reach it"},{"left":"Open file","right":"Put a rook where no pawns block it"},{"left":"The 7th rank","right":"Feed the rook on enemy pawns"},{"left":"Isolated pawn","right":"Guard it, or trade down around it"},{"left":"Doubled pawns","right":"They cannot defend each other"}]}}],"position":8},
  {"id":"chess-final","course_id":"chess","title":"Chess Final Exam","theory":["Final exam: moves, notation, openings, mating patterns, endgames, tactics, and strategy — the whole comprehensive course."],"questions":[{"prompt":"How does a knight move?","correctChain":["In an L-shape: two squares one way, one sideways"],"scrambledTokens":["In an L-shape: two squares one way, one sideways","Diagonally any distance","Straight any distance","One square any way"],"explain":"The jumper — the only piece that leaps over others."},{"prompt":"Castle kingside in notation:","correctChain":["O-O"],"scrambledTokens":["O-O-O","O-O","0-0","Kg1"],"explain":"O-O kingside, O-O-O queenside. Safety in two characters."},{"prompt":"Back-rank mate needs…","correctChain":["A rook/queen on the 8th rank + a caged king"],"scrambledTokens":["A rook/queen on the 8th rank + a caged king","Two knights","No pawns moved","Opposite castling"],"explain":"Pawn wall + last-rank invader = mate. Push luft!"},{"prompt":"Stalemate means the game is a:","correctChain":["Draw"],"scrambledTokens":["Win","Draw","Loss","Replay"],"explain":"No moves + not in check = draw. Check first, celebrate after."},{"prompt":"“J’adoube” — touch-move means…","correctChain":["A touched piece must move if legal"],"scrambledTokens":["A touched piece must move if legal","You may take back moves","Clocks pause","Draws are offered"],"explain":"Touch-move: touch it, move it. Adjust only saying “j’adoube”."},{"prompt":"Queen vs king mates on the board’s:","correctChain":["Edge"],"scrambledTokens":["Center","Edge","Corner square only","Back rank"],"explain":"Push to the rim and finish. Technique beats hope."},{"prompt":"You have a passed pawn on the seventh rank and rooks on the board. What is the strongest plan?","correctChain":["Support promotion with your rook behind the pawn."],"scrambledTokens":["Support promotion with your rook behind the pawn.","Trade rooks immediately and race the king.","Move the pawn sideways to safety.","Offer a draw before promoting."],"explain":"A passed pawn on the seventh is a winning threat: put the rook behind it, escort it, and force the defender to give way."},{"kind":"text","prompt":"Type the notation for queenside castling.","correctChain":["O-O-O"],"scrambledTokens":[],"explain":"Queenside castling is O-O-O (three symbols); kingside is O-O. Use letter O, not zero, in standard notation.","text":{"answers":["O-O-O","0-0-0"],"misconceptions":{"O-O":"O-O is kingside castling. Queenside has three symbols: O-O-O."}}},{"kind":"match","prompt":"Pair each final-exam idea with the course unit it came from.","correctChain":["5 pairs"],"scrambledTokens":["Castle before move ten → Openings","Give the king luft → Mating patterns","Opposition → Endgames","Double check — king must move → Tactics","Rook behind a passed pawn → Strategy"],"explain":"One idea per unit: the exam asks whether you can place the knowledge, not only play it.","match":{"pairs":[{"left":"Castle before move ten","right":"Openings"},{"left":"Give the king luft","right":"Mating patterns"},{"left":"Opposition","right":"Endgames"},{"left":"Double check — king must move","right":"Tactics"},{"left":"Rook behind a passed pawn","right":"Strategy"}]}}],"position":9},
  {"id":"english-basics","course_id":"english","title":"English Basics","theory":["Start with the building blocks: 26 letters, numbers, and the two little words that confuse everyone — a and an. Use an before vowel sounds (an apple), a everywhere else (a ball).","Plurals usually add -s (books), but watch the rebels: box → boxes, child → children."],"questions":[{"prompt":"How many letters are in the English alphabet?","correctChain":["26"],"scrambledTokens":["26","24","28","30"],"explain":"26 letters: A to Z. Master their sounds and spelling follows."},{"prompt":"Say the first three letters:","correctChain":["A","B","C"],"scrambledTokens":["C","A","D","B"],"explain":"A, B, C — the start of every spelling bee."},{"prompt":"Fill the gap: \"___ apple\".","correctChain":["an"],"scrambledTokens":["an","a","the","no word needed"],"explain":"An before vowel SOUNDS: an apple, an hour. A ball, a cat."},{"prompt":"The plural of \"child\" is…","correctChain":["children"],"scrambledTokens":["children","childs","childes","child"],"explain":"Irregular rebel: one child, two children. Box → boxes is regular."},{"prompt":"Say \"I am a student\":","correctChain":["I","am","a","student"],"scrambledTokens":["student","I","am","a","teacher"],"explain":"I + am + a + who you are — your first English sentence."},{"kind":"match","prompt":"Pair each word or rule with the form it needs.","correctChain":["4 pairs"],"scrambledTokens":["an → Before a vowel sound","a → Before a consonant sound","children → The plural of child","boxes → The plural of box"],"explain":"An hour takes an because the h is silent; an apple takes an because a is a vowel sound. Sound, not spelling.","match":{"pairs":[{"left":"an","right":"Before a vowel sound"},{"left":"a","right":"Before a consonant sound"},{"left":"children","right":"The plural of child"},{"left":"boxes","right":"The plural of box"}]}},{"kind":"listen","prompt":"Listen and type the sentence about who you are.","correctChain":["I am a student"],"scrambledTokens":[],"explain":"Four short words, one be-form: am only ever follows I.","listen":{"phrase":"I am a student","answers":["I am a student"]}},{"kind":"speak","prompt":"Say your first English sentence out loud.","correctChain":["I am a student"],"scrambledTokens":[],"explain":"Link am into the rhythm — \"eye-am-uh-STOO-dent\" — and do not stress the a.","speak":{"phrase":"I am a student","passScore":75}}],"position":1},
  {"id":"english-everyday","course_id":"english","title":"Everyday English","theory":["Sound natural: introduce yourself (My name is…), ask back (Where are you from?), mind the moment (Excuse me to pass by, Sorry to apologise).","Time runs the day: What time is it? See you tomorrow. Small phrases, huge confidence."],"questions":[{"prompt":"Ask \"Where are you from?\":","correctChain":["Where","are","you","from"],"scrambledTokens":["from","Where","you","are","what"],"explain":"The friendliest question in English — memorise the order."},{"prompt":"\"What time is it?\" asks for…","correctChain":["The current time"],"scrambledTokens":["The current time","The day of the week","Your age","The date"],"explain":"Time = clock reading. Day = Monday. Date = 1st of June."},{"prompt":"You step on someone's foot. Say…","correctChain":["Sorry"],"scrambledTokens":["Sorry","Excuse me","Thank you","Welcome"],"explain":"Sorry = apologise. Excuse me = pass by or get attention."},{"prompt":"Say \"See you tomorrow\":","correctChain":["See","you","tomorrow"],"scrambledTokens":["tomorrow","See","later","you"],"explain":"See you + when: tomorrow, later, soon, on Monday."},{"prompt":"\"Nice to meet you\" is said…","correctChain":["When meeting someone for the first time"],"scrambledTokens":["When meeting someone for the first time","When leaving a party","When answering the phone","When saying thank you"],"explain":"First meeting only — then switch to \"Good to see you\"."},{"kind":"match","prompt":"Pair each phrase with the moment it belongs to.","correctChain":["5 pairs"],"scrambledTokens":["Sorry → You have hurt someone","Excuse me → You need to get past","Nice to meet you → A first introduction","What time is it? → You want the clock","See you tomorrow → You are leaving"],"explain":"Sorry apologises after the fact; excuse me asks before it happens — swapping them sounds rude.","match":{"pairs":[{"left":"Sorry","right":"You have hurt someone"},{"left":"Excuse me","right":"You need to get past"},{"left":"Nice to meet you","right":"A first introduction"},{"left":"What time is it?","right":"You want the clock"},{"left":"See you tomorrow","right":"You are leaving"}]}},{"kind":"listen","prompt":"Listen and type the friendliest question in English.","correctChain":["Where are you from"],"scrambledTokens":[],"explain":"Where + are + you + from — the auxiliary sits before the subject, which is what makes it a question.","listen":{"phrase":"Where are you from","answers":["Where are you from"]}},{"kind":"speak","prompt":"Say your goodbye for tomorrow, out loud.","correctChain":["See you tomorrow"],"scrambledTokens":[],"explain":"Natives squeeze it to \"see-ya-tuh-MOR-oh\" — the t is a flap, so it sounds like a soft d.","speak":{"phrase":"See you tomorrow","passScore":75}}],"position":2},
  {"id":"english-tenses","course_id":"english","title":"English Tenses Lab","theory":["Three tenses carry 90% of conversation: present simple for habits (She goes), present continuous for right now (I am eating), past simple for finished time (I went).","Spot the -s: he/she/it verbs add -s (go → goes). Spot the clock: now/right now → am/is/are + -ing. Spot yesterday → past form."],"questions":[{"prompt":"\"She ___ to school every day.\"","correctChain":["goes"],"scrambledTokens":["goes","go","going","gone"],"explain":"He/she/it + habit → add -s: she goes, he eats."},{"prompt":"Say \"I am eating now\":","correctChain":["I","am","eating"],"scrambledTokens":["eating","I","am","was"],"explain":"am + verb-ing = happening right now."},{"prompt":"\"Yesterday I ___ to the market.\"","correctChain":["went"],"scrambledTokens":["went","go","goes","going"],"explain":"Yesterday = finished past → went (not goed!)."},{"prompt":"Say \"They will come tomorrow\":","correctChain":["They","will","come"],"scrambledTokens":["come","They","will","came"],"explain":"will + base verb = future. No -s, no -ed."},{"prompt":"\"Right now\" signals which tense?","correctChain":["Present continuous"],"scrambledTokens":["Present continuous","Present simple","Past simple","Future"],"explain":"Right now / at the moment → am/is/are + -ing."},{"kind":"match","prompt":"Pair each sentence with the tense it uses.","correctChain":["4 pairs"],"scrambledTokens":["She goes to school every day → Present simple","I am eating now → Present continuous","Yesterday I went to the market → Past simple","They will come tomorrow → Future with will"],"explain":"The time word decides the tense: every day → -s, now → be + -ing, yesterday → past form, tomorrow → will.","match":{"pairs":[{"left":"She goes to school every day","right":"Present simple"},{"left":"I am eating now","right":"Present continuous"},{"left":"Yesterday I went to the market","right":"Past simple"},{"left":"They will come tomorrow","right":"Future with will"}]}},{"kind":"listen","prompt":"Listen and type the sentence about tomorrow.","correctChain":["They will come tomorrow"],"scrambledTokens":[],"explain":"will takes the base verb — no -s on comes, ever, after a modal.","listen":{"phrase":"They will come tomorrow","answers":["They will come tomorrow"]}},{"kind":"speak","prompt":"Say what you are doing right now, out loud.","correctChain":["I am eating now"],"scrambledTokens":[],"explain":"The -ing ending is a short nasal, not \"ee-ing\": eye-am-EE-ting-now.","speak":{"phrase":"I am eating now","passScore":75}}],"position":3},
  {"id":"english-quiz","course_id":"english","title":"English Checkpoint","theory":["Checkpoint: alphabet, articles, everyday phrases, questions, describing and comparing, health, and tenses from the full English course."],"questions":[{"prompt":"Fill the gap: \"___ hour\".","correctChain":["an"],"scrambledTokens":["an","a","the","no word needed"],"explain":"Hour starts with a vowel SOUND (silent h) → an hour."},{"prompt":"Say \"I am a student\":","correctChain":["I","am","a","student"],"scrambledTokens":["student","am","I","a"],"explain":"I + am + a + who you are."},{"prompt":"\"She ___ TV every evening.\"","correctChain":["watches"],"scrambledTokens":["watches","watch","watching","watched"],"explain":"She + habit → -es after -ch: she watches."},{"prompt":"Ask \"Where are you from?\":","correctChain":["Where","are","you","from"],"scrambledTokens":["from","are","Where","you"],"explain":"Word order matters: Where + are + you + from."},{"prompt":"The plural of \"box\" is…","correctChain":["boxes"],"scrambledTokens":["boxes","boxs","boxies","box"],"explain":"After -x, add -es: box → boxes, bus → buses."},{"prompt":"Fill the gap: “___ he call you yesterday?”","correctChain":["Did"],"scrambledTokens":["Did","Does","Do","Was"],"explain":"Yesterday is past, so the auxiliary is did + base verb: did he call."},{"prompt":"The comparative of “good” is…","correctChain":["better"],"scrambledTokens":["better","gooder","more good","best"],"explain":"Good is irregular: good → better → best. “Best” is the superlative, not the comparative."},{"prompt":"Give advice: “You shouldn’t drive.”","correctChain":["You","shouldn't","drive"],"scrambledTokens":["drive","You","shouldn't","should"],"explain":"Should + not contracts to shouldn’t, then the base verb: shouldn’t drive."},{"kind":"text","prompt":"You are at a clinic and need help. Type a polite sentence asking to see a doctor.","correctChain":["Could I see a doctor, please?"],"scrambledTokens":[],"explain":"Could I…? and May I…? are the polite request forms; please softens the ask. “I need a doctor” is direct but still acceptable in an emergency — add please for a routine appointment.","text":{"answers":["Could I see a doctor, please?","I need a doctor, please.","May I see a doctor, please?"],"misconceptions":{"I need doctor":"English needs an article: a doctor."}}},{"kind":"match","prompt":"Pair each word with the irregular form it hides.","correctChain":["4 pairs"],"scrambledTokens":["good → Its comparative is better","best → Its superlative","child → Its plural is children","box → Its plural is boxes"],"explain":"Good/better/best never take -er or -est, and after -x the plural adds -es, not a bare s.","match":{"pairs":[{"left":"good","right":"Its comparative is better"},{"left":"best","right":"Its superlative"},{"left":"child","right":"Its plural is children"},{"left":"box","right":"Its plural is boxes"}]}},{"kind":"listen","prompt":"Listen and type the question you would ask a new friend.","correctChain":["Where are you from"],"scrambledTokens":[],"explain":"Rising intonation on the last word marks it as a question — the words themselves never change.","listen":{"phrase":"Where are you from","answers":["Where are you from"]}},{"kind":"speak","prompt":"Give someone a piece of advice, out loud.","correctChain":["You shouldn't drive"],"scrambledTokens":[],"explain":"should-ent contracts hard: \"yoo SHUD-nt drive\" — the l in should is silent.","speak":{"phrase":"You shouldn't drive","passScore":75}}],"position":4},
  {"id":"english-greetings","course_id":"english","title":"Greetings & Small Talk","theory":["Sound natural from hello: “Hi, how is it going?” beats a flat “How are you?” — answer “Pretty good, you?” and the conversation flows. “Nice to meet you” is for first meetings; “Good to see you” is for friends you already know.","Small talk runs on three topics: weather (“Lovely day, is it not?”), weekend (“Any plans?”), and the classic closer “Well, good talking to you!”"],"questions":[{"prompt":"“How is it going?” is…","correctChain":["A casual hello"],"scrambledTokens":["A casual hello","A goodbye","A complaint","A question about travel"],"explain":"Answer it like “Pretty good!” — nobody wants a medical report."},{"prompt":"Greet someone for the first time:","correctChain":["Nice","to","meet","you"],"scrambledTokens":["you","Nice","meet","to","see"],"explain":"First meeting = Nice to meet you. Later = Good to SEE you."},{"prompt":"“Any plans for the weekend?” is…","correctChain":["Friendly small talk"],"scrambledTokens":["Friendly small talk","A job interview","A complaint","A farewell"],"explain":"Weekend plans: the universal friendly filler."},{"prompt":"Close a chat warmly:","correctChain":["Good","talking","to","you"],"scrambledTokens":["you","Good","to","talking","bye"],"explain":"“Good talking to you!” ends any chat on a smile."},{"prompt":"A friend you know says hello. You reply…","correctChain":["Good to see you!"],"scrambledTokens":["Good to see you!","Nice to meet you!","Who are you?","See you never!"],"explain":"Nice to MEET you is first-time only — then it is Good to SEE you."},{"kind":"match","prompt":"Pair each phrase with the moment it belongs to.","correctChain":["5 pairs"],"scrambledTokens":["How is it going → A casual hello that wants no report","Nice to meet you → Meeting someone for the first time","Good to see you → Greeting someone you already know","Any plans → Friendly small talk about the weekend","Good talking to you → Ending the conversation"],"explain":"English small talk is a sequence: open, ask lightly, then close. Nice to meet you only fits the very first link.","match":{"pairs":[{"left":"How is it going","right":"A casual hello that wants no report"},{"left":"Nice to meet you","right":"Meeting someone for the first time"},{"left":"Good to see you","right":"Greeting someone you already know"},{"left":"Any plans","right":"Friendly small talk about the weekend"},{"left":"Good talking to you","right":"Ending the conversation"}]}},{"kind":"listen","prompt":"Listen and type the casual greeting.","correctChain":["How is it going"],"scrambledTokens":[],"explain":"In fast speech this collapses toward howzitgoing — the sounds blur but the words never change.","listen":{"phrase":"How is it going","answers":["How is it going"],"misconceptions":{"How it is going":"The question keeps the verb before the subject: how IS IT going."}}},{"kind":"speak","prompt":"Greet someone you have just been introduced to, out loud.","correctChain":["Nice to meet you"],"scrambledTokens":[],"explain":"Link meet straight into you — meech-oo — and let the t of to disappear; no English speaker says each word separately here.","speak":{"phrase":"Nice to meet you","passScore":75}}],"position":5},
  {"id":"english-numbers-time","course_id":"english","title":"Numbers, Time & Dates","theory":["Count with confidence: eleven to twenty are rebels (eleven, twelve, thirteen…), then the pattern locks: twenty-one, thirty-two. Hundreds and thousands stack: two hundred and five, three thousand.","Tell time two ways: “half past three” or “three thirty”; “quarter to five” or “four forty-five”. Dates flip the order: Monday the 3rd of June. At, on, in: at 5pm, on Monday, in June."],"questions":[{"prompt":"“Twelve” is the number…","correctChain":["12"],"scrambledTokens":["12","20","2","11"],"explain":"Eleven 11, twelve 12 — then thirteen adds the -teen."},{"prompt":"Say “twenty-one”:","correctChain":["twenty-one"],"scrambledTokens":["twenty-one","twelve","twenty-two","thirty-one"],"explain":"Tens + units with a hyphen: twenty-one, forty-five."},{"prompt":"“Half past three” means…","correctChain":["3:30"],"scrambledTokens":["3:30","2:30","3:15","4:30"],"explain":"Half past = 30 minutes after the hour."},{"prompt":"Say the date “Monday the 3rd of June”:","correctChain":["Monday","the","3rd"],"scrambledTokens":["3rd","Monday","June","the"],"explain":"Day first, then the + ordinal: Monday the 3rd."},{"prompt":"“___ Monday” — pick the right preposition.","correctChain":["on"],"scrambledTokens":["on","at","in","by"],"explain":"On + days, at + clock times, in + months and years."},{"kind":"match","prompt":"Pair each number word with its value.","correctChain":["5 pairs"],"scrambledTokens":["Thirteen → 13","Twenty → 20","Thirty → 30","Hundred → 100","Thousand → 1000"],"explain":"Thirteen and thirty are the famous ear-trap: the stress sits on THIR-teen versus THREE-ty, and that is the only difference.","match":{"pairs":[{"left":"Thirteen","right":"13"},{"left":"Twenty","right":"20"},{"left":"Thirty","right":"30"},{"left":"Hundred","right":"100"},{"left":"Thousand","right":"1000"}]}},{"kind":"listen","prompt":"Listen and type the time being said.","correctChain":["It is half past three"],"scrambledTokens":[],"explain":"Half past three is 3:30 — thirty minutes after the hour named last.","listen":{"phrase":"It is half past three","answers":["It is half past three"],"misconceptions":{"It is three thirty":"That is the same minute spoken the other way; the recording used half past three."}}},{"kind":"speak","prompt":"Say the time just before five, out loud.","correctChain":["It is quarter to five"],"scrambledTokens":[],"explain":"Quarter takes a flap in American speech — KWER-er — and to reduces to a schwa: tuh five.","speak":{"phrase":"It is quarter to five","passScore":75}}],"position":6},
  {"id":"english-articles","course_id":"english","title":"Articles & Pointing Words","theory":["A/an introduces something new (“I saw a dog”), the points at something known (“The dog was big”). This/these stay close, that/those stand far: this book here, that shop over there.","An before vowel SOUNDS (an hour, an honest man), a elsewhere. These/those are simply the plurals of this/that."],"questions":[{"prompt":"“I saw ___ elephant.” Fill the gap.","correctChain":["an"],"scrambledTokens":["an","a","the","no word needed"],"explain":"Elephant starts with a vowel sound → an elephant."},{"prompt":"Point at a near book (one):","correctChain":["this","book"],"scrambledTokens":["book","that","this","those"],"explain":"This = near + singular. That = far + singular."},{"prompt":"“Close the door” uses “the” because…","correctChain":["Both speakers know which door"],"scrambledTokens":["Both speakers know which door","Doors are always “the”","It is the first mention","A and an are plural"],"explain":"The = shared knowledge. First mention takes a/an."},{"prompt":"Point at far shoes (many):","correctChain":["those","shoes"],"scrambledTokens":["shoes","these","those","that"],"explain":"Those = far + plural. These = near + plural."},{"prompt":"“___ honest man” — a or an?","correctChain":["an"],"scrambledTokens":["an","a","the","none"],"explain":"Honest starts with a vowel SOUND (silent h) → an honest man."},{"kind":"match","prompt":"Pair each pointing word with the job it does.","correctChain":["5 pairs"],"scrambledTokens":["A → Something new, before a consonant sound","An → Something new, before a vowel sound","The → Both speakers already know which one","This → One thing, near me","Those → Many things, far away"],"explain":"A and an answer sound, not spelling: a university, an hour. The answers shared knowledge.","match":{"pairs":[{"left":"A","right":"Something new, before a consonant sound"},{"left":"An","right":"Something new, before a vowel sound"},{"left":"The","right":"Both speakers already know which one"},{"left":"This","right":"One thing, near me"},{"left":"Those","right":"Many things, far away"}]}},{"kind":"listen","prompt":"Listen and type what was seen at the zoo.","correctChain":["I saw an elephant"],"scrambledTokens":[],"explain":"An glues onto the vowel of elephant — one running sound, anelephant — which is why learners often miss where the article ends.","listen":{"phrase":"I saw an elephant","answers":["I saw an elephant"]}},{"kind":"speak","prompt":"Describe a trustworthy person, out loud.","correctChain":["He is an honest man"],"scrambledTokens":[],"explain":"The h in honest is silent: AN-ONN-est. If you breathe the h, the article has to be a, and that is what gives the accent away.","speak":{"phrase":"He is an honest man","passScore":75}}],"position":7},
  {"id":"english-food-shopping","course_id":"english","title":"Food & Shopping","theory":["Shop in English: “How much is this?” opens, “Too expensive — any discount?” bargains, “I will take it” closes. Countables take many/few (many apples), uncountables take much/little (much rice).","Soften everything with please, excuse me, and sorry. “Could I have…?” beats “Give me…” in every country on Earth."],"questions":[{"prompt":"“How much is this?” asks for…","correctChain":["The price"],"scrambledTokens":["The price","The weight","The time","The name"],"explain":"How much = price. How many = quantity."},{"prompt":"Order politely: “a coffee, please”:","correctChain":["Could","I","have"],"scrambledTokens":["have","Could","Give","I"],"explain":"“Could I have…?” — polite in every shop on Earth."},{"prompt":"“Many apples” but “much rice” because…","correctChain":["Apples are countable, rice is not"],"scrambledTokens":["Apples are countable, rice is not","Rice is plural","Apples are cheap","Much is formal"],"explain":"Many/few + countables; much/little + uncountables."},{"prompt":"Say you will buy it:","correctChain":["I","will","take","it"],"scrambledTokens":["it","I","take","will"],"explain":"“I will take it” — the deal is done. Smile included."},{"prompt":"The price shocks you. Say…","correctChain":["That is too expensive!"],"scrambledTokens":["That is too expensive!","Give it free!","Too cheap!","No money!"],"explain":"Too + adjective states the problem; then bargain."},{"kind":"match","prompt":"Pair each shopping phrase with what it does.","correctChain":["5 pairs"],"scrambledTokens":["How much is this → Ask the price","Could I have a coffee → Order without demanding","Many apples → Countables take many","Much rice → Uncountables take much","I will take it → Close the deal"],"explain":"Could I have…? is the sentence that makes any shop staff smile; Give me… is the sentence that makes them wary.","match":{"pairs":[{"left":"How much is this","right":"Ask the price"},{"left":"Could I have a coffee","right":"Order without demanding"},{"left":"Many apples","right":"Countables take many"},{"left":"Much rice","right":"Uncountables take much"},{"left":"I will take it","right":"Close the deal"}]}},{"kind":"listen","prompt":"Listen and type the polite order.","correctChain":["Could I have a coffee please"],"scrambledTokens":[],"explain":"Could reduces to cud and I have runs as eye-uv — the politeness is in the words, not in the emphasis.","listen":{"phrase":"Could I have a coffee please","answers":["Could I have a coffee please"]}},{"kind":"speak","prompt":"Ask the price of something in your hand, out loud.","correctChain":["How much is this"],"scrambledTokens":[],"explain":"Much ends on the ch sound — muuch — and this keeps its final s voiceless; do not let it drift into \"thiz\".","speak":{"phrase":"How much is this","passScore":75}}],"position":8},
  {"id":"english-travel","course_id":"english","title":"Travel & Directions","theory":["Never get lost: “Excuse me, where is…?” opens every direction. Go straight on, turn left/right, it is on your left — then “How far is it?” and “Thank you very much!”","Book transport with “A ticket to…, please” and confirm “What time does it leave?” Single or return? Platform or gate? Ask twice, travel once."],"questions":[{"prompt":"“Turn left at the corner” means…","correctChain":["Go left when you reach the corner"],"scrambledTokens":["Go left when you reach the corner","Stop at the corner","Turn around now","Cross the road"],"explain":"Turn + direction + landmark: turn right at the bank."},{"prompt":"Ask where the station is:","correctChain":["Where","is","the","station"],"scrambledTokens":["station","Where","the","is","what"],"explain":"Where is the…? — the traveller’s master key."},{"prompt":"“It is on your right” means the place is…","correctChain":["To your right-hand side"],"scrambledTokens":["To your right-hand side","Behind you","Far away","Closed"],"explain":"On your left/right pins it to your own body."},{"prompt":"Buy a ticket politely:","correctChain":["A","ticket","to","Lagos"],"scrambledTokens":["Lagos","A","to","ticket","please"],"explain":"A ticket to + place + please. Add “return” for round trip."},{"prompt":"“What time does it leave?” asks for…","correctChain":["The departure time"],"scrambledTokens":["The departure time","The price","The platform","The arrival city"],"explain":"Leave = depart, arrive = get there. Mind both."},{"kind":"match","prompt":"Pair each direction phrase with what it tells you.","correctChain":["5 pairs"],"scrambledTokens":["Go straight on → Keep walking forward","Turn left at the corner → Change direction at a landmark","It is on your right → Pin the place to your own body","How far is it → Ask about distance","What time does it leave → Ask about departure"],"explain":"Directions use landmark grammar: turn + direction + at + place. Ask twice — distance and time are different questions.","match":{"pairs":[{"left":"Go straight on","right":"Keep walking forward"},{"left":"Turn left at the corner","right":"Change direction at a landmark"},{"left":"It is on your right","right":"Pin the place to your own body"},{"left":"How far is it","right":"Ask about distance"},{"left":"What time does it leave","right":"Ask about departure"}]}},{"kind":"listen","prompt":"Listen and type the question a traveller asks first.","correctChain":["Excuse me where is the station"],"scrambledTokens":[],"explain":"Excuse me opens the conversation; the station is the shared the because both speakers know which one is meant.","listen":{"phrase":"Excuse me where is the station","answers":["Excuse me where is the station"]}},{"kind":"speak","prompt":"Give someone the turn, out loud.","correctChain":["Turn left at the corner"],"scrambledTokens":[],"explain":"Turn starts with the r-colored vowel — TURN, tongue curled, no t-u split — and at the reduces to uh-theh.","speak":{"phrase":"Turn left at the corner","passScore":75}}],"position":9},
  {"id":"english-work","course_id":"english","title":"Work & Jobs","theory":["Talk shop: “I work as a…” names the role, “I work for…” names the company, “I am responsible for…” names the duty. Can = ability (“I can code”), could = past ability or polite request (“Could you help?”).","Meetings run on three verbs: suggest (I suggest we…), agree (I agree because…), decide (We decided to…). Opinions welcome, evidence required."],"questions":[{"prompt":"“I work ___ a nurse.” Fill the gap.","correctChain":["as"],"scrambledTokens":["as","for","to","like"],"explain":"As + role, for + company: I work as a nurse for City Hospital."},{"prompt":"State an ability:","correctChain":["I","can","type"],"scrambledTokens":["type","I","could","can"],"explain":"Can + base verb: I can drive, she can cook."},{"prompt":"“Could you help me?” is…","correctChain":["A polite request"],"scrambledTokens":["A polite request","Past ability","A complaint","An order"],"explain":"Could softens requests; can states raw ability."},{"prompt":"Name a duty: “reports every Friday”:","correctChain":["responsible","for","reports"],"scrambledTokens":["reports","responsible","of","for"],"explain":"Responsible for + -ing/duty: responsible for reports."},{"prompt":"“We decided to launch” means the team…","correctChain":["Made a decision"],"scrambledTokens":["Made a decision","Had an idea","Disagreed","Delayed"],"explain":"Decide + to + verb: decided to launch, agreed to wait."},{"kind":"match","prompt":"Pair each work phrase with what it names.","correctChain":["5 pairs"],"scrambledTokens":["I work as a nurse → The role","I work for City Hospital → The employer","I am responsible for reports → The duty","I can code → An ability you have now","Could you help me → A request, softened"],"explain":"As names the job, for names the company. Can states ability; could is either past ability or politeness.","match":{"pairs":[{"left":"I work as a nurse","right":"The role"},{"left":"I work for City Hospital","right":"The employer"},{"left":"I am responsible for reports","right":"The duty"},{"left":"I can code","right":"An ability you have now"},{"left":"Could you help me","right":"A request, softened"}]}},{"kind":"listen","prompt":"Listen and type where she works.","correctChain":["She works for City Hospital"],"scrambledTokens":[],"explain":"The -s on works is audible and obligatory: she WORKS. Dropping it is the single most common workplace-English slip.","listen":{"phrase":"She works for City Hospital","answers":["She works for City Hospital"]}},{"kind":"speak","prompt":"Name your duty at work, out loud.","correctChain":["I am responsible for reports"],"scrambledTokens":[],"explain":"Re-SPON-si-bl puts the weight on the second syllable, and responsible for runs together as one breath.","speak":{"phrase":"I am responsible for reports","passScore":75}}],"position":10},
  {"id":"english-past-stories","course_id":"english","title":"Past Stories","theory":["Tell what happened: past simple for finished events (I went, she bought), past continuous for the background scene (It was raining). Ago counts backwards: two days ago, a week ago.","Irregulars steal the show: go → went, eat → ate, see → saw, buy → bought. No -ed, no mercy — memorise the rebels."],"questions":[{"prompt":"“She ___ a new phone yesterday.”","correctChain":["bought"],"scrambledTokens":["bought","buy","buys","buyed"],"explain":"Buy → bought. Yesterday demands the true past form."},{"prompt":"Set the background scene:","correctChain":["It","was","raining"],"scrambledTokens":["raining","It","is","was"],"explain":"Was/were + -ing paints the background; simple past fires events."},{"prompt":"“Three days ago” means…","correctChain":["Three days before now"],"scrambledTokens":["Three days before now","In three days","For three days","Every three days"],"explain":"Ago always looks backwards from today."},{"prompt":"Say “We saw a lion”:","correctChain":["We","saw","a","lion"],"scrambledTokens":["lion","We","seed","saw","a"],"explain":"See → saw. Never “seed” — the rebels refuse -ed."},{"prompt":"“I was cooking when he arrived” — the cooking was…","correctChain":["Already in progress"],"scrambledTokens":["Already in progress","Finished first","Cancelled","Planned later"],"explain":"Past continuous = in progress; past simple = the interruption."},{"kind":"match","prompt":"Pair each irregular verb with its past form.","correctChain":["5 pairs"],"scrambledTokens":["Go → Went","Eat → Ate","See → Saw","Buy → Bought","It was raining → The background scene"],"explain":"The rebels share one rule: no -ed, ever. Bought is spelled with a silent -ght, which is why it looks longer than it sounds.","match":{"pairs":[{"left":"Go","right":"Went"},{"left":"Eat","right":"Ate"},{"left":"See","right":"Saw"},{"left":"Buy","right":"Bought"},{"left":"It was raining","right":"The background scene"}]}},{"kind":"listen","prompt":"Listen and type the story about the safari.","correctChain":["We saw a lion two days ago"],"scrambledTokens":[],"explain":"Saw is the past of see, and ago always counts backwards from today — two days ago, not two days from now.","listen":{"phrase":"We saw a lion two days ago","answers":["We saw a lion two days ago"]}},{"kind":"speak","prompt":"Say what someone bought yesterday, out loud.","correctChain":["She bought a new phone"],"scrambledTokens":[],"explain":"Bought is one syllable — bawt — with no g sound and no ht sound. Pronouncing the letters you see is the giveaway of a reader, not a speaker.","speak":{"phrase":"She bought a new phone","passScore":75}}],"position":11},
  {"id":"english-final","course_id":"english","title":"English Final Exam","theory":["Final exam: greetings, numbers, articles, shopping, travel, work, questions, describing and comparing, health, and past stories — the whole comprehensive course."],"questions":[{"prompt":"A stranger greets you with “How is it going?” You answer…","correctChain":["Pretty good, you?"],"scrambledTokens":["Pretty good, you?","I am going home.","It goes well.","What going?"],"explain":"Casual hello → casual bounce-back. Keep it light."},{"prompt":"Point at near shoes (many):","correctChain":["these","shoes"],"scrambledTokens":["shoes","those","these","that"],"explain":"These = near + plural. Those wave from far away."},{"prompt":"“She ___ TV every evening.”","correctChain":["watches"],"scrambledTokens":["watches","watch","watching","watched"],"explain":"She + habit → -es after -ch: she watches."},{"prompt":"Ask the price politely:","correctChain":["How","much","is","this"],"scrambledTokens":["this","How","is","much"],"explain":"How much is this? — then “Could I have…?” to close."},{"prompt":"“We ___ a lion on safari.” (past)","correctChain":["saw"],"scrambledTokens":["saw","see","seed","seen"],"explain":"See → saw. The rebels never take -ed."},{"prompt":"State your job: “a driver for City Cabs”:","correctChain":["work","as","a","driver"],"scrambledTokens":["driver","work","for","as","a"],"explain":"Work AS a role, FOR a company. Both halves win."},{"prompt":"Ask about the past: “Where did he go?”","correctChain":["Where","did","he","go"],"scrambledTokens":["go","Where","did","he","went"],"explain":"After did the verb stays in the base form: did he go, never did he went."},{"prompt":"Which sentence is correct?","correctChain":["This room is more comfortable than mine."],"scrambledTokens":["This room is more comfortable than mine.","This room is comfortabler than mine.","This room is most comfortable than mine.","This room is more comfortable that mine."],"explain":"Long adjectives take more … than; -er belongs to short ones like cheaper."},{"prompt":"Say “I am allergic to peanuts”:","correctChain":["I","am","allergic","to","peanuts"],"scrambledTokens":["peanuts","I","am","allergic","to","allergy"],"explain":"I am allergic to + the food. Allergy is the noun; allergic is the adjective."},{"prompt":"You arrive at a hotel with a reservation. Which check-in line is most professional?","correctChain":["Hi, I have a reservation under Chen."],"scrambledTokens":["Hi, I have a reservation under Chen.","Give me my room, Chen.","I am Chen and I want a room now.","Reservation? Chen. Room."],"explain":"Name, reservation, and the name it is under — complete, calm, and easy for the desk to check."},{"kind":"text","prompt":"Type the past tense of the verb “buy”.","correctChain":["bought"],"scrambledTokens":[],"explain":"Buy is irregular: buy → bought. “Buyed” is never correct, even though it sounds plausible.","text":{"answers":["bought"],"misconceptions":{"buyed":"Buy is irregular: the past tense is bought, not buyed."}}},{"kind":"match","prompt":"Pair each course item with the rule it proves.","correctChain":["5 pairs"],"scrambledTokens":["Bought → Irregular past, no -ed","Doesn’t work → After the auxiliary the verb stays bare","More comfortable → Long adjectives take more","An hour → An before a vowel sound, silent h counts","Allergic to peanuts → The preposition allergic demands"],"explain":"The final is five rules from five units — each one a mistake that non-native speakers still make after ten years.","match":{"pairs":[{"left":"Bought","right":"Irregular past, no -ed"},{"left":"Doesn’t work","right":"After the auxiliary the verb stays bare"},{"left":"More comfortable","right":"Long adjectives take more"},{"left":"An hour","right":"An before a vowel sound, silent h counts"},{"left":"Allergic to peanuts","right":"The preposition allergic demands"}]}},{"kind":"listen","prompt":"Listen and type the question about his home.","correctChain":["Where does he live"],"scrambledTokens":[],"explain":"Does carries the tense, so live stays bare: where DOES he LIVE. Two -s endings would be double-marking.","listen":{"phrase":"Where does he live","answers":["Where does he live"]}},{"kind":"speak","prompt":"Talk about yesterday, out loud.","correctChain":["I didn’t go to work"],"scrambledTokens":[],"explain":"Didn’t ends on a t and flows straight into go; after didn’t the verb is bare, so the past lives only in the auxiliary.","speak":{"phrase":"I didn’t go to work","passScore":75}}],"position":12},
  {"id":"english-questions","course_id":"english","title":"English Questions & Negatives","theory":["Present simple questions use do or does + base verb: Do you work here? Does she live in Nairobi? Past questions use did + base verb: Did they arrive?","Negatives use don’t, doesn’t or didn’t + base verb: I don’t drive. She doesn’t work here. They didn’t call. Never add -s or -ed after the auxiliary.","Question-word order is question word + auxiliary + subject + verb: Where does he live? Why did you call? Short answers repeat the auxiliary: Yes, I do. / No, she doesn’t."],"questions":[{"prompt":"“___ she live in Mombasa?”","correctChain":["Does"],"scrambledTokens":["Does","Do","Is","Did"],"explain":"She is third-person singular, so present simple takes does + live."},{"prompt":"Make it negative: “He works on Sundays.”","correctChain":["He","doesn't","work","on","Sundays"],"scrambledTokens":["He","doesn't","work","works","on","Sundays"],"explain":"The auxiliary carries the tense; work stays in the base form — doesn’t work."},{"prompt":"Choose the correct question.","correctChain":["Where does he live?"],"scrambledTokens":["Where does he live?","Where he does live?","Where does he lives?","Where do he live?"],"explain":"Question word + auxiliary + subject + base verb: where + does + he + live."},{"prompt":"Ask about the past: “Did you eat?”","correctChain":["Did","you","eat"],"scrambledTokens":["eat","Did","you","ate"],"explain":"After did, use the base verb: Did you eat? Never Did you ate?"},{"prompt":"“No, she doesn’t.” answers…","correctChain":["Does she…?"],"scrambledTokens":["Does she…?","Do she…?","Is she…?","Did she…?"],"explain":"Short answers echo the auxiliary and tense of the question — does in, doesn’t out."},{"kind":"match","prompt":"Pair each auxiliary with the sentence it belongs to.","correctChain":["5 pairs"],"scrambledTokens":["Do → Present question with you, we or they","Does → Present question with he, she or it","Did → Any past question","Don’t → Negative for I, you, we or they","Doesn’t → Negative for he, she or it"],"explain":"One tense marker per clause: does already carries the third person, so the main verb never adds an -s on top.","match":{"pairs":[{"left":"Do","right":"Present question with you, we or they"},{"left":"Does","right":"Present question with he, she or it"},{"left":"Did","right":"Any past question"},{"left":"Don’t","right":"Negative for I, you, we or they"},{"left":"Doesn’t","right":"Negative for he, she or it"}]}},{"kind":"listen","prompt":"Listen and type the question about her.","correctChain":["Does she live in Mombasa"],"scrambledTokens":[],"explain":"Does + she + live: the -es ending on does is the only place the third person appears.","listen":{"phrase":"Does she live in Mombasa","answers":["Does she live in Mombasa"]}},{"kind":"speak","prompt":"Ask why someone rang, out loud.","correctChain":["Why did you call"],"scrambledTokens":[],"explain":"Did you links as did-ya, and call keeps its pure final l — the past is already inside did, so no -ed anywhere.","speak":{"phrase":"Why did you call","passScore":75}}],"position":13},
  {"id":"english-comparing","course_id":"english","title":"English Describing & Comparing","theory":["Adjectives go before the noun and do not take a plural -s: two big dogs, a quiet room.","Short adjectives compare with -er + than (cheaper than, taller than); longer ones use more (more expensive than). Irregulars: good → better → best, bad → worse → worst.","as … as shows equality: She is as tall as her brother. Too means more than you want; enough means sufficient: too hot, warm enough."],"questions":[{"prompt":"Which phrase is correct?","correctChain":["two big dogs"],"scrambledTokens":["two big dogs","two bigs dogs","two dogs big","two big dog"],"explain":"The adjective stays singular and sits before the noun: two big dogs."},{"prompt":"Compare: “This bag is cheaper than that one.”","correctChain":["This","bag","is","cheaper","than","that","one"],"scrambledTokens":["cheaper","This","bag","is","than","that","one","cheapest"],"explain":"One-syllable adjective + -er + than: cheaper than. Cheapest is the superlative."},{"prompt":"“More expensive” is the comparative of…","correctChain":["expensive"],"scrambledTokens":["expensive","expensiver","most expensive","expense"],"explain":"Long adjectives take more, not -er: more expensive than."},{"prompt":"Say “She is as tall as her brother.”","correctChain":["She","is","as","tall","as","her","brother"],"scrambledTokens":["tall","She","is","as","taller","as","her","brother"],"explain":"as + adjective + as shows equality; taller belongs to a than comparison."},{"prompt":"“The soup is too hot” means…","correctChain":["It is hotter than I want"],"scrambledTokens":["It is hotter than I want","It is exactly right","It is not hot","It is the hottest soup"],"explain":"Too = more than is wanted. Enough would mean it is acceptable."},{"kind":"match","prompt":"Pair each comparative pattern with what it compares.","correctChain":["5 pairs"],"scrambledTokens":["Cheaper than → A short adjective taking -er","More expensive than → A long adjective taking more","As tall as → Equality — no difference at all","The best → The superlative of good","Worse than → The comparative of bad"],"explain":"One or two syllables take -er; three take more. Good and bad refuse both patterns entirely.","match":{"pairs":[{"left":"Cheaper than","right":"A short adjective taking -er"},{"left":"More expensive than","right":"A long adjective taking more"},{"left":"As tall as","right":"Equality — no difference at all"},{"left":"The best","right":"The superlative of good"},{"left":"Worse than","right":"The comparative of bad"}]}},{"kind":"listen","prompt":"Listen and type the comparison between the rooms.","correctChain":["This room is bigger than mine"],"scrambledTokens":[],"explain":"Big doubles the g before -er: bigger. The written -er is pronounced as a soft r, never a hard err.","listen":{"phrase":"This room is bigger than mine","answers":["This room is bigger than mine"]}},{"kind":"speak","prompt":"Say the two of you are equal height, out loud.","correctChain":["She is as tall as her brother"],"scrambledTokens":[],"explain":"The two as sounds reduce to uhz — uz-TALL-uhz — which is why the sentence sounds shorter than it looks.","speak":{"phrase":"She is as tall as her brother","passScore":75}}],"position":14},
  {"id":"english-health","course_id":"english","title":"English Health & Emergencies","theory":["Say where it hurts with have or hurt: I have a headache. My back hurts. It hurts here. I feel dizzy.","Ask for help: I need a doctor. Could you call an ambulance? Where is the nearest pharmacy? I’m allergic to peanuts.","Give advice with should + base verb: You should rest. You shouldn’t drive. Should never takes -s or -ed."],"questions":[{"prompt":"You have a bad headache. You say…","correctChain":["I have a headache."],"scrambledTokens":["I have a headache.","I am a headache.","My headache has me.","I do a headache."],"explain":"Use have for symptoms: I have a headache / a fever / a cough."},{"prompt":"Ask for a doctor: “I need a doctor.”","correctChain":["I","need","a","doctor"],"scrambledTokens":["doctor","I","need","a","medicine"],"explain":"I need a doctor — clear, direct, and understood everywhere."},{"prompt":"“I’m allergic to peanuts” means…","correctChain":["Peanuts make me ill"],"scrambledTokens":["Peanuts make me ill","I love peanuts","I am carrying peanuts","Peanuts are expensive"],"explain":"Allergic means the body reacts badly — avoid the food and tell the staff."},{"prompt":"Give advice: “You should rest.”","correctChain":["You","should","rest"],"scrambledTokens":["rest","You","should","rested"],"explain":"Should + base verb: should rest. Never should rested or should rests."},{"prompt":"Choose the polite emergency request.","correctChain":["Could you call an ambulance?"],"scrambledTokens":["Could you call an ambulance?","Call ambulance now!","You call ambulance.","Ambulance calling?"],"explain":"Could you…? is the polite request; the emergency itself stays urgent and clear."},{"kind":"match","prompt":"Pair each health phrase with what the clinician hears.","correctChain":["5 pairs"],"scrambledTokens":["I have a headache → A symptom you carry","My back hurts → Pain named by body part","You should rest → Advice","I am allergic to peanuts → A warning before any food","Could you call an ambulance → A request that stays polite under pressure"],"explain":"Have carries symptoms, hurt is the verb the body part owns, and should never takes -s or -ed.","match":{"pairs":[{"left":"I have a headache","right":"A symptom you carry"},{"left":"My back hurts","right":"Pain named by body part"},{"left":"You should rest","right":"Advice"},{"left":"I am allergic to peanuts","right":"A warning before any food"},{"left":"Could you call an ambulance","right":"A request that stays polite under pressure"}]}},{"kind":"listen","prompt":"Listen and type the question about medicine.","correctChain":["Where is the nearest pharmacy"],"scrambledTokens":[],"explain":"Nearest is near plus the superlative -est, and pharmacy stresses the first syllable: FARM-uh-see.","listen":{"phrase":"Where is the nearest pharmacy","answers":["Where is the nearest pharmacy"]}},{"kind":"speak","prompt":"Give someone firm advice, out loud.","correctChain":["You shouldn’t drive"],"scrambledTokens":[],"explain":"Shouldn’t loses the l-d sound entirely — SHUDDNT — and drive stays bare because should never takes a past form.","speak":{"phrase":"You shouldn’t drive","passScore":75}}],"position":15},
  {"id":"english-politeness","course_id":"english","title":"English Politeness & Apologies","theory":["English relies heavily on softening formulas. Use Excuse me to get someone’s attention or to pass by them, and I’m sorry to apologize for a mistake or express sympathy.","Could you please help me? is more polite than Can you help me?. When someone thanks you, reply warmly with You’re welcome, Don’t mention it, or No worries."],"questions":[{"prompt":"You need to squeeze past someone on the bus. What do you say?","correctChain":["Excuse me"],"scrambledTokens":["Excuse me","I’m sorry","Thank you","Goodbye"],"explain":"Excuse me asks for a path or gets attention. I’m sorry expresses regret after the fact."},{"prompt":"Say “Excuse me, could you help me?”:","correctChain":["Excuse","me","could","you","help","me"],"scrambledTokens":["help","Excuse","me","could","you","me","can"],"explain":"Could you help me is the courteous, polite request."},{"prompt":"“Don’t mention it” means…","correctChain":["You are welcome"],"scrambledTokens":["You are welcome","Do not speak to me","I forgot it","Please tell me"],"explain":"Don’t mention it is a friendly, gracious response to being thanked."},{"prompt":"Say “Thank you very much”:","correctChain":["Thank","you","very","much"],"scrambledTokens":["much","Thank","you","very","many"],"explain":"Much pairs with gratitude: Thank you very much."},{"prompt":"A stranger drops their book. You pick it up, and they thank you. What is a polite response?","correctChain":["You’re welcome"],"scrambledTokens":["You’re welcome","Excuse me","I am sorry","Never mind"],"explain":"You’re welcome is the universal, kind response to thank you."},{"kind":"match","prompt":"Pair each polite English phrase with the right moment.","correctChain":["5 pairs"],"scrambledTokens":["Excuse me → Getting attention or squeezing past","I’m so sorry → Apologizing for an accident","You’re welcome → Answering thank you","Could you please → Softening a request","After you → Letting someone pass first"],"explain":"Excuse me opens, I’m sorry apologizes, and You’re welcome answers gratitude.","match":{"pairs":[{"left":"Excuse me","right":"Getting attention or squeezing past"},{"left":"I’m so sorry","right":"Apologizing for an accident"},{"left":"You’re welcome","right":"Answering thank you"},{"left":"Could you please","right":"Softening a request"},{"left":"After you","right":"Letting someone pass first"}]}},{"kind":"listen","prompt":"Listen and type the sincere apology.","correctChain":["I am really sorry about that"],"scrambledTokens":[],"explain":"Really emphasizes your sincerity: I am really sorry about that.","listen":{"phrase":"I am really sorry about that","answers":["I am really sorry about that"]}},{"kind":"speak","prompt":"Say “Excuse me, could you help me?” out loud.","correctChain":["Excuse me could you help me"],"scrambledTokens":[],"explain":"ik-SKYOOZ mee cood yoo HELP mee: soft and courteous.","speak":{"phrase":"Excuse me could you help me","passScore":75}}],"position":16},
  {"id":"english-introductions","course_id":"english","title":"English Introductions & Origins","theory":["Introduce yourself with My name is... or I’m... . Ask someone: What’s your name? (casual) or May I ask your name? (formal).","Talk about your background with Where are you from? -> I’m from London / I come from Kenya. Talk about residence with Where do you live? -> I live in New York. Close with Nice to meet you or Pleased to meet you."],"questions":[{"prompt":"“Where are you from?” asks about…","correctChain":["Your country or home town"],"scrambledTokens":["Your country or home town","Your job","Where you are going","Your hotel"],"explain":"Where are you from asks for your origin or nationality."},{"prompt":"Say “My name is Sarah”:","correctChain":["My","name","is","Sarah"],"scrambledTokens":["Sarah","My","name","is","Your"],"explain":"My name is + name is the classic introduction."},{"prompt":"“Nice to meet you” is said…","correctChain":["When being introduced to someone new"],"scrambledTokens":["When being introduced to someone new","When leaving for good","When ordering food","When asking directions"],"explain":"Nice to meet you is the universal handshake phrase."},{"prompt":"Say “I live in London”:","correctChain":["I","live","in","London"],"scrambledTokens":["London","I","live","in","from"],"explain":"Live in + city: I live in London. From is for origin."},{"prompt":"You are from Canada. How do you answer “Where are you from?”","correctChain":["I am from Canada"],"scrambledTokens":["I am from Canada","I live in Canada","My name is Canada","I like Canada"],"explain":"I am from Canada directly answers the question."},{"kind":"match","prompt":"Pair each introduction phrase with its role.","correctChain":["5 pairs"],"scrambledTokens":["My name is → Stating your name","I am from → Stating where you were born","I live in → Stating your current home","Nice to meet you → Polite greeting on meeting","What is your name → Asking for someone’s name"],"explain":"Name, origin, and residence are the three anchors of any personal introduction.","match":{"pairs":[{"left":"My name is","right":"Stating your name"},{"left":"I am from","right":"Stating where you were born"},{"left":"I live in","right":"Stating your current home"},{"left":"Nice to meet you","right":"Polite greeting on meeting"},{"left":"What is your name","right":"Asking for someone’s name"}]}},{"kind":"listen","prompt":"Listen and type the friendly introduction line.","correctChain":["It is nice to meet you"],"scrambledTokens":[],"explain":"It is nice to meet you is the full, unabbreviated greeting.","listen":{"phrase":"It is nice to meet you","answers":["It is nice to meet you"]}},{"kind":"speak","prompt":"Say where you come from, out loud in English.","correctChain":["I am from the United States"],"scrambledTokens":[],"explain":"I am from the yoo-NY-ted STATES: clear and natural.","speak":{"phrase":"I am from the United States","passScore":75}}],"position":17},
  {"id":"english-money","course_id":"english","title":"English Shopping & Money","theory":["In stores, ask prices with How much is this? or How much does it cost?.","Express opinions with It’s too expensive or It’s a good deal / affordable. At checkout: Can I pay by card? or In cash. At a café, ask Could we have the bill, please? (UK) or The check, please (US). Tip with Keep the change."],"questions":[{"prompt":"“How much does it cost?” asks…","correctChain":["The price of an item"],"scrambledTokens":["The price of an item","The time of day","The store hours","Where the item is"],"explain":"How much asks about price or quantity."},{"prompt":"Say “It is too expensive” in English:","correctChain":["It","is","too","expensive"],"scrambledTokens":["expensive","It","is","too","cheap"],"explain":"Too means more than acceptable: too expensive."},{"prompt":"How do you ask to pay with a credit card?","correctChain":["Can I pay by card?"],"scrambledTokens":["Can I pay by card?","Do you take checks?","Where is the cashier?","Is it free?"],"explain":"Pay by card is the standard phrasing."},{"prompt":"Ask for the bill at a restaurant politely:","correctChain":["Could","we","have","the","bill","please"],"scrambledTokens":["please","Could","we","have","the","bill","can"],"explain":"Could we have the bill, please is the polite British/international dining phrase."},{"prompt":"“Keep the change” means…","correctChain":["You are leaving the extra coins as a tip"],"scrambledTokens":["You are leaving the extra coins as a tip","You want all coins back","The coins are broken","You have no money"],"explain":"Keep the change tells the server or driver they may retain the change as a gratuity."},{"kind":"match","prompt":"Pair each shopping phrase with what you are asking.","correctChain":["5 pairs"],"scrambledTokens":["How much is this → Asking the price","Too expensive → Evaluating the cost as high","By card → Payment method","In cash → Paying with paper and coins","The bill please → Asking to pay the restaurant"],"explain":"How much asks the price, expensive evaluates it, and by card chooses the payment.","match":{"pairs":[{"left":"How much is this","right":"Asking the price"},{"left":"Too expensive","right":"Evaluating the cost as high"},{"left":"By card","right":"Payment method"},{"left":"In cash","right":"Paying with paper and coins"},{"left":"The bill please","right":"Asking to pay the restaurant"}]}},{"kind":"listen","prompt":"Listen and type the customer’s price question.","correctChain":["How much is this jacket"],"scrambledTokens":[],"explain":"How much is + the specific noun: How much is this jacket?","listen":{"phrase":"How much is this jacket","answers":["How much is this jacket"]}},{"kind":"speak","prompt":"Ask for the restaurant bill, out loud.","correctChain":["Could we have the bill please"],"scrambledTokens":[],"explain":"cood wee hav thuh BIL pleez: soft, courteous, and polite.","speak":{"phrase":"Could we have the bill please","passScore":75}}],"position":18}
